const DEFAULT_EMPLOYEE_DISPLAY_COLUMNS = Object.freeze([
  "color", "personnel_number", "name", "nickname", "position", "assignment", "workload", "preferred_day", "fixed_days", "status",
]);
const employeeDisplayCollator = new Intl.Collator("de-AT", { numeric: true, sensitivity: "base" });

function availableEmployeeDisplayColumns() {
  const localAccess = !state.portalStatus?.portalEnabled;
  const fieldAccess = state.portalSession?.user?.personnelRecordAccess?.fieldAccess || {};
  return EMPLOYEE_DISPLAY_COLUMNS.filter((column) => !column.fieldKey || localAccess || ["read", "write"].includes(fieldAccess[column.fieldKey]));
}

function normalizeEmployeeDisplayColumns(columns) {
  const available = new Set(availableEmployeeDisplayColumns().map((column) => column.id));
  const submitted = Array.isArray(columns) ? columns : [];
  const normalized = [...new Set(submitted.map(String).filter((column) => available.has(column)))];
  if (normalized.length) return normalized;
  const defaults = DEFAULT_EMPLOYEE_DISPLAY_COLUMNS.filter((column) => available.has(column));
  return defaults.length ? defaults : ["name"];
}

function normalizeEmployeeDisplaySort(sort = {}) {
  const known = new Set(EMPLOYEE_DISPLAY_COLUMNS.map((column) => column.id));
  const key = known.has(String(sort?.key || "")) ? String(sort.key) : "personnel_number";
  return { key, direction: sort?.direction === "desc" ? "desc" : "asc" };
}

function employeeDisplayProfileValue(employee, fieldKey) {
  return String(fieldKey || "").split(".").reduce((value, segment) => value && typeof value === "object" ? value[segment] : "", employee?.personnel_display || "") ?? "";
}

function employeeDisplayRawValue(employee, columnId) {
  const column = EMPLOYEE_DISPLAY_COLUMNS.find((entry) => entry.id === columnId);
  if (column?.fieldKey) return employeeDisplayProfileValue(employee, column.fieldKey);
  if (columnId === "color") return employee.color || "";
  if (columnId === "personnel_number") return employee.personnel_number || "";
  if (columnId === "name") return employee.full_name || employee.nickname || "";
  if (columnId === "nickname") return employee.nickname || "";
  if (columnId === "position") return employee.position_name || "";
  if (columnId === "cost_center") return [employee.cost_center_code, employee.cost_center_name].filter(Boolean).join(" · ");
  if (columnId === "assignment") return [employee.home_location_name || employee.home_location_id, employee.preferred_department_name].filter(Boolean).join(" · ");
  if (columnId === "location") return employee.home_location_name || employee.home_location_id || "";
  if (columnId === "department") return employee.preferred_department_name || "";
  if (columnId === "workload") return Number(employee.contracted_hours || 0);
  if (columnId === "preferred_day") return preferredDayLabels[employee.preferred_day_off] || "";
  if (columnId === "fixed_days") return formatFixedWorkdays(employee.fixed_workdays);
  if (columnId === "status") return employee.active ? "Aktiv" : "Inaktiv";
  return "";
}

function employeeDisplayCell(employee, column) {
  const raw = employeeDisplayRawValue(employee, column.id);
  if (column.id === "color") return `<span class="employee-color" style="background:${escapeHtmlAttribute(employee.color || "#6b7b75")}"></span>`;
  if (column.id === "personnel_number") return `<strong>${escapeHtml(raw || "–")}</strong>`;
  if (column.id === "status") return `<span class="status-badge ${employee.active ? "" : "inactive"}">${employee.active ? "Aktiv" : "Inaktiv"}</span>`;
  if (column.id === "cost_center") return `<span class="status-badge ${employee.cost_center_id ? "" : "warning"}">${escapeHtml(raw || "Nicht zugeordnet")}</span>`;
  if (column.id === "workload") return `${escapeHtml(String(employee.contracted_hours || 0).replace(".", ","))} h · ${Number(employee.target_workdays_per_week || 5)} T.`;
  if (column.date) return raw ? escapeHtml(formatDate(String(raw))) : "–";
  return escapeHtml(String(raw || "–"));
}

function sortedEmployeesForDisplay(employees) {
  const sort = normalizeEmployeeDisplaySort(state.employeeDisplaySort);
  const direction = sort.direction === "desc" ? -1 : 1;
  return employees.slice().sort((left, right) => {
    const result = employeeDisplayCollator.compare(String(employeeDisplayRawValue(left, sort.key) ?? ""), String(employeeDisplayRawValue(right, sort.key) ?? ""));
    if (result) return result * direction;
    return employeeDisplayCollator.compare(String(left.personnel_number || ""), String(right.personnel_number || ""));
  });
}

function employeeDisplayHeader(columns) {
  const sort = normalizeEmployeeDisplaySort(state.employeeDisplaySort);
  return `<tr>${columns.map((column) => {
    const active = sort.key === column.id;
    const ariaSort = active ? (sort.direction === "asc" ? "ascending" : "descending") : "none";
    const indicator = active ? `<span aria-hidden="true">${sort.direction === "asc" ? "↑" : "↓"}</span>` : "";
    return `<th aria-sort="${ariaSort}"><button type="button" class="employee-sort-button" data-employee-sort="${escapeHtmlAttribute(column.id)}">${escapeHtml(column.label)}${indicator}</button></th>`;
  }).join("")}<th><span class="visually-hidden">Aktionen</span></th></tr>`;
}

function applyEmployeeDisplayTableLayout(table, columns) {
  if (!table) return;
  table.style.setProperty("--employee-column-count", String(columns.length + 1));
}

function renderEmployeeColumnOptions() {
  if (!elements.employeeColumnOptions) return;
  const selected = new Set(normalizeEmployeeDisplayColumns(state.employeeDisplayColumns));
  const grouped = availableEmployeeDisplayColumns().reduce((result, column) => {
    if (!result.has(column.group)) result.set(column.group, []);
    result.get(column.group).push(column);
    return result;
  }, new Map());
  elements.employeeColumnOptions.innerHTML = [...grouped.entries()].map(([group, columns]) => `<fieldset><legend>${escapeHtml(group)}</legend><div>${columns.map((column) => `<label class="employee-column-option"><input type="checkbox" name="employeeDisplayColumn" value="${escapeHtmlAttribute(column.id)}" ${selected.has(column.id) ? "checked" : ""} /><span>${escapeHtml(column.label)}</span></label>`).join("")}</div></fieldset>`).join("");
}

function openEmployeeColumnsModal() {
  state.employeeDisplayColumns = normalizeEmployeeDisplayColumns(state.employeeDisplayColumns);
  renderEmployeeColumnOptions();
  elements.employeeColumnsModal?.showModal();
}

function apiList(payload, keys = []) {
  if (Array.isArray(payload)) return payload;
  for (const key of keys) {
    if (Array.isArray(payload?.[key])) return payload[key];
  }
  return [];
}

function normalizedActive(value, fallback = true) {
  if (value === undefined || value === null) return fallback;
  return ![false, 0, "0"].includes(value);
}

function normalizeCostCenterType(item = {}) {
  const positions = apiList(item, ["positions"]).map((position) => ({
    ...position,
    id: String(position.id ?? position.position_id ?? position.positionId ?? ""),
    name: String(position.name ?? position.position_name ?? position.positionName ?? ""),
    builtin: normalizedActive(position.builtin, false),
    sort_order: Number(position.sort_order ?? position.sortOrder ?? 0),
  }));
  const submittedPositionIds = item.positionIds ?? item.position_ids;
  const positionIds = Array.isArray(submittedPositionIds)
    ? submittedPositionIds.map((id) => String(id))
    : positions.map((position) => position.id);
  return {
    ...item,
    id: String(item.id ?? item.cost_center_type_id ?? item.costCenterTypeId ?? item.code ?? ""),
    code: String(item.code ?? item.type_code ?? item.typeCode ?? ""),
    name: String(item.name ?? item.label ?? item.type_name ?? item.typeName ?? ""),
    description: String(item.description ?? ""),
    isBranch: normalizedActive(item.isBranch ?? item.is_branch, false),
    active: normalizedActive(item.active),
    builtin: normalizedActive(item.builtin, false),
    sortOrder: Number(item.sortOrder ?? item.sort_order ?? 0),
    positionIds,
    positions,
    costCenterCount: Number(item.costCenterCount ?? item.cost_center_count ?? 0),
    activeCostCenterCount: Number(item.activeCostCenterCount ?? item.active_cost_center_count ?? 0),
    locationCount: Number(item.locationCount ?? item.location_count ?? 0),
  };
}

function normalizeCostCenter(item = {}) {
  const typeId = String(item.typeId ?? item.cost_center_type_id ?? item.costCenterTypeId ?? item.type ?? "");
  const typeCode = String(item.typeCode ?? item.cost_center_type_code ?? item.costCenterTypeCode ?? item.type ?? "other");
  return {
    ...item,
    id: item.id ?? item.cost_center_id ?? item.costCenterId ?? item.code ?? "",
    code: String(item.code ?? item.cost_center_code ?? item.costCenterCode ?? ""),
    name: String(item.name ?? item.cost_center_name ?? item.costCenterName ?? ""),
    type: typeCode,
    typeId,
    typeCode,
    typeName: String(item.typeName ?? item.cost_center_type_name ?? item.costCenterTypeName ?? ""),
    isBranch: normalizedActive(
      item.isBranch ?? item.cost_center_type_is_branch ?? item.costCenterTypeIsBranch,
      typeCode === "branch",
    ),
    typeActive: normalizedActive(item.typeActive ?? item.cost_center_type_active ?? item.costCenterTypeActive),
    description: String(item.description ?? ""),
    active: normalizedActive(item.active),
    employee_count: Number(item.employee_count ?? item.employeeCount ?? 0),
    location_count: Number(item.location_count ?? item.locationCount ?? 0),
    locationId: String(item.locationId ?? item.location_id ?? ""),
    locationName: String(item.locationName ?? item.location_name ?? ""),
  };
}

function normalizePersonnelDirectoryEmployee(item = {}) {
  const personnelNumber = String(item.personnel_number ?? item.personnelNumber ?? item.employee_number ?? item.employeeNumber ?? "");
  const scoped = state.allEmployees.find((employee) => String(employee.personnel_number) === personnelNumber) || {};
  const merged = { ...scoped, ...item };
  return {
    ...merged,
    personnel_number: personnelNumber,
    full_name: String(merged.full_name ?? merged.fullName ?? ""),
    nickname: String(merged.nickname ?? ""),
    position_name: String(merged.position_name ?? merged.positionName ?? ""),
    position_id: merged.position_id ?? merged.positionId ?? "",
    cost_center_id: merged.cost_center_id ?? merged.costCenterId ?? "",
    cost_center_code: String(merged.cost_center_code ?? merged.costCenterCode ?? ""),
    cost_center_name: String(merged.cost_center_name ?? merged.costCenterName ?? ""),
    cost_center_type: String(merged.cost_center_type ?? merged.costCenterType ?? ""),
    home_location_id: merged.home_location_id ?? merged.homeLocationId ?? "",
    home_location_name: String(merged.home_location_name ?? merged.homeLocationName ?? ""),
    preferred_department_id: merged.preferred_department_id ?? merged.preferredDepartmentId ?? "",
    preferred_department_name: String(merged.preferred_department_name ?? merged.preferredDepartmentName ?? ""),
    contracted_hours: Number(merged.contracted_hours ?? merged.contractedHours ?? 0),
    target_workdays_per_week: Number(merged.target_workdays_per_week ?? merged.targetWorkdaysPerWeek ?? 5),
    active: normalizedActive(merged.active),
  };
}

function costCenterTypeByKey(value) {
  const key = String(value || "");
  return state.costCenterTypes.find((entry) => entry.id === key || entry.code === key) || null;
}

function costCenterTypeLabel(type) {
  const value = typeof type === "object" ? type?.typeId || type?.typeCode || type?.type : type;
  const match = costCenterTypeByKey(value);
  if (match) return match.name;
  if (typeof type === "object" && type?.typeName) return type.typeName;
  return ({ branch: "Filiale", administration: "Verwaltung", production: "Produktion", other: "Sonstige" })[value] || "Sonstige";
}

async function loadPersonnelAdministration({ force = false } = {}) {
  if (!canOpenPersonnelAdministrationView() || state.personnelAdministrationLoading) return;
  if (state.personnelAdministrationLoaded && !force) {
    renderPersonnelAdministration();
    return;
  }
  state.personnelAdministrationLoading = true;
  if (elements.personnelDirectoryBody) elements.personnelDirectoryBody.innerHTML = '<tr><td colspan="8">Personalstammdaten werden geladen.</td></tr>';
  try {
    const [directoryPayload, costCenterPayload] = await Promise.all([
      canReadCentralPersonnel() ? api("/api/personnel-directory") : Promise.resolve([]),
      canReadCostCenters()
        ? api("/api/cost-centers?includeInactive=1").catch((error) => {
          if ([403, 404].includes(error.status)) return [];
          throw error;
        })
        : Promise.resolve([]),
    ]);
    state.personnelDirectory = apiList(directoryPayload, ["employees", "items", "personnel"])
      .map(normalizePersonnelDirectoryEmployee);
    state.costCenters = apiList(costCenterPayload, ["costCenters", "cost_centers", "items"])
      .map(normalizeCostCenter);
    const typeItems = Array.isArray(costCenterPayload)
      ? []
      : apiList(costCenterPayload, ["types", "costCenterTypes", "cost_center_types"]);
    if (typeItems.length) state.costCenterTypes = typeItems.map(normalizeCostCenterType);
    const positionItems = Array.isArray(costCenterPayload)
      ? []
      : apiList(costCenterPayload, ["positions"]);
    if (positionItems.length) state.positions = positionItems;
    state.personnelAdministrationLoaded = true;
    renderPersonnelAdministration();
  } catch (error) {
    if (elements.personnelDirectoryBody) elements.personnelDirectoryBody.innerHTML = `<tr><td colspan="8">${escapeHtml(error.message)}</td></tr>`;
    if (elements.costCenterList) elements.costCenterList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  } finally {
    state.personnelAdministrationLoading = false;
  }
}

function filteredPersonnelDirectory() {
  const search = state.personnelDirectorySearch.trim().toLocaleLowerCase("de-AT");
  const costCenter = state.personnelDirectoryCostCenterFilter;
  const status = state.personnelDirectoryStatusFilter;
  return state.personnelDirectory.filter((employee) => {
    if (status === "active" && !employee.active) return false;
    if (status === "inactive" && employee.active) return false;
    if (status === "unassigned" && employee.cost_center_id) return false;
    if (costCenter && String(employee.cost_center_id) !== String(costCenter)) return false;
    if (!search) return true;
    return [employee.personnel_number, employee.full_name, employee.nickname, employee.position_name,
      employee.cost_center_code, employee.cost_center_name, employee.home_location_name, employee.preferred_department_name]
      .some((value) => String(value || "").toLocaleLowerCase("de-AT").includes(search));
  }).sort((left, right) => String(left.personnel_number).localeCompare(String(right.personnel_number), "de-AT", { numeric: true, sensitivity: "base" }));
}

function renderPersonnelAdministrationSummary() {
  if (!elements.personnelAdministrationSummary) return;
  const total = state.personnelDirectory.length;
  const active = state.personnelDirectory.filter((employee) => employee.active).length;
  const inactive = total - active;
  const unassigned = state.personnelDirectory.filter((employee) => !employee.cost_center_id).length;
  elements.personnelAdministrationSummary.innerHTML = [
    ["Beschäftigte", total, "gesamt"],
    ["Aktiv", active, "aktuelle Personalstämme"],
    ["Inaktiv", inactive, "historisch erhalten"],
    ["Ohne Kostenstelle", unassigned, unassigned ? "Zuordnung nachpflegen" : "vollständig zugeordnet"],
  ].map(([label, value, note], index) => `<article class="personnel-administration-stat ${index === 3 && value ? "warning" : ""}"><span>${escapeHtml(label)}</span><strong>${Number(value)}</strong><small>${escapeHtml(note)}</small></article>`).join("");
}

function renderPersonnelDirectory() {
  if (!elements.personnelDirectoryBody) return;
  const currentCostCenter = state.personnelDirectoryCostCenterFilter;
  elements.personnelDirectoryCostCenterFilter.innerHTML = `<option value="">Alle Kostenstellen</option>${state.costCenters
    .slice().sort((left, right) => left.code.localeCompare(right.code, "de-AT", { numeric: true }))
    .map((center) => `<option value="${escapeHtmlAttribute(String(center.id))}">${escapeHtml(`${center.code} · ${center.name}${center.active ? "" : " · inaktiv"}`)}</option>`).join("")}`;
  if ([...elements.personnelDirectoryCostCenterFilter.options].some((option) => option.value === String(currentCostCenter))) {
    elements.personnelDirectoryCostCenterFilter.value = String(currentCostCenter);
  } else {
    state.personnelDirectoryCostCenterFilter = "";
  }
  const columns = normalizeEmployeeDisplayColumns(state.employeeDisplayColumns)
    .map((id) => availableEmployeeDisplayColumns().find((column) => column.id === id))
    .filter(Boolean);
  state.employeeDisplayColumns = columns.map((column) => column.id);
  if (elements.personnelDirectoryHead) elements.personnelDirectoryHead.innerHTML = employeeDisplayHeader(columns);
  applyEmployeeDisplayTableLayout(elements.personnelDirectoryTable, columns);
  const rows = sortedEmployeesForDisplay(filteredPersonnelDirectory());
  const canEdit = canWriteCentralPersonnel();
  const canOpenRecord = personnelRecordAvailableInUi();
  const canOpenProfile = canOpenEmployeeProfileFoundation();
  elements.personnelDirectoryBody.innerHTML = rows.length ? rows.map((employee) => {
    const actions = [
      canOpenProfile ? `<button type="button" class="edit-button" data-central-employee-profile="${escapeHtmlAttribute(employee.personnel_number)}">Profil</button>` : "",
      canEdit ? `<button type="button" class="edit-button" data-central-edit-employee="${escapeHtmlAttribute(employee.personnel_number)}">Stammdaten</button>` : "",
      canOpenRecord ? `<button type="button" class="edit-button" data-central-personnel-record="${escapeHtmlAttribute(employee.personnel_number)}">Personalakt</button>` : "",
    ].filter(Boolean).join("");
    return `<tr class="${employee.cost_center_id ? "" : "personnel-directory-unassigned"}">
      ${columns.map((column) => `<td data-label="${escapeHtmlAttribute(column.label)}">${employeeDisplayCell(employee, column)}</td>`).join("")}
      <td data-label="Aktionen"><span class="table-actions">${actions || "–"}</span></td>
    </tr>`;
  }).join("") : `<tr><td colspan="${columns.length + 1}" class="personnel-directory-empty">Keine passenden Mitarbeitenden gefunden.</td></tr>`;
}

