const EMPLOYEE_PROFILE_DOCUMENT_STATUSES = Object.freeze({
  active: "Aktiv",
  retention_review: "Aufbewahrung prüfen",
  archived: "Archiviert",
});

function employeeProfileMasterDataFieldFingerprint(fieldKeys) {
  return [...new Set((Array.isArray(fieldKeys) ? fieldKeys : []).map(String).filter(Boolean))]
    .sort((left, right) => left.localeCompare(right, "en"))
    .join("\0");
}

function employeeProfileIsOpen() {
  return state.employeeProfileOpen === true;
}

function normalizeEmployeeProfileHeader(payload, expectedEmployeeNumber, capability, tabKey) {
  if (!payload || typeof payload !== "object"
    || payload.capabilities?.[capability] !== true
    || payload.tabs?.[tabKey]?.available !== true) {
    throw new Error("Dieser Profilbereich ist nicht freigegeben.");
  }
  const profile = payload.profile;
  const employeeNumber = String(profile?.employeeNumber || "").trim();
  const displayName = String(profile?.displayName || "").trim();
  if (!employeeNumber || employeeNumber !== String(expectedEmployeeNumber || "").trim()
    || !displayName || typeof profile?.active !== "boolean") {
    throw new Error("Die Profilprojektion ist unvollständig.");
  }
  const organization = profile.organization && typeof profile.organization === "object"
    ? profile.organization
    : {};
  return {
    employeeNumber,
    displayName,
    active: profile.active,
    organization: {
      positionName: String(organization.positionName || "").trim(),
      costCenter: {
        code: String(organization.costCenter?.code || "").trim(),
        name: String(organization.costCenter?.name || "").trim(),
      },
      location: {
        id: String(organization.location?.id || "").trim(),
        name: String(organization.location?.name || "").trim(),
      },
      department: {
        id: String(organization.department?.id || "").trim(),
        name: String(organization.department?.name || "").trim(),
      },
    },
  };
}

function normalizeEmployeeProfileAccess(payload) {
  return {
    tabs: Object.fromEntries(EMPLOYEE_PROFILE_TABS.map(({ id }) => [id, {
      available: payload.tabs?.[id]?.available === true && (
        id === "overview" ? payload.capabilities?.canReadOverview === true
          : id === "masterData" ? payload.capabilities?.canReadMasterOrg === true
            : id === "documents" ? payload.capabilities?.canReadDocuments === true
              : id === "onboarding" ? payload.capabilities?.canReadOnboardingPreview === true
                : id === "offboarding"
                  ? payload.capabilities?.canReadOffboardingConfidential === true
                  : false
      ),
    }])),
    capabilities: {
      canReadOverview: payload.capabilities?.canReadOverview === true,
      canReadMasterOrg: payload.capabilities?.canReadMasterOrg === true,
      canReadDocuments: payload.capabilities?.canReadDocuments === true,
      canReadOnboardingPreview: payload.capabilities?.canReadOnboardingPreview === true,
      canStartOnboarding: payload.capabilities?.canStartOnboarding === true,
      canCloseOnboarding: payload.capabilities?.canCloseOnboarding === true,
      canReadOffboardingConfidential:
        payload.capabilities?.canReadOffboardingConfidential === true,
      canPrepareOffboarding: payload.capabilities?.canPrepareOffboarding === true,
      canApproveOffboardingException:
        payload.capabilities?.canApproveOffboardingException === true,
      canReleaseOffboardingCommunication:
        payload.capabilities?.canReleaseOffboardingCommunication === true,
      canConfirmOffboardingInformation:
        payload.capabilities?.canConfirmOffboardingInformation === true,
      canExecuteOffboarding: payload.capabilities?.canExecuteOffboarding === true,
      canCloseOffboarding: payload.capabilities?.canCloseOffboarding === true,
      canReadOffboardingConfidentialAudit:
        payload.capabilities?.canReadOffboardingConfidentialAudit === true,
    },
  };
}

function normalizeEmployeeProfileOverview(payload, expectedEmployeeNumber) {
  return {
    ...normalizeEmployeeProfileHeader(payload, expectedEmployeeNumber, "canReadOverview", "overview"),
    ...normalizeEmployeeProfileAccess(payload),
  };
}

function employeeProfileProjectedPath(source, path) {
  let value = source;
  for (const segment of String(path || "").split(".")) {
    if (!value || typeof value !== "object" || !Object.hasOwn(value, segment)) {
      return { available: false, value: null };
    }
    value = value[segment];
  }
  return { available: true, value };
}

function normalizeEmployeeProfileMasterData(payload, expectedEmployeeNumber) {
  const profile = normalizeEmployeeProfileHeader(
    payload,
    expectedEmployeeNumber,
    "canReadMasterOrg",
    "masterData",
  );
  const source = payload.masterData && typeof payload.masterData === "object"
    && !Array.isArray(payload.masterData) ? payload.masterData : {};
  const fields = EMPLOYEE_PROFILE_MASTER_DATA_FIELDS.flatMap((definition) => {
    const projected = employeeProfileProjectedPath(source, definition.key);
    if (!projected.available || projected.value === null || typeof projected.value === "object") return [];
    return [{
      key: definition.key,
      group: definition.group,
      label: definition.label,
      kind: definition.kind || "text",
      value: String(projected.value).trim(),
    }];
  });
  return { profile, fields, ...normalizeEmployeeProfileAccess(payload) };
}

function normalizeEmployeeProfileDocuments(payload, expectedEmployeeNumber) {
  const profile = normalizeEmployeeProfileHeader(
    payload,
    expectedEmployeeNumber,
    "canReadDocuments",
    "documents",
  );
  if (!Array.isArray(payload.documents)) throw new Error("Die Dokumentprojektion ist unvollständig.");
  const documents = payload.documents.map((document) => {
    const id = String(document?.id || "").trim();
    const currentVersion = Number(document?.currentVersion);
    const revision = Number(document?.revision);
    const byteSize = Number(document?.byteSize);
    const visibility = String(document?.visibility || "").trim();
    const status = String(document?.status || "").trim();
    if (!id || !Number.isInteger(currentVersion) || currentVersion < 1
      || !Number.isInteger(revision) || revision < 1
      || !Number.isSafeInteger(byteSize) || byteSize < 0
      || visibility !== "hr_confidential"
      || !Object.hasOwn(EMPLOYEE_PROFILE_DOCUMENT_STATUSES, status)) {
      throw new Error("Die Dokumentprojektion ist ungültig.");
    }
    return {
      id,
      status,
      category: String(document?.category || "").trim(),
      visibility,
      title: String(document?.title || "").trim(),
      documentDate: String(document?.documentDate || "").trim(),
      description: String(document?.description || "").trim(),
      originalFilename: String(document?.originalFilename || "").trim(),
      detectedMime: String(document?.detectedMime || "").trim(),
      byteSize,
      currentVersion,
      revision,
      archivedAt: document?.archivedAt ? String(document.archivedAt).trim() : "",
      createdAt: String(document?.createdAt || "").trim(),
      updatedAt: String(document?.updatedAt || "").trim(),
    };
  });
  return { profile, documents, ...normalizeEmployeeProfileAccess(payload) };
}

const EMPLOYEE_ONBOARDING_ASSIGNMENT_STATES = new Set([
  "system_deferred",
  "fixed_recipient_eligible",
  "selection_required",
  "unresolved",
]);

const EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES = Object.freeze([
  "personnel_administration",
  "base_security_privacy",
]);

const EMPLOYEE_ONBOARDING_CONFIRMATION_FIELDS = Object.freeze([
  "responsibility",
  "packages",
  "lifecycleReviews",
  "assignments",
  "atomicStart",
]);

function normalizeEmployeeOnboardingScope(value) {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Der Onboarding-Geltungsbereich ist ungültig.");
  }
  const type = String(value.type || "").trim();
  const locationId = value.locationId === null ? null : String(value.locationId || "").trim();
  const departmentId = value.departmentId === null ? null : Number(value.departmentId);
  if (!new Set(["company", "location", "department"]).has(type)
    || (type === "company" && (locationId !== null || departmentId !== null))
    || (type !== "company" && !locationId)
    || (type === "location" && departmentId !== null)
    || (type === "department" && (!Number.isSafeInteger(departmentId) || departmentId < 1))) {
    throw new Error("Der Onboarding-Geltungsbereich ist ungültig.");
  }
  return { type, locationId, departmentId };
}

function normalizeEmployeeOnboardingAssignment(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Eine Onboarding-Zuweisungsvorschau ist ungültig.");
  }
  const stepReference = String(value.stepReference || "").trim();
  const title = String(value.title || "").trim();
  const sortOrder = Number(value.sortOrder);
  const stateValue = String(value.state || "").trim();
  const responsibilityType = String(value.responsibility?.type || "").trim();
  const responsibilityReference = String(value.responsibility?.reference || "").trim();
  const responsibilityLabel = String(value.responsibility?.label || "").trim();
  if (!stepReference || !title || !Number.isSafeInteger(sortOrder) || sortOrder < 1
    || !EMPLOYEE_ONBOARDING_ASSIGNMENT_STATES.has(stateValue)
    || !new Set(["system", "role", "employee"]).has(responsibilityType)
    || !responsibilityLabel || value.selectedAssignee !== null
    || !Array.isArray(value.eligibleRecipients)
    || (responsibilityType === "system") !== (stateValue === "system_deferred")
    || (responsibilityType === "system" && responsibilityReference)
    || (responsibilityType !== "system" && !responsibilityReference)
    || (responsibilityType === "employee"
      && !new Set(["fixed_recipient_eligible", "unresolved"]).has(stateValue))
    || (responsibilityType === "role"
      && !new Set(["selection_required", "unresolved"]).has(stateValue))) {
    throw new Error("Eine Onboarding-Zuweisungsvorschau ist ungültig.");
  }
  const eligibleRecipients = value.eligibleRecipients.map((recipient) => {
    const actorId = String(recipient?.actorId || "").trim();
    const displayName = String(recipient?.displayName || "").trim();
    if (!actorId || !displayName) {
      throw new Error("Ein möglicher Onboarding-Empfänger ist ungültig.");
    }
    return { actorId, displayName };
  });
  if (new Set(eligibleRecipients.map(({ actorId }) => actorId)).size !== eligibleRecipients.length
    || (stateValue === "system_deferred"
      && (responsibilityType !== "system" || eligibleRecipients.length))
    || (stateValue === "fixed_recipient_eligible"
      && (responsibilityType !== "employee" || eligibleRecipients.length !== 1
        || eligibleRecipients[0].actorId !== responsibilityReference))
    || (stateValue === "selection_required" && !eligibleRecipients.length)
    || (stateValue === "unresolved" && eligibleRecipients.length)) {
    throw new Error("Die Empfängerauflösung der Onboarding-Vorschau ist widersprüchlich.");
  }
  return {
    stepReference,
    title,
    sortOrder,
    state: stateValue,
    responsibility: {
      type: responsibilityType,
      reference: responsibilityReference,
      label: responsibilityLabel,
    },
    eligibleRecipients,
    selectedAssignee: null,
  };
}

function normalizeEmployeeOnboardingPackage(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || !Array.isArray(value.assignments) || !value.assignments.length
    || value.assignments.length > 30) {
    throw new Error("Ein Onboarding-Paket ist ungültig.");
  }
  const publicationId = String(value.publicationId || "").trim();
  const processId = String(value.processId || "").trim();
  const workflowCode = String(value.workflowCode || "").trim();
  const title = String(value.title || "").trim();
  const versionNumber = Number(value.versionNumber);
  const sourceRevision = Number(value.sourceRevision);
  const authorityLevel = String(value.authorityLevel || "").trim();
  const requirementKind = String(value.requirementKind || "").trim();
  const reviewStatus = String(value.reviewStatus || "").trim();
  if (!publicationId || !processId || !workflowCode || !title
    || !Number.isSafeInteger(versionNumber) || versionNumber < 1
    || !Number.isSafeInteger(sourceRevision) || sourceRevision < 1
    || !new Set(["central", "local"]).has(authorityLevel)
    || !new Set(["mandatory", "supplemental"]).has(requirementKind)
    || reviewStatus !== "requires_new_lifecycle_review") {
    throw new Error("Ein Onboarding-Paket ist ungültig.");
  }
  const assignments = value.assignments.map(normalizeEmployeeOnboardingAssignment);
  if (new Set(assignments.map(({ stepReference }) => stepReference)).size !== assignments.length) {
    throw new Error("Ein Onboarding-Paket enthält doppelte Schrittbezüge.");
  }
  return {
    publicationId,
    processId,
    sourceRevision,
    versionNumber,
    workflowCode,
    title,
    authorityLevel,
    requirementKind,
    scope: normalizeEmployeeOnboardingScope(value.scope),
    publishedAt: String(value.publishedAt || "").trim(),
    reviewStatus,
    assignments,
  };
}

function normalizeEmployeeOnboardingExecutionTimestamp(value, { nullable = false } = {}) {
  if (value === null && nullable) return null;
  const normalized = String(value || "").trim();
  if (!normalized || Number.isNaN(new Date(normalized).getTime())) {
    throw new Error("Ein Zeitwert des aktiven Onboarding-Falls ist ungültig.");
  }
  return normalized;
}

function normalizeEmployeeOnboardingActiveCase(value) {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Der aktive Onboarding-Fall ist ungültig.");
  }
  const caseId = String(value.caseId || "").trim();
  const caseState = String(value.state || "").trim();
  const packageCount = Number(value.packageCount);
  const taskCount = Number(value.taskCount);
  const completedTaskCount = Number(value.completedTaskCount);
  if (!caseId || caseId.length > 120
    || !new Set(["prepared", "approved", "active", "completed", "cancelled"]).has(caseState)
    || !Number.isSafeInteger(packageCount) || packageCount < 0
    || !Number.isSafeInteger(taskCount) || taskCount < 0
    || !Number.isSafeInteger(completedTaskCount) || completedTaskCount < 0
    || completedTaskCount > taskCount
    || typeof value.closeAvailable !== "boolean"
    || (value.closeAvailable && (
      caseState !== "active"
      || taskCount < 1
      || completedTaskCount !== taskCount
    ))) {
    throw new Error("Der aktive Onboarding-Fall ist ungültig.");
  }
  return {
    caseId,
    state: caseState,
    createdAt: normalizeEmployeeOnboardingExecutionTimestamp(value.createdAt, { nullable: true }),
    startedAt: normalizeEmployeeOnboardingExecutionTimestamp(value.startedAt, { nullable: true }),
    completedAt: normalizeEmployeeOnboardingExecutionTimestamp(value.completedAt, { nullable: true }),
    packageCount,
    taskCount,
    completedTaskCount,
    closeAvailable: value.closeAvailable,
  };
}

function normalizeEmployeeOnboardingExecution(payload) {
  const canStartOnboarding = payload.capabilities?.canStartOnboarding === true;
  const canCloseOnboarding = payload.capabilities?.canCloseOnboarding === true;
  const source = payload.onboardingExecution;
  if (source === undefined || source === null) {
    if (canStartOnboarding) {
      throw new Error("Die Onboarding-Ausführungsprojektion fehlt.");
    }
    return null;
  }
  if (!source || typeof source !== "object" || Array.isArray(source)
    || source.contractVersion !== "o4-v0.1"
    || source.mode !== "controlled_onboarding_start"
    || !/^[0-9a-f]{64}$/i.test(String(source.previewSha256 || ""))
    || typeof source.formAvailable !== "boolean"
    || source.requiredConfirmation !== "START_ONBOARDING") {
    throw new Error("Die Onboarding-Ausführungsprojektion ist ungültig.");
  }
  const activeCase = normalizeEmployeeOnboardingActiveCase(source.activeCase);
  if (source.formAvailable && (!canStartOnboarding || activeCase !== null)) {
    throw new Error("Die Onboarding-Ausführungsprojektion ist widersprüchlich.");
  }
  if (activeCase?.closeAvailable && !canCloseOnboarding) {
    throw new Error("Die Onboarding-Abschlussfreigabe ist widersprüchlich.");
  }
  return {
    contractVersion: source.contractVersion,
    mode: source.mode,
    previewSha256: String(source.previewSha256).toLowerCase(),
    formAvailable: source.formAvailable,
    requiredConfirmation: source.requiredConfirmation,
    activeCase,
  };
}

function normalizeEmployeeProfileOnboarding(payload, expectedEmployeeNumber) {
  const profile = normalizeEmployeeProfileHeader(
    payload,
    expectedEmployeeNumber,
    "canReadOnboardingPreview",
    "onboarding",
  );
  const source = payload.onboardingPreview;
  if (!source || typeof source !== "object" || Array.isArray(source)
    || source.contractVersion !== "o3-v0.1"
    || source.mode !== "read_only_onboarding_profile_preview"
    || source.caseType !== "onboarding"
    || source.startAllowed !== false
    || source.casePersisted !== false
    || source.instanceCount !== 0
    || source.taskCount !== 0
    || source.assignmentCount !== 0
    || source.subject?.employeeNumber !== String(expectedEmployeeNumber || "").trim()
    || !Array.isArray(source.packageResolution?.packages)
    || !Array.isArray(source.packageResolution?.requiredPackageFamilies)
    || !Array.isArray(source.packageResolution?.selectedBindings)
    || source.packageResolution.selectedBindings.length
    || !Array.isArray(source.packageResolution?.conflicts)
    || !Array.isArray(source.blockers)) {
    throw new Error("Die Onboarding-Profilprojektion ist unvollständig.");
  }
  const packages = source.packageResolution.packages.map(normalizeEmployeeOnboardingPackage);
  const assignments = packages.flatMap((entry) => entry.assignments);
  const summary = source.assignmentPreview;
  const expectedSummary = {
    packageCount: packages.length,
    stepCount: assignments.length,
    fixedRecipientCount: assignments.filter(({ state: value }) => value === "fixed_recipient_eligible").length,
    selectionRequiredCount: assignments.filter(({ state: value }) => value === "selection_required").length,
    unresolvedCount: assignments.filter(({ state: value }) => value === "unresolved").length,
    systemStepCount: assignments.filter(({ state: value }) => value === "system_deferred").length,
    selectedAssignmentCount: 0,
  };
  if (!summary || Object.entries(expectedSummary).some(([key, value]) => summary[key] !== value)) {
    throw new Error("Die Zusammenfassung der Onboarding-Zuweisungen ist widersprüchlich.");
  }
  const blockers = source.blockers.map((entry) => {
    const code = String(entry?.code || "").trim();
    if (!code) throw new Error("Ein Onboarding-Blocker ist ungültig.");
    return { code };
  });
  const onboardingExecution = normalizeEmployeeOnboardingExecution(payload);
  return {
    profile,
    onboardingPreview: {
      contractVersion: source.contractVersion,
      scope: normalizeEmployeeOnboardingScope(source.scope),
      packageResolution: {
        requiredPackageFamilies: source.packageResolution.requiredPackageFamilies
          .map((value) => String(value || "").trim()).filter(Boolean),
        packages,
        conflictCount: source.packageResolution.conflicts.length,
      },
      assignmentPreview: expectedSummary,
      blockers,
      startAllowed: false,
      casePersisted: false,
      instanceCount: 0,
      taskCount: 0,
      assignmentCount: 0,
    },
    onboardingExecution,
    ...normalizeEmployeeProfileAccess(payload),
  };
}

const EMPLOYEE_OFFBOARDING_FAMILIES = Object.freeze({
  hr_contract_end: "Vertragsende und Personaladministration",
  communication_release_information: "Kommunikationsfreigabe und Information",
  accounts_permissions: "Konten und Berechtigungen",
  work_access_assets: "Arbeitszugänge und Betriebsmittel",
  handover_open_responsibilities: "Übergabe und offene Verantwortungen",
  closing_documents_follow_up: "Abschlussdokumente und Nachbearbeitung",
});

const EMPLOYEE_OFFBOARDING_STATES = new Set([
  "internally_prepared",
  "communication_released",
  "employee_informed",
  "active",
  "completed",
  "cancelled",
]);

const EMPLOYEE_OFFBOARDING_PACKAGE_STATES = new Set([
  "confidential_preparation",
  "pending",
  "active",
  "complete",
  "terminated",
]);

function normalizeEmployeeOffboardingTimestamp(value, { nullable = false } = {}) {
  if (nullable && value === null) return null;
  const normalized = String(value || "").trim();
  const parsed = new Date(normalized);
  if (!normalized || Number.isNaN(parsed.getTime()) || parsed.toISOString() !== normalized) {
    throw new Error("Ein Offboarding-Zeitpunkt ist ungültig.");
  }
  return normalized;
}

function normalizeEmployeeOffboardingDate(value) {
  const normalized = String(value || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)
    || new Date(`${normalized}T00:00:00.000Z`).toISOString().slice(0, 10) !== normalized) {
    throw new Error("Ein Offboarding-Datum ist ungültig.");
  }
  return normalized;
}

function normalizeEmployeeOffboardingCandidate(entry, expectedEmployeeNumber) {
  const actorId = String(entry?.actorId || "").trim();
  const displayName = String(entry?.displayName || "").trim();
  if (!actorId || !displayName || actorId === String(expectedEmployeeNumber || "").trim()) {
    throw new Error("Eine Offboarding-Zuweisung ist ungültig.");
  }
  return {
    actorId,
    displayName,
    roleLabel: String(entry?.roleLabel || "Fachperson").trim(),
  };
}

function normalizeEmployeeOffboardingPackages(value, {
  preparedOnly = false,
  expectedEmployeeNumber = "",
} = {}) {
  if (!Array.isArray(value) || value.length !== 6) {
    throw new Error("Die sechs Offboarding-Pflichtfamilien fehlen.");
  }
  const seen = new Set();
  return value.map((entry) => {
    const familyCode = String(entry?.familyCode || "").trim();
    if (!Object.hasOwn(EMPLOYEE_OFFBOARDING_FAMILIES, familyCode) || seen.has(familyCode)) {
      throw new Error("Eine Offboarding-Pflichtfamilie ist ungültig.");
    }
    seen.add(familyCode);
    if (preparedOnly) {
      if (!Array.isArray(entry?.candidates)) {
        throw new Error("Die Empfängerfreigabe einer Offboarding-Pflichtfamilie fehlt.");
      }
      return {
        familyCode,
        title: String(entry?.title || EMPLOYEE_OFFBOARDING_FAMILIES[familyCode]).trim(),
        recipientClass: String(entry?.recipientClass || "").trim(),
        candidates: entry.candidates.map((candidate) => (
          normalizeEmployeeOffboardingCandidate(candidate, expectedEmployeeNumber)
        )),
      };
    }
    const orderId = String(entry?.orderId || "").trim();
    const status = String(entry?.status || "").trim();
    const assigneeActorId = String(entry?.assigneeActorId || "").trim();
    if (!orderId || !assigneeActorId || !EMPLOYEE_OFFBOARDING_PACKAGE_STATES.has(status)) {
      throw new Error("Ein Offboarding-Auftrag ist ungültig.");
    }
    return {
      familyCode,
      title: String(entry?.title || EMPLOYEE_OFFBOARDING_FAMILIES[familyCode]).trim(),
      recipientClass: String(entry?.recipientClass || "").trim(),
      assigneeActorId,
      assigneeDisplayName: String(entry?.assigneeDisplayName || assigneeActorId).trim(),
      orderId,
      status,
      dueAt: entry?.dueAt === null
        ? null
        : normalizeEmployeeOffboardingTimestamp(entry?.dueAt),
    };
  });
}

function normalizeEmployeeOffboardingCase(value, expectedEmployeeNumber) {
  if (value === null) return null;
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("Der vertrauliche Offboarding-Fall ist ungültig.");
  }
  const caseId = String(value.caseId || "").trim();
  const stateValue = String(value.state || "").trim();
  const revision = Number(value.revision);
  if (!caseId || !EMPLOYEE_OFFBOARDING_STATES.has(stateValue)
    || !Number.isSafeInteger(revision) || revision < 1
    || String(value.employeeNumber || expectedEmployeeNumber).trim()
      !== String(expectedEmployeeNumber || "").trim()) {
    throw new Error("Der vertrauliche Offboarding-Fall ist ungültig.");
  }
  const referenceTimes = value.referenceTimes || {};
  const urgency = value.urgency || {};
  const confidential = value.confidential || {};
  const allowedActions = value.allowedActions || {};
  const mode = String(urgency.mode || "").trim();
  if (!["standard", "time_critical"].includes(mode)
    || typeof urgency.approved !== "boolean"
    || !Array.isArray(confidential.documentReferenceIds)) {
    throw new Error("Die geschützte Offboarding-Projektion ist ungültig.");
  }
  return {
    caseId,
    state: stateValue,
    revision,
    responsibleActorId: String(value.responsibleActorId || "").trim(),
    createdAt: normalizeEmployeeOffboardingTimestamp(value.createdAt),
    updatedAt: normalizeEmployeeOffboardingTimestamp(value.updatedAt),
    referenceTimes: {
      plannedExitAt: normalizeEmployeeOffboardingTimestamp(referenceTimes.plannedExitAt),
      lastWorkingDay: normalizeEmployeeOffboardingDate(referenceTimes.lastWorkingDay),
      legalExitDate: normalizeEmployeeOffboardingDate(referenceTimes.legalExitDate),
      accessBlockAt: normalizeEmployeeOffboardingTimestamp(referenceTimes.accessBlockAt),
    },
    urgency: {
      mode,
      exceptionReasonCode: urgency.exceptionReasonCode === null
        ? null
        : String(urgency.exceptionReasonCode || "").trim(),
      followUpDueAt: urgency.followUpDueAt === null
        ? null
        : normalizeEmployeeOffboardingTimestamp(urgency.followUpDueAt),
      approved: urgency.approved,
    },
    confidential: {
      exitReasonCode: String(confidential.exitReasonCode || "").trim(),
      exitReasonNote: String(confidential.exitReasonNote || "").trim(),
      hrNote: String(confidential.hrNote || "").trim(),
      documentReferenceIds: confidential.documentReferenceIds
        .map((entry) => String(entry || "").trim()).filter(Boolean),
    },
    packages: normalizeEmployeeOffboardingPackages(value.packages),
    allowedActions: {
      approveTimeCritical: allowedActions.approveTimeCritical === true,
      releaseCommunication: allowedActions.releaseCommunication === true,
      confirmInformation: allowedActions.confirmInformation === true,
      activate: allowedActions.activate === true,
      cancel: allowedActions.cancel === true,
      close: allowedActions.close === true,
    },
  };
}

function normalizeEmployeeProfileOffboarding(payload, expectedEmployeeNumber) {
  const profile = normalizeEmployeeProfileHeader(
    payload,
    expectedEmployeeNumber,
    "canReadOffboardingConfidential",
    "offboarding",
  );
  const source = payload.offboarding;
  if (!source || typeof source !== "object" || Array.isArray(source)
    || source.contractVersion !== "o5-v0.1"
    || source.mode !== "confidential_offboarding") {
    throw new Error("Die vertrauliche Offboarding-Projektion ist unvollständig.");
  }
  const preparation = source.preparation || {};
  if (typeof preparation.available !== "boolean"
    || !Array.isArray(preparation.packages)) {
    throw new Error("Die vertrauliche Offboarding-Vorbereitung ist unvollständig.");
  }
  return {
    profile,
    offboarding: {
      contractVersion: source.contractVersion,
      mode: source.mode,
      case: normalizeEmployeeOffboardingCase(source.case, expectedEmployeeNumber),
      preparation: {
        available: preparation.available,
        packages: normalizeEmployeeOffboardingPackages(preparation.packages, {
          preparedOnly: true,
          expectedEmployeeNumber,
        }),
      },
    },
    ...normalizeEmployeeProfileAccess(payload),
  };
}

function employeeProfileInitials(displayName) {
  const parts = String(displayName || "").trim().split(/\s+/).filter(Boolean);
  return (parts.length ? `${parts[0][0] || ""}${parts.length > 1 ? parts.at(-1)[0] || "" : ""}` : "MA")
    .toLocaleUpperCase("de-AT")
    .slice(0, 2);
}

function employeeProfileReferenceLabel(reference, { includeCode = false } = {}) {
  const name = String(reference?.name || "").trim();
  const code = String(reference?.code || "").trim();
  if (includeCode && code && name) return `${code} · ${name}`;
  return name || (includeCode ? code : "") || "Nicht hinterlegt";
}

function renderEmployeeProfileHeader() {
  const profile = state.employeeProfile;
  if (!profile) {
    const unavailable = Boolean(state.employeeProfileLoadError || state.employeeProfileTabErrors.overview);
    if (elements.employeeProfileAvatar) elements.employeeProfileAvatar.textContent = "MA";
    if (elements.employeeProfileName) elements.employeeProfileName.textContent = unavailable ? "Profil nicht verfügbar" : "Profil wird geladen";
    if (elements.employeeProfileIdentity) elements.employeeProfileIdentity.textContent = unavailable
      ? "Es wurden keine Profildaten angezeigt."
      : "Freigegebene Organisationsdaten werden geladen.";
    if (elements.employeeProfileStatus) {
      elements.employeeProfileStatus.textContent = unavailable ? "Nicht verfügbar" : "Wird geladen";
      elements.employeeProfileStatus.classList.add("inactive");
    }
    return;
  }
  if (elements.employeeProfileAvatar) elements.employeeProfileAvatar.textContent = employeeProfileInitials(profile.displayName);
  if (elements.employeeProfileName) elements.employeeProfileName.textContent = profile.displayName;
  if (elements.employeeProfileIdentity) elements.employeeProfileIdentity.textContent = `Personalnummer ${profile.employeeNumber}`;
  if (elements.employeeProfileStatus) {
    elements.employeeProfileStatus.textContent = profile.active ? "Aktiv" : "Inaktiv";
    elements.employeeProfileStatus.classList.toggle("inactive", !profile.active);
  }
}

function employeeProfileTabDefinition(tabId = state.employeeProfileTab) {
  return EMPLOYEE_PROFILE_TABS.find(({ id }) => id === tabId) || null;
}

function applyEmployeeProfileAccessProjection(result) {
  state.employeeProfileTabAvailability = {
    overview: result?.tabs?.overview?.available === true
      && result?.capabilities?.canReadOverview === true,
    masterData: result?.tabs?.masterData?.available === true
      && result?.capabilities?.canReadMasterOrg === true,
    documents: result?.tabs?.documents?.available === true
      && result?.capabilities?.canReadDocuments === true,
    onboarding: result?.tabs?.onboarding?.available === true
      && result?.capabilities?.canReadOnboardingPreview === true,
    offboarding: result?.tabs?.offboarding?.available === true
      && result?.capabilities?.canReadOffboardingConfidential === true,
  };
}

function employeeProfileTabIsLoading(tabId = state.employeeProfileTab) {
  return state.employeeProfileLoadingTabs.has(tabId);
}

function employeeProfileFormatValue(field) {
  if (!String(field?.value || "").trim()) return "Nicht hinterlegt";
  return field.kind === "date" ? formatDate(field.value, undefined, field.value) : field.value;
}

function employeeProfileFormatTimestamp(value, fallback = "Nicht hinterlegt") {
  const parsed = new Date(String(value || ""));
  if (Number.isNaN(parsed.getTime())) return fallback;
  try {
    return new Intl.DateTimeFormat("de-AT", { dateStyle: "short", timeStyle: "short" }).format(parsed);
  } catch {
    return fallback;
  }
}

function employeeProfileFormatFileSize(value) {
  const bytes = Number(value);
  if (!Number.isFinite(bytes) || bytes < 0) return "Nicht hinterlegt";
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let size = bytes / 1024;
  let unit = units[0];
  for (let index = 1; index < units.length && size >= 1024; index += 1) {
    size /= 1024;
    unit = units[index];
  }
  return `${new Intl.NumberFormat("de-AT", { maximumFractionDigits: 1 }).format(size)} ${unit}`;
}

function renderEmployeeProfileMasterData(data) {
  const organization = state.employeeProfile?.organization || {};
  const organizationRows = [
    ["Position", organization.positionName || "Nicht hinterlegt"],
    ["Kostenstelle", employeeProfileReferenceLabel(organization.costCenter, { includeCode: true })],
    ["Standort", employeeProfileReferenceLabel(organization.location)],
    ["Abteilung", employeeProfileReferenceLabel(organization.department)],
  ];
  const groupOrder = [...new Set(EMPLOYEE_PROFILE_MASTER_DATA_FIELDS.map(({ group }) => group))];
  const groups = groupOrder.map((group) => ({
    group,
    fields: (data?.fields || []).filter((field) => field.group === group),
  })).filter(({ fields }) => fields.length);
  const fieldMarkup = groups.map(({ group, fields }) => `
    <section class="employee-profile-data-section">
      <h3>${escapeHtml(group)}</h3>
      <dl class="employee-profile-data-grid">${fields.map((field) => `
        <div><dt>${escapeHtml(field.label)}</dt><dd>${escapeHtml(employeeProfileFormatValue(field))}</dd></div>`).join("")}</dl>
    </section>`).join("");
  return `<div class="employee-profile-overview-grid employee-profile-organization-grid">${organizationRows.map(([label, value]) => `
      <article class="employee-profile-overview-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></article>`).join("")}</div>
    ${fieldMarkup || '<div class="employee-profile-empty employee-profile-inline-empty"><strong>Keine weiteren Stammdaten freigegeben</strong><p>Für diesen Bereich wurden ausschließlich Organisationsdaten bereitgestellt.</p></div>'}
    <p class="employee-profile-boundary">Nur die serverseitig für diesen Zugriff freigegebenen Felder werden angezeigt. Änderungen sind in diesem Profil nicht möglich.</p>`;
}

function renderEmployeeProfileDocuments(documents) {
  if (!documents.length) {
    return '<div class="employee-profile-empty"><strong>Keine Dokumente sichtbar</strong><p>Für dieses Profil wurden keine Dokumentmetadaten freigegeben.</p></div>';
  }
  return `<div class="employee-profile-document-list">${documents.map((document) => {
    const statusLabel = EMPLOYEE_PROFILE_DOCUMENT_STATUSES[document.status] || "Status nicht verfügbar";
    const documentDate = formatDate(document.documentDate, undefined, "Kein Dokumentdatum");
    const updatedAt = employeeProfileFormatTimestamp(document.updatedAt || document.createdAt);
    return `<article class="employee-profile-document">
      <header><div><span class="eyebrow">${escapeHtml(document.category || "Dokument")}</span><h3>${escapeHtml(document.title || document.originalFilename || "Dokument")}</h3></div><span class="status-badge ${document.status === "active" ? "approved" : "inactive"}">${escapeHtml(statusLabel)}</span></header>
      ${document.description ? `<p>${escapeHtml(document.description)}</p>` : ""}
      <dl class="employee-profile-document-meta">
        <div><dt>Version</dt><dd>${document.currentVersion}</dd></div>
        <div><dt>Dokumentdatum</dt><dd>${escapeHtml(documentDate)}</dd></div>
        <div><dt>Datei</dt><dd>${escapeHtml(document.originalFilename || "Nicht hinterlegt")}</dd></div>
        <div><dt>Format</dt><dd>${escapeHtml(document.detectedMime || "Nicht hinterlegt")}</dd></div>
        <div><dt>Größe</dt><dd>${escapeHtml(employeeProfileFormatFileSize(document.byteSize))}</dd></div>
        <div><dt>Aktualisiert</dt><dd>${escapeHtml(updatedAt)}</dd></div>
      </dl>
    </article>`;
  }).join("")}</div>
  <p class="employee-profile-boundary">Diese Ansicht enthält ausschließlich freigegebene Metadaten und Versionsstände. Dateiinhalte, Speicherpfade und technische Prüfnachweise werden nicht geladen.</p>`;
}

const EMPLOYEE_ONBOARDING_BLOCKER_LABELS = Object.freeze({
  onboarding_execution_deferred_until_o4: "Der Onboarding-Start bleibt bis zum ausdrücklich freigegebenen Ausführungsblock O4 technisch gesperrt.",
  subject_not_found: "Der Mitarbeiterbezug konnte nicht sicher aufgelöst werden.",
  subject_inactive: "Der Mitarbeiterbezug ist nicht aktiv.",
  scope_unresolved: "Standort oder Abteilung ist noch nicht eindeutig zugeordnet.",
  scope_inactive: "Ein benötigter Organisationsbereich ist nicht aktiv.",
  scope_relation_invalid: "Standort und Abteilung sind widersprüchlich verknüpft.",
  no_applicable_onboarding_packages: "Für diesen Organisationsbereich wurde kein passendes Onboarding-Paket gefunden.",
  m4_publication_review_required: "Die vorhandenen Workflow-Veröffentlichungen müssen unter dem neuen Lifecycle-Schutzvertrag erneut fachlich geprüft werden.",
  required_package_family_unmapped: "Mindestens eine verpflichtende Paketfamilie ist noch keiner geprüften Veröffentlichung zugeordnet.",
  package_conflict: "Mehrere Pakete besitzen einen nicht automatisch auflösbaren fachlichen Konflikt.",
  assignment_selection_required: "Für mindestens einen Schritt muss später ausdrücklich eine verantwortliche Person ausgewählt werden.",
  assignment_unresolved: "Für mindestens einen Schritt wurde derzeit keine geeignete verantwortliche Person gefunden.",
  onboarding_notifications_deferred: "Mindestens ein Paket enthält Benachrichtigungen. Diese bleiben in O4 technisch gesperrt.",
});

function employeeOnboardingScopeLabel(scope) {
  if (!scope) return "Noch nicht eindeutig";
  if (scope.type === "company") return "Gesamtes Unternehmen";
  if (scope.type === "location") return `Standort ${scope.locationId}`;
  return `Standort ${scope.locationId} · Abteilung ${scope.departmentId}`;
}

function employeeOnboardingAssignmentState(value) {
  return ({
    system_deferred: { label: "Systemschritt gesperrt", tone: "inactive" },
    fixed_recipient_eligible: { label: "Feste Person geeignet", tone: "approved" },
    selection_required: { label: "Auswahl erforderlich", tone: "warning" },
    unresolved: { label: "Noch ungeklärt", tone: "inactive" },
  })[value] || { label: "Nicht verfügbar", tone: "inactive" };
}

function renderEmployeeProfileOnboardingPreview(preview, { controlledExecution = false } = {}) {
  const summary = preview.assignmentPreview;
  const packages = preview.packageResolution.packages;
  const blockerLabels = [...new Set(preview.blockers
    .filter(({ code }) => !controlledExecution || code !== "onboarding_execution_deferred_until_o4")
    .map(({ code }) => (
    EMPLOYEE_ONBOARDING_BLOCKER_LABELS[code] || "Eine fachliche Voraussetzung ist noch nicht erfüllt."
  )))];
  const packageMarkup = packages.length ? `<div class="employee-onboarding-package-list">${packages.map((entry) => `
    <article class="employee-onboarding-package">
      <header>
        <div><span class="eyebrow">${entry.requirementKind === "mandatory" ? "Unternehmensweites Pflichtpaket" : "Ergänzung"}</span><h3>${escapeHtml(entry.title)}</h3></div>
        <span class="status-badge warning">Prüfung erforderlich</span>
      </header>
      <dl class="employee-onboarding-package-meta">
        <div><dt>Version</dt><dd>${entry.versionNumber}</dd></div>
        <div><dt>Workflow-Code</dt><dd>${escapeHtml(entry.workflowCode)}</dd></div>
        <div><dt>Geltungsbereich</dt><dd>${escapeHtml(employeeOnboardingScopeLabel(entry.scope))}</dd></div>
        <div><dt>Veröffentlicht</dt><dd>${escapeHtml(employeeProfileFormatTimestamp(entry.publishedAt, "Nicht hinterlegt"))}</dd></div>
      </dl>
      <div class="employee-onboarding-assignment-list">${entry.assignments.map((assignment) => {
        const assignmentState = employeeOnboardingAssignmentState(assignment.state);
        const recipients = assignment.eligibleRecipients.length
          ? assignment.eligibleRecipients.map(({ displayName, actorId }) => `${displayName} · ${actorId}`).join(", ")
          : assignment.state === "system_deferred"
            ? "Keine Ausführung in O3"
            : "Keine geeignete Person gefunden";
        return `<section class="employee-onboarding-assignment">
          <header><div><span>Schritt ${assignment.sortOrder}</span><strong>${escapeHtml(assignment.title)}</strong></div><span class="status-badge ${assignmentState.tone}">${escapeHtml(assignmentState.label)}</span></header>
          <dl>
            <div><dt>Verantwortung</dt><dd>${escapeHtml(assignment.responsibility.label)}</dd></div>
            <div><dt>Geeignete Personen</dt><dd>${escapeHtml(recipients)}</dd></div>
          </dl>
        </section>`;
      }).join("")}</div>
    </article>`).join("")}</div>`
    : '<div class="employee-profile-empty employee-profile-inline-empty"><strong>Keine Pakete aufgelöst</strong><p>Die serverseitige Vorschau hat derzeit kein anwendbares Onboarding-Paket gefunden.</p></div>';
  return `<section class="employee-onboarding-intro">
      <div><span class="eyebrow">${controlledExecution ? "Kontrollierter Start" : "Geschützte Lesevorschau"}</span><h3>${controlledExecution ? "Onboarding sicher vorbereiten" : "Onboarding ist noch nicht startbar"}</h3><p>${controlledExecution ? "Pakete, fachliche Prüfungen und Verantwortliche werden vor dem atomaren Start ausdrücklich bestätigt." : "Pakete und mögliche Verantwortliche werden serverseitig ermittelt. Diese Ansicht erzeugt weder Fall noch Instanz, Aufgabe oder Zuweisung."}</p></div>
      <span class="status-badge ${controlledExecution ? "warning" : "inactive"}">${controlledExecution ? "O4" : "Nur Vorschau"}</span>
    </section>
    <div class="employee-profile-overview-grid employee-onboarding-summary">
      <article class="employee-profile-overview-card"><span>Pakete</span><strong>${summary.packageCount}</strong></article>
      <article class="employee-profile-overview-card"><span>Schritte</span><strong>${summary.stepCount}</strong></article>
      <article class="employee-profile-overview-card"><span>Personenauswahl offen</span><strong>${summary.selectionRequiredCount}</strong></article>
      <article class="employee-profile-overview-card"><span>Ungeklärte Zuweisungen</span><strong>${summary.unresolvedCount}</strong></article>
    </div>
    ${blockerLabels.length ? `<section class="employee-onboarding-blockers"><h3>${controlledExecution ? "Hinweise vor dem Start" : "Fehlende Voraussetzungen"}</h3><ul>${blockerLabels.map((label) => `<li>${escapeHtml(label)}</li>`).join("")}</ul></section>` : ""}
    ${packageMarkup}
    <p class="employee-profile-boundary">${controlledExecution ? "O4 startet ausschließlich den bestätigten Onboarding-Fall und die ausgewählten Pakete als eine atomare Aktion. Es gibt keine automatische Verantwortlichenwahl, Benachrichtigung oder externe Aktion." : "O3 ist vollständig read-only. Es gibt hier bewusst keinen Startknopf, keine automatische Verantwortlichenwahl, keine Fortschaltung, keine Benachrichtigung und keine externe Aktion."}</p>`;
}

const EMPLOYEE_ONBOARDING_START_FAMILY_LABELS = Object.freeze({
  personnel_administration: "Personaladministration",
  base_security_privacy: "Grundschutz, Sicherheit & Datenschutz",
});

const EMPLOYEE_ONBOARDING_START_CONFIRMATION_LABELS = Object.freeze({
  responsibility: "Ich übernehme die Verantwortung für diesen kontrollierten Onboarding-Start.",
  packages: "Ich habe beide Pflichtfamilien zwei verschiedenen unternehmensweiten Pflichtpaketen zugeordnet.",
  lifecycleReviews: "Ich habe die Lifecycle-Eignung jedes anwendbaren Pakets fachlich geprüft.",
  assignments: "Ich habe für jeden nicht-systemischen Schritt ausdrücklich eine verantwortliche Person ausgewählt.",
  atomicStart: "Ich bestätige, dass Fall, Pakete und Zuweisungen gemeinsam und atomar gestartet werden müssen.",
});

const EMPLOYEE_ONBOARDING_ACTIVE_CASE_STATES = Object.freeze({
  prepared: "Vorbereitet",
  approved: "Freigegeben",
  active: "Aktiv",
  completed: "Abgeschlossen",
  cancelled: "Abgebrochen",
});

function clearEmployeeOnboardingStartState() {
  state.employeeOnboardingStartDraft = null;
  state.employeeOnboardingCloseDraft = null;
}

function employeeOnboardingCloseDraftFor(activeCase) {
  if (!activeCase?.closeAvailable) return null;
  const existing = state.employeeOnboardingCloseDraft;
  if (existing?.caseId === activeCase.caseId) return existing;
  state.employeeOnboardingCloseDraft = {
    caseId: activeCase.caseId,
    confirmed: false,
    pending: false,
    operationId: "",
    error: "",
  };
  return state.employeeOnboardingCloseDraft;
}

function employeeOnboardingResponsibleActorId() {
  const user = state.portalSession?.user;
  const projectedActorId = String(user?.actorId || "").trim();
  if (projectedActorId) return projectedActorId;
  const employeeNumber = String(user?.employeeNumber || "").trim();
  if (employeeNumber) return employeeNumber;
  const accountId = String(user?.accountId || "").trim();
  return accountId ? `account:${accountId}` : "";
}

function employeeOnboardingAssignmentDraftKey(publicationId, stepReference) {
  return `${String(publicationId || "").trim()}\0${String(stepReference || "").trim()}`;
}

function employeeOnboardingStartDraftFor(preview) {
  const execution = preview?.onboardingExecution;
  if (!execution?.formAvailable) return null;
  const employeeNumber = String(state.employeeProfileEmployeeNumber || "").trim();
  const existing = state.employeeOnboardingStartDraft;
  if (existing?.employeeNumber === employeeNumber
    && existing.previewSha256 === execution.previewSha256) return existing;
  state.employeeOnboardingStartDraft = {
    employeeNumber,
    previewSha256: execution.previewSha256,
    referenceDates: {
      contractualEntryDate: "",
      firstWorkingDay: "",
      onboardingTargetDate: "",
    },
    packageSelections: Object.fromEntries(
      EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES.map((familyCode) => [familyCode, ""]),
    ),
    packageReviews: {},
    assignments: {},
    confirmations: Object.fromEntries(
      EMPLOYEE_ONBOARDING_CONFIRMATION_FIELDS.map((field) => [field, false]),
    ),
    finalConfirmation: false,
    pending: false,
    operationId: "",
    requestFingerprint: "",
    error: "",
  };
  return state.employeeOnboardingStartDraft;
}

function employeeOnboardingStartCandidatePackages(preview) {
  return preview.packageResolution.packages.filter((entry) => (
    entry.requirementKind === "mandatory"
      && entry.scope?.type === "company"
      && entry.authorityLevel === "central"
  ));
}

function pruneEmployeeOnboardingStartDraft(preview, draft) {
  const candidatePublicationIds = new Set(
    employeeOnboardingStartCandidatePackages(preview).map(({ publicationId }) => publicationId),
  );
  for (const familyCode of EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES) {
    if (!candidatePublicationIds.has(draft.packageSelections[familyCode])) {
      draft.packageSelections[familyCode] = "";
    }
  }
  const applicablePublicationIds = new Set(
    preview.packageResolution.packages.map(({ publicationId }) => publicationId),
  );
  draft.packageReviews = Object.fromEntries(Object.entries(draft.packageReviews)
    .filter(([publicationId]) => applicablePublicationIds.has(publicationId)));
  draft.assignments = Object.fromEntries(Object.entries(draft.assignments)
    .filter(([key]) => applicablePublicationIds.has(key.split("\0", 1)[0])));
}

function employeeOnboardingStartSelectedPackages(preview, draft) {
  const candidates = employeeOnboardingStartCandidatePackages(preview);
  return EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES.flatMap((familyCode) => {
    const publicationId = draft.packageSelections[familyCode];
    const selectedPackage = candidates.find((entry) => entry.publicationId === publicationId);
    return selectedPackage ? [{ familyCode, package: selectedPackage }] : [];
  });
}

function employeeOnboardingIsIsoDate(value) {
  const normalized = String(value || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) return false;
  const parsed = new Date(`${normalized}T00:00:00.000Z`);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString().slice(0, 10) === normalized;
}

function buildEmployeeOnboardingStartRequest(preview, draft) {
  const execution = preview?.onboardingExecution;
  const responsibleActorId = employeeOnboardingResponsibleActorId();
  if (!execution?.formAvailable || preview.canStartOnboarding !== true
    || execution.requiredConfirmation !== "START_ONBOARDING"
    || draft.employeeNumber !== state.employeeProfileEmployeeNumber
    || draft.previewSha256 !== execution.previewSha256
    || !responsibleActorId) {
    throw new Error("Der kontrollierte Onboarding-Start ist nicht mehr verfügbar.");
  }
  if (!Object.values(draft.referenceDates).every(employeeOnboardingIsIsoDate)) {
    throw new Error("Bitte alle drei Referenzdaten vollständig und gültig eintragen.");
  }
  if (draft.referenceDates.contractualEntryDate > draft.referenceDates.firstWorkingDay
    || draft.referenceDates.firstWorkingDay > draft.referenceDates.onboardingTargetDate) {
    throw new Error("Die Referenzdaten müssen in zeitlicher Reihenfolge liegen.");
  }
  const selectedPackages = employeeOnboardingStartSelectedPackages(preview, draft);
  const selectedPublicationIds = selectedPackages.map(({ package: entry }) => entry.publicationId);
  if (selectedPackages.length !== EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES.length
    || new Set(selectedPublicationIds).size !== selectedPublicationIds.length) {
    throw new Error("Bitte jeder Pflichtfamilie ein anderes unternehmensweites Pflichtpaket zuordnen.");
  }
  const familyCodesByPublication = new Map(selectedPackages.map(({ familyCode, package: entry }) => (
    [entry.publicationId, [familyCode]]
  )));
  const packageBindings = preview.packageResolution.packages.map((entry) => {
    if (draft.packageReviews[entry.publicationId] !== true) {
      throw new Error("Bitte die Lifecycle-Prüfung jedes anwendbaren Pakets bestätigen.");
    }
    const assignments = entry.assignments
      .filter(({ responsibility }) => responsibility.type !== "system")
      .map((assignment) => {
        const assigneeActorId = String(draft.assignments[
          employeeOnboardingAssignmentDraftKey(entry.publicationId, assignment.stepReference)
        ] || "").trim();
        if (!assigneeActorId
          || !assignment.eligibleRecipients.some(({ actorId }) => actorId === assigneeActorId)) {
          throw new Error("Bitte für jeden nicht-systemischen Schritt ausdrücklich eine geeignete Person auswählen.");
        }
        return { stepReference: assignment.stepReference, assigneeActorId };
      });
    return {
      publicationId: entry.publicationId,
      versionNumber: entry.versionNumber,
      familyCodes: familyCodesByPublication.get(entry.publicationId) || [],
      reviewConfirmed: true,
      assignments,
    };
  });
  if (!EMPLOYEE_ONBOARDING_CONFIRMATION_FIELDS.every((field) => draft.confirmations[field] === true)
    || draft.finalConfirmation !== true) {
    throw new Error("Bitte alle ausdrücklichen Bestätigungen einschließlich START_ONBOARDING setzen.");
  }
  return {
    expectedPreviewSha256: execution.previewSha256,
    responsibleActorId,
    confirmation: "START_ONBOARDING",
    confirmations: Object.fromEntries(
      EMPLOYEE_ONBOARDING_CONFIRMATION_FIELDS.map((field) => [field, true]),
    ),
    referenceDates: { ...draft.referenceDates },
    packageBindings,
  };
}

function employeeOnboardingStartRequestWithOperation(draft, request) {
  const fingerprint = JSON.stringify(request);
  if (!draft.operationId || draft.requestFingerprint !== fingerprint) {
    const operationId = globalThis.crypto?.randomUUID?.();
    if (!operationId) throw new Error("Für den sicheren Start konnte keine Vorgangs-ID erzeugt werden.");
    draft.operationId = operationId;
    draft.requestFingerprint = fingerprint;
  }
  return { operationId: draft.operationId, ...request };
}

function renderEmployeeOnboardingActiveCase(activeCase) {
  const terminal = ["completed", "cancelled"].includes(activeCase.state);
  const closeDraft = employeeOnboardingCloseDraftFor(activeCase);
  const closeMarkup = closeDraft ? `<form class="employee-onboarding-close-form" data-employee-onboarding-close-form aria-busy="${String(closeDraft.pending)}">
      <label class="employee-onboarding-start-check">
        <input type="checkbox" required data-onboarding-close-confirmation${closeDraft.confirmed ? " checked" : ""}${closeDraft.pending ? " disabled" : ""}>
        <span>Ich best&auml;tige, dass alle verkn&uuml;pften Onboarding-Aufgaben erledigt sind: <strong>CLOSE_ONBOARDING</strong></span>
      </label>
      <p class="employee-onboarding-start-message${closeDraft.error ? " error" : ""}" data-onboarding-close-message role="status" aria-live="polite">${escapeHtml(closeDraft.error)}</p>
      <div class="employee-onboarding-start-actions"><button type="submit" class="primary-button"${closeDraft.pending ? " disabled" : ""}>${closeDraft.pending ? "Fall wird abgeschlossen &hellip;" : "Onboarding-Fall verbindlich abschlie&szlig;en"}</button></div>
    </form>` : "";
  const stateLabel = EMPLOYEE_ONBOARDING_ACTIVE_CASE_STATES[activeCase.state] || "Status nicht verfügbar";
  return `<section class="employee-onboarding-active-case" aria-labelledby="employeeOnboardingActiveCaseTitle">
    <header><div><span class="eyebrow">${terminal ? "Abgeschlossener" : "Aktiver"} Onboarding-Fall</span><h3 id="employeeOnboardingActiveCaseTitle">${escapeHtml(stateLabel)}</h3></div><span class="status-badge ${activeCase.closeAvailable || activeCase.state === "active" ? "approved" : "inactive"}">${activeCase.closeAvailable ? "Abschluss freigegeben" : "Nur Status"}</span></header>
    <dl>
      <div><dt>Fallreferenz</dt><dd>${escapeHtml(activeCase.caseId)}</dd></div>
      <div><dt>Angelegt</dt><dd>${escapeHtml(employeeProfileFormatTimestamp(activeCase.createdAt))}</dd></div>
      <div><dt>Gestartet</dt><dd>${escapeHtml(activeCase.startedAt ? employeeProfileFormatTimestamp(activeCase.startedAt) : "Noch nicht gestartet")}</dd></div>
      <div><dt>Abgeschlossen</dt><dd>${escapeHtml(activeCase.completedAt ? employeeProfileFormatTimestamp(activeCase.completedAt) : "Noch offen")}</dd></div>
      <div><dt>Pakete</dt><dd>${activeCase.packageCount}</dd></div>
      <div><dt>Aufgaben</dt><dd>${activeCase.completedTaskCount} von ${activeCase.taskCount} erledigt</dd></div>
    </dl>
    ${closeMarkup}
    <p>Der Fall bleibt als minimierte Statusprojektion sichtbar. Außer dem ausdrücklich freigegebenen Abschluss sind Änderungen und externe Aktionen nicht verfügbar.</p>
  </section>`;
}

function renderEmployeeOnboardingStartForm(preview) {
  const execution = preview.onboardingExecution;
  const draft = employeeOnboardingStartDraftFor(preview);
  if (!draft) return "";
  pruneEmployeeOnboardingStartDraft(preview, draft);
  const candidates = employeeOnboardingStartCandidatePackages(preview);
  const requiredFamiliesProjected = EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES.every(
    (familyCode) => preview.packageResolution.requiredPackageFamilies.includes(familyCode),
  );
  const responsibleActorId = employeeOnboardingResponsibleActorId();
  const structuralBlocker = !requiredFamiliesProjected
    ? "Die beiden Pflichtfamilien fehlen in der aktuellen Servervorschau."
    : candidates.length < 2
      ? "Für den kontrollierten Start werden zwei verschiedene unternehmensweite Pflichtpakete benötigt."
      : !responsibleActorId
        ? "Die verantwortliche angemeldete Person konnte nicht sicher bestimmt werden."
        : "";
  const disabled = draft.pending ? " disabled" : "";
  const selectedPackages = employeeOnboardingStartSelectedPackages(preview, draft);
  const familySelectors = EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES.map((familyCode) => {
    const selectedPublicationId = draft.packageSelections[familyCode] || "";
    const selectedElsewhere = new Set(EMPLOYEE_ONBOARDING_REQUIRED_START_FAMILIES
      .filter((otherFamilyCode) => otherFamilyCode !== familyCode)
      .map((otherFamilyCode) => draft.packageSelections[otherFamilyCode]).filter(Boolean));
    return `<label class="employee-onboarding-start-field">
      <span>${escapeHtml(EMPLOYEE_ONBOARDING_START_FAMILY_LABELS[familyCode])}</span>
      <select required data-onboarding-family-code="${escapeHtmlAttribute(familyCode)}"${disabled}>
        <option value="">Pflichtpaket ausdrücklich auswählen</option>
        ${candidates.map((entry) => `<option value="${escapeHtmlAttribute(entry.publicationId)}"${entry.publicationId === selectedPublicationId ? " selected" : ""}${selectedElsewhere.has(entry.publicationId) ? " disabled" : ""}>${escapeHtml(entry.title)} · Version ${entry.versionNumber}</option>`).join("")}
      </select>
    </label>`;
  }).join("");
  const familyCodesByPublication = new Map(selectedPackages.map(({ familyCode, package: entry }) => (
    [entry.publicationId, [familyCode]]
  )));
  const applicablePackageMarkup = preview.packageResolution.packages.map((entry) => {
    const familyCodes = familyCodesByPublication.get(entry.publicationId) || [];
    const packagePurpose = familyCodes.length
      ? familyCodes.map((familyCode) => EMPLOYEE_ONBOARDING_START_FAMILY_LABELS[familyCode]).join(" · ")
      : "Zusätzliches anwendbares Paket";
    return `
    <article class="employee-onboarding-start-package">
      <header><div><span class="eyebrow">${escapeHtml(packagePurpose)}</span><h4>${escapeHtml(entry.title)}</h4></div><span class="status-badge warning">Version ${entry.versionNumber}</span></header>
      <label class="employee-onboarding-start-check employee-onboarding-review-check">
        <input type="checkbox" required data-onboarding-review-publication="${escapeHtmlAttribute(entry.publicationId)}"${draft.packageReviews[entry.publicationId] ? " checked" : ""}${disabled}>
        <span>Ich habe dieses Paket und seine Schritte unter dem Lifecycle-Schutzvertrag fachlich geprüft.</span>
      </label>
      <div class="employee-onboarding-start-assignments">${entry.assignments.map((assignment) => {
        if (assignment.responsibility.type === "system") {
          return `<section class="employee-onboarding-start-assignment system"><div><span>Schritt ${assignment.sortOrder}</span><strong>${escapeHtml(assignment.title)}</strong></div><span class="status-badge inactive">Systemschritt · keine externe Aktion</span></section>`;
        }
        const assignmentKey = employeeOnboardingAssignmentDraftKey(entry.publicationId, assignment.stepReference);
        const selectedActorId = draft.assignments[assignmentKey] || "";
        return `<label class="employee-onboarding-start-assignment">
          <span><small>Schritt ${assignment.sortOrder} · ${escapeHtml(assignment.responsibility.label)}</small><strong>${escapeHtml(assignment.title)}</strong></span>
          <select required data-onboarding-assignment-publication="${escapeHtmlAttribute(entry.publicationId)}" data-onboarding-assignment-step="${escapeHtmlAttribute(assignment.stepReference)}"${disabled}>
            <option value="">Verantwortliche Person ausdrücklich auswählen</option>
            ${assignment.eligibleRecipients.map((recipient) => `<option value="${escapeHtmlAttribute(recipient.actorId)}"${recipient.actorId === selectedActorId ? " selected" : ""}>${escapeHtml(recipient.displayName)} · ${escapeHtml(recipient.actorId)}</option>`).join("")}
          </select>
        </label>`;
      }).join("")}</div>
    </article>`;
  }).join("");
  const confirmationMarkup = EMPLOYEE_ONBOARDING_CONFIRMATION_FIELDS.map((field) => `
    <label class="employee-onboarding-start-check">
      <input type="checkbox" required data-onboarding-confirmation="${field}"${draft.confirmations[field] ? " checked" : ""}${disabled}>
      <span>${escapeHtml(EMPLOYEE_ONBOARDING_START_CONFIRMATION_LABELS[field])}</span>
    </label>`).join("");
  return `<section class="employee-onboarding-execution" aria-labelledby="employeeOnboardingStartTitle">
    <header><div><span class="eyebrow">O4 · kontrollierte Ausführung</span><h3 id="employeeOnboardingStartTitle">Onboarding atomar starten</h3><p>Alle Felder beginnen bewusst leer. Der Server prüft Vorschau, Pakete, Rechte und Zuweisungen beim Start erneut.</p></div><span class="status-badge warning">Explizite Freigabe</span></header>
    <form class="employee-onboarding-start-form" data-employee-onboarding-start-form autocomplete="off" aria-busy="${String(draft.pending)}">
      <section class="employee-onboarding-start-section"><h4>1. Referenzdaten</h4><div class="employee-onboarding-date-grid">
        ${[["contractualEntryDate", "Vertraglicher Eintritt"], ["firstWorkingDay", "Erster Arbeitstag"], ["onboardingTargetDate", "Onboarding-Zieldatum"]].map(([field, label]) => `<label class="employee-onboarding-start-field"><span>${label}</span><input type="date" required data-onboarding-reference-date="${field}" value="${escapeHtmlAttribute(draft.referenceDates[field])}"${disabled}></label>`).join("")}
      </div></section>
      <section class="employee-onboarding-start-section"><h4>2. Pflichtfamilien und Pakete</h4><div class="employee-onboarding-family-grid">${familySelectors}</div><p class="employee-onboarding-start-hint">Alle anwendbaren Pakete müssen einzeln geprüft und jeder nicht-systemische Schritt ausdrücklich zugewiesen werden.</p>${applicablePackageMarkup}</section>
      <section class="employee-onboarding-start-section"><h4>3. Verantwortlicher Start</h4><p class="employee-onboarding-responsible">Angemeldete verantwortliche Person: <strong>${escapeHtml(state.portalSession?.user?.fullName || state.portalSession?.user?.nickname || responsibleActorId || "Nicht verfügbar")}</strong></p></section>
      <section class="employee-onboarding-start-section"><h4>4. Ausdrückliche Bestätigungen</h4><div class="employee-onboarding-confirmations">${confirmationMarkup}</div></section>
      <label class="employee-onboarding-start-check employee-onboarding-final-confirmation">
        <input type="checkbox" required data-onboarding-final-confirmation${draft.finalConfirmation ? " checked" : ""}${disabled}>
        <span>Ich bestätige abschließend: <strong>${escapeHtml(execution.requiredConfirmation)}</strong></span>
      </label>
      ${structuralBlocker ? `<p class="employee-onboarding-start-message error" role="alert">${escapeHtml(structuralBlocker)}</p>` : `<p class="employee-onboarding-start-message${draft.error ? " error" : ""}" data-onboarding-start-message role="status" aria-live="polite">${escapeHtml(draft.error)}</p>`}
      <div class="employee-onboarding-start-actions"><button type="submit" class="primary-button"${draft.pending || structuralBlocker ? " disabled" : ""}>${draft.pending ? "Onboarding wird atomar gestartet …" : "Onboarding verbindlich starten"}</button></div>
    </form>
  </section>`;
}

function renderEmployeeProfileOnboarding(preview) {
  const execution = preview.onboardingExecution;
  const controlledExecution = Boolean(execution);
  const previewMarkup = renderEmployeeProfileOnboardingPreview(preview, { controlledExecution });
  if (!execution) return previewMarkup;
  if (execution.activeCase) return `${previewMarkup}${renderEmployeeOnboardingActiveCase(execution.activeCase)}`;
  if (execution.formAvailable && preview.canStartOnboarding === true) {
    return `${previewMarkup}${renderEmployeeOnboardingStartForm(preview)}`;
  }
  return `${previewMarkup}<section class="employee-onboarding-execution-unavailable"><strong>Kontrollierter Start nicht verfügbar</strong><p>Der aktuelle Serverstand gibt für dieses Profil kein Startformular frei.</p></section>`;
}

function captureEmployeeOnboardingStartForm(form) {
  const preview = state.employeeProfileTabData.onboarding;
  const draft = employeeOnboardingStartDraftFor(preview);
  if (!draft || draft.pending) return draft;
  form.querySelectorAll("[data-onboarding-reference-date]").forEach((input) => {
    draft.referenceDates[input.dataset.onboardingReferenceDate] = String(input.value || "").trim();
  });
  form.querySelectorAll("[data-onboarding-family-code]").forEach((select) => {
    draft.packageSelections[select.dataset.onboardingFamilyCode] = String(select.value || "").trim();
  });
  draft.packageReviews = {};
  form.querySelectorAll("[data-onboarding-review-publication]").forEach((input) => {
    draft.packageReviews[input.dataset.onboardingReviewPublication] = input.checked === true;
  });
  draft.assignments = {};
  form.querySelectorAll("[data-onboarding-assignment-publication][data-onboarding-assignment-step]").forEach((select) => {
    draft.assignments[employeeOnboardingAssignmentDraftKey(
      select.dataset.onboardingAssignmentPublication,
      select.dataset.onboardingAssignmentStep,
    )] = String(select.value || "").trim();
  });
  form.querySelectorAll("[data-onboarding-confirmation]").forEach((input) => {
    draft.confirmations[input.dataset.onboardingConfirmation] = input.checked === true;
  });
  draft.finalConfirmation = form.querySelector("[data-onboarding-final-confirmation]")?.checked === true;
  draft.error = "";
  pruneEmployeeOnboardingStartDraft(preview, draft);
  return draft;
}

function employeeOnboardingStartContextIsCurrent(employeeNumber, profileRequestToken, previewSha256) {
  return employeeProfileIsOpen()
    && state.employeeProfileTab === "onboarding"
    && state.employeeProfileEmployeeNumber === employeeNumber
    && state.employeeProfileRequestToken === profileRequestToken
    && state.employeeProfileTabData.onboarding?.onboardingExecution?.previewSha256 === previewSha256;
}

async function reloadEmployeeOnboardingProjection(employeeNumber = state.employeeProfileEmployeeNumber) {
  const normalizedEmployeeNumber = String(employeeNumber || "").trim();
  if (!normalizedEmployeeNumber || !employeeProfileIsOpen()
    || state.employeeProfileTab !== "onboarding"
    || state.employeeProfileEmployeeNumber !== normalizedEmployeeNumber) return;
  state.employeeProfileTabData.onboarding = null;
  delete state.employeeProfileTabErrors.onboarding;
  await loadEmployeeProfileTab("onboarding", normalizedEmployeeNumber);
}

async function submitEmployeeOnboardingStart(event) {
  const form = event.target.closest("[data-employee-onboarding-start-form]");
  if (!form) return;
  event.preventDefault();
  const preview = state.employeeProfileTabData.onboarding;
  const draft = captureEmployeeOnboardingStartForm(form);
  if (!draft || draft.pending) return;
  if (typeof form.reportValidity === "function" && !form.reportValidity()) return;
  let request;
  try {
    request = employeeOnboardingStartRequestWithOperation(
      draft,
      buildEmployeeOnboardingStartRequest(preview, draft),
    );
  } catch (error) {
    draft.error = error.message;
    renderEmployeeProfileContent();
    return;
  }
  const employeeNumber = state.employeeProfileEmployeeNumber;
  const profileRequestToken = state.employeeProfileRequestToken;
  const previewSha256 = preview.onboardingExecution.previewSha256;
  draft.pending = true;
  draft.error = "";
  renderEmployeeProfileContent();
  try {
    const result = await api(`/api/portal/v1/personnel-lifecycle/employees/${encodeURIComponent(employeeNumber)}/onboarding-starts`, {
      method: "POST",
      body: JSON.stringify(request),
    });
    if (!employeeOnboardingStartContextIsCurrent(employeeNumber, profileRequestToken, previewSha256)) return;
    clearEmployeeOnboardingStartState();
    await reloadEmployeeOnboardingProjection(employeeNumber);
    showToast(String(result?.message || "Onboarding wurde atomar gestartet."));
  } catch (error) {
    if (!employeeOnboardingStartContextIsCurrent(employeeNumber, profileRequestToken, previewSha256)) return;
    if ([403, 409].includes(error.status)) {
      clearEmployeeOnboardingStartState();
      showToast(error.message, true);
      await reloadEmployeeOnboardingProjection(employeeNumber);
      return;
    }
    draft.pending = false;
    draft.error = error.message || "Der Onboarding-Start konnte nicht sicher bestätigt werden.";
    renderEmployeeProfileContent();
  }
}

function captureEmployeeOnboardingCloseForm(form) {
  const activeCase = state.employeeProfileTabData.onboarding?.onboardingExecution?.activeCase;
  const draft = employeeOnboardingCloseDraftFor(activeCase);
  if (!draft || draft.pending) return draft;
  draft.confirmed = form.querySelector("[data-onboarding-close-confirmation]")?.checked === true;
  draft.error = "";
  return draft;
}

function employeeOnboardingCloseContextIsCurrent(employeeNumber, profileRequestToken, caseId) {
  return employeeProfileIsOpen()
    && state.employeeProfileTab === "onboarding"
    && state.employeeProfileEmployeeNumber === employeeNumber
    && state.employeeProfileRequestToken === profileRequestToken
    && state.employeeProfileTabData.onboarding?.onboardingExecution?.activeCase?.caseId === caseId;
}

async function submitEmployeeOnboardingClose(event) {
  const form = event.target.closest("[data-employee-onboarding-close-form]");
  if (!form) return;
  event.preventDefault();
  const draft = captureEmployeeOnboardingCloseForm(form);
  if (!draft || draft.pending) return;
  if (typeof form.reportValidity === "function" && !form.reportValidity()) return;
  if (!draft.confirmed) {
    draft.error = "Bitte CLOSE_ONBOARDING ausdrücklich bestätigen.";
    renderEmployeeProfileContent();
    return;
  }
  if (!draft.operationId) {
    draft.operationId = globalThis.crypto?.randomUUID?.() || "";
    if (!draft.operationId) {
      draft.error = "Für den sicheren Abschluss konnte keine Vorgangs-ID erzeugt werden.";
      renderEmployeeProfileContent();
      return;
    }
  }
  const employeeNumber = state.employeeProfileEmployeeNumber;
  const profileRequestToken = state.employeeProfileRequestToken;
  const caseId = draft.caseId;
  draft.pending = true;
  draft.error = "";
  renderEmployeeProfileContent();
  try {
    const result = await api(`/api/portal/v1/personnel-lifecycle/onboarding/cases/${encodeURIComponent(caseId)}/close`, {
      method: "POST",
      body: JSON.stringify({
        operationId: draft.operationId,
        confirmation: "CLOSE_ONBOARDING",
        evidenceReference: null,
      }),
    });
    if (!employeeOnboardingCloseContextIsCurrent(employeeNumber, profileRequestToken, caseId)) return;
    clearEmployeeOnboardingStartState();
    await reloadEmployeeOnboardingProjection(employeeNumber);
    showToast(String(result?.message || "Onboarding-Fall wurde abgeschlossen."));
  } catch (error) {
    if (!employeeOnboardingCloseContextIsCurrent(employeeNumber, profileRequestToken, caseId)) return;
    if ([403, 409].includes(error.status)) {
      clearEmployeeOnboardingStartState();
      showToast(error.message, true);
      await reloadEmployeeOnboardingProjection(employeeNumber);
      return;
    }
    draft.pending = false;
    draft.error = error.message || "Der Onboarding-Abschluss konnte nicht sicher bestätigt werden.";
    renderEmployeeProfileContent();
  }
}

const EMPLOYEE_OFFBOARDING_STATE_LABELS = Object.freeze({
  internally_prepared: "Intern vorbereitet",
  communication_released: "Kommunikation freigegeben",
  employee_informed: "Mitarbeiter/-in informiert",
  active: "In Ausführung",
  completed: "Abgeschlossen",
  cancelled: "Abgebrochen",
});

const EMPLOYEE_OFFBOARDING_ACTIONS = Object.freeze({
  approveTimeCritical: Object.freeze({
    route: "time-critical-approvals",
    confirmation: "CONFIRM_TIME_CRITICAL_OFFBOARDING",
    label: "Zeitkritische Ausnahme freigeben",
    reason: true,
  }),
  releaseCommunication: Object.freeze({
    route: "communication-releases",
    confirmation: "RELEASE_OFFBOARDING_COMMUNICATION",
    label: "Kommunikation verbindlich freigeben",
    reason: true,
  }),
  confirmInformation: Object.freeze({
    route: "information-confirmations",
    confirmation: "CONFIRM_OFFBOARDING_INFORMATION",
    label: "Information bestätigen",
    informedAt: true,
  }),
  activate: Object.freeze({
    route: "activations",
    confirmation: "ACTIVATE_OFFBOARDING",
    label: "Ausführung aktivieren",
  }),
  cancel: Object.freeze({
    route: "cancellations",
    confirmation: "CANCEL_OFFBOARDING",
    label: "Offboarding kontrolliert abbrechen",
    reason: true,
    danger: true,
  }),
  close: Object.freeze({
    route: "closures",
    confirmation: "CLOSE_OFFBOARDING",
    label: "Offboarding-Fall abschließen",
  }),
});

function employeeOffboardingDraftFor(offboarding) {
  const caseKey = offboarding?.case
    ? `${offboarding.case.caseId}:${offboarding.case.revision}`
    : `prepare:${state.employeeProfileEmployeeNumber}`;
  if (!state.employeeOffboardingDraft || state.employeeOffboardingDraft.key !== caseKey) {
    state.employeeOffboardingDraft = {
      key: caseKey,
      pending: "",
      error: "",
      operationIds: {},
      requestFingerprints: {},
    };
  }
  return state.employeeOffboardingDraft;
}

function clearEmployeeOffboardingState() {
  state.employeeOffboardingDraft = null;
}

function employeeOffboardingDateTimeInputValue(value) {
  const parsed = new Date(String(value || ""));
  if (Number.isNaN(parsed.getTime())) return "";
  const offset = parsed.getTimezoneOffset() * 60_000;
  return new Date(parsed.getTime() - offset).toISOString().slice(0, 16);
}

function employeeOffboardingIsoFromInput(value, label) {
  const normalized = String(value || "").trim();
  const parsed = new Date(normalized);
  if (!normalized || Number.isNaN(parsed.getTime())) {
    throw new Error(`${label} ist ungültig.`);
  }
  return parsed.toISOString();
}

function employeeOffboardingOperationId(draft, action, requestBody) {
  const fingerprint = JSON.stringify(requestBody);
  if (!draft.operationIds[action] || draft.requestFingerprints[action] !== fingerprint) {
    const operationId = globalThis.crypto?.randomUUID?.();
    if (!operationId) throw new Error("Für die sichere Offboarding-Aktion konnte keine Vorgangs-ID erzeugt werden.");
    draft.operationIds[action] = operationId.toLowerCase();
    draft.requestFingerprints[action] = fingerprint;
  }
  return draft.operationIds[action];
}

function renderEmployeeOffboardingPreparation(offboarding) {
  const preparation = offboarding.preparation;
  if (!preparation.available) {
    return `<section class="employee-offboarding-boundary"><strong>Keine neue Vorbereitung möglich</strong><p>Der Server hat für dieses Profil keine vertrauliche Vorbereitung freigegeben.</p></section>`;
  }
  const draft = employeeOffboardingDraftFor(offboarding);
  const disabled = draft.pending ? " disabled" : "";
  const packageMarkup = preparation.packages.map((entry) => {
    const candidateOptions = entry.candidates.map((candidate) => (
      `<option value="${escapeHtmlAttribute(candidate.actorId)}">${escapeHtml(candidate.displayName)} · ${escapeHtml(candidate.roleLabel)}</option>`
    )).join("");
    return `<article class="employee-offboarding-package" data-offboarding-family="${escapeHtmlAttribute(entry.familyCode)}">
    <header><strong>${escapeHtml(entry.title || EMPLOYEE_OFFBOARDING_FAMILIES[entry.familyCode])}</strong><span class="status-badge inactive">Noch nicht freigegeben</span></header>
    <label class="field"><span>Zuständige Fachperson</span><select required data-offboarding-assignee="${escapeHtmlAttribute(entry.familyCode)}"${disabled}><option value="">Bitte auswählen</option>${candidateOptions}</select></label>
    <label class="field"><span>Geschützter Auftragstitel</span><input required maxlength="160" data-offboarding-title="${escapeHtmlAttribute(entry.familyCode)}" value="${escapeHtmlAttribute(entry.title || EMPLOYEE_OFFBOARDING_FAMILIES[entry.familyCode])}"${disabled}></label>
    <label class="field"><span>Geschützte Arbeitsanweisung</span><textarea required maxlength="4000" rows="3" data-offboarding-instructions="${escapeHtmlAttribute(entry.familyCode)}"${disabled}></textarea></label>
  </article>`;
  }).join("");
  const blocked = preparation.packages.some(({ candidates }) => candidates.length === 0);
  return `<section class="employee-offboarding-workspace" aria-labelledby="employeeOffboardingPrepareTitle">
    <header><div><span class="eyebrow">O5 · streng vertraulich</span><h3 id="employeeOffboardingPrepareTitle">Offboarding intern vorbereiten</h3><p>Vor der ausdrücklichen Kommunikationsfreigabe entstehen keine sichtbaren Aufgaben, Zähler, Meldungen oder Kalenderhinweise.</p></div><span class="status-badge warning">Nur berechtigte Personen</span></header>
    <form data-employee-offboarding-prepare autocomplete="off" aria-busy="${String(Boolean(draft.pending))}">
      <section class="employee-onboarding-start-section"><h4>1. Referenztermine</h4><div class="employee-onboarding-date-grid">
        <label class="field"><span>Geplanter Austrittszeitpunkt</span><input type="datetime-local" required data-offboarding-reference="plannedExitAt"${disabled}></label>
        <label class="field"><span>Letzter Arbeitstag</span><input type="date" required data-offboarding-reference="lastWorkingDay"${disabled}></label>
        <label class="field"><span>Rechtliches Austrittsdatum</span><input type="date" required data-offboarding-reference="legalExitDate"${disabled}></label>
        <label class="field"><span>Zugriffssperrzeitpunkt</span><input type="datetime-local" required data-offboarding-reference="accessBlockAt"${disabled}></label>
      </div></section>
      <section class="employee-onboarding-start-section"><h4>2. Geschützter Fallinhalt</h4><div class="employee-onboarding-date-grid">
        <label class="field"><span>Grundcode</span><input required maxlength="80" pattern="[a-z][a-z0-9_]{1,79}" data-offboarding-exit-code placeholder="z. B. employee_notice"${disabled}></label>
        <label class="field"><span>Dringlichkeit</span><select required data-offboarding-urgency${disabled}><option value="standard">Standard</option><option value="time_critical">Zeitkritische Ausnahme</option></select></label>
        <label class="field"><span>Ausnahmegrund-Code (nur zeitkritisch)</span><input maxlength="80" pattern="[a-z][a-z0-9_]{1,79}" data-offboarding-exception-code${disabled}></label>
        <label class="field"><span>Nacharbeit bis (nur zeitkritisch)</span><input type="datetime-local" data-offboarding-follow-up${disabled}></label>
      </div>
      <label class="field"><span>Geschützte Begründung</span><textarea required maxlength="2000" rows="3" data-offboarding-exit-note${disabled}></textarea></label>
      <label class="field"><span>Vertraulicher PL-Vermerk</span><textarea maxlength="4000" rows="3" data-offboarding-hr-note${disabled}></textarea></label>
      <label class="field"><span>Dokumentreferenzen (eine pro Zeile)</span><textarea maxlength="4000" rows="2" data-offboarding-documents${disabled}></textarea></label>
      <label class="field"><span>Begründung der zeitkritischen Ausnahme</span><textarea maxlength="2000" rows="2" data-offboarding-exception-note${disabled}></textarea></label></section>
      <section class="employee-onboarding-start-section"><h4>3. Sechs Pflichtfamilien</h4><div class="employee-offboarding-package-list">${packageMarkup}</div></section>
      <label class="employee-onboarding-start-check employee-onboarding-final-confirmation"><input type="checkbox" required data-offboarding-prepare-confirm${disabled}><span>Ich bestätige die rein interne Vorbereitung mit <strong>PREPARE_OFFBOARDING</strong>.</span></label>
      ${blocked ? '<p class="employee-onboarding-start-message error">Es steht keine berechtigte Fachperson für die Pflichtzuweisungen zur Verfügung.</p>' : `<p class="employee-onboarding-start-message${draft.error ? " error" : ""}" role="status" aria-live="polite">${escapeHtml(draft.error)}</p>`}
      <div class="employee-onboarding-start-actions"><button type="submit" class="primary-button"${disabled}${blocked ? " disabled" : ""}>${draft.pending ? "Vorbereitung wird geschützt gespeichert …" : "Internes Offboarding vorbereiten"}</button></div>
    </form>
  </section>`;
}

function renderEmployeeOffboardingAction(action, currentCase, draft) {
  const definition = EMPLOYEE_OFFBOARDING_ACTIONS[action];
  if (!definition || currentCase.allowedActions[action] !== true) return "";
  const disabled = draft.pending ? " disabled" : "";
  const reasonMarkup = definition.reason ? `<div class="employee-onboarding-date-grid">
    <label class="field"><span>Grundcode</span><input required maxlength="80" pattern="[a-z][a-z0-9_]{1,79}" data-offboarding-action-reason-code${disabled}></label>
    <label class="field"><span>Dokumentreferenzen (eine pro Zeile)</span><textarea rows="2" data-offboarding-action-documents${disabled}></textarea></label>
  </div><label class="field"><span>Geschützte Begründung</span><textarea required maxlength="2000" rows="2" data-offboarding-action-reason-note${disabled}></textarea></label>` : "";
  const informedMarkup = definition.informedAt
    ? `<label class="field"><span>Tatsächlicher Informationszeitpunkt</span><input type="datetime-local" required data-offboarding-informed-at${disabled}></label>`
    : "";
  return `<form class="employee-offboarding-action${definition.danger ? " danger" : ""}" data-employee-offboarding-action="${escapeHtmlAttribute(action)}" aria-busy="${String(draft.pending === action)}">
    <h4>${escapeHtml(definition.label)}</h4>${reasonMarkup}${informedMarkup}
    <label class="employee-onboarding-start-check"><input type="checkbox" required data-offboarding-action-confirm${disabled}><span>Ich bestätige ausdrücklich: <strong>${escapeHtml(definition.confirmation)}</strong></span></label>
    <button type="submit" class="${definition.danger ? "danger-button" : "primary-button"}"${disabled}>${draft.pending === action ? "Wird sicher verarbeitet …" : escapeHtml(definition.label)}</button>
  </form>`;
}

function renderEmployeeOffboardingCase(offboarding) {
  const currentCase = offboarding.case;
  const draft = employeeOffboardingDraftFor(offboarding);
  const packageMarkup = currentCase.packages.map((entry) => `<article class="employee-offboarding-package">
    <header><strong>${escapeHtml(entry.title)}</strong><span class="status-badge${entry.status === "complete" ? "" : " warning"}">${escapeHtml(entry.status)}</span></header>
    <p>${escapeHtml(entry.assigneeDisplayName)} · ${escapeHtml(entry.recipientClass)}</p>
  </article>`).join("");
  const actionMarkup = Object.keys(EMPLOYEE_OFFBOARDING_ACTIONS)
    .map((action) => renderEmployeeOffboardingAction(action, currentCase, draft)).join("");
  return `<section class="employee-offboarding-workspace" aria-labelledby="employeeOffboardingCaseTitle">
    <header><div><span class="eyebrow">O5 · vertraulicher Fall</span><h3 id="employeeOffboardingCaseTitle">${escapeHtml(EMPLOYEE_OFFBOARDING_STATE_LABELS[currentCase.state])}</h3><p>Revision ${currentCase.revision} · Verantwortlich: ${escapeHtml(currentCase.responsibleActorId)}</p></div><span class="status-badge warning">Nicht allgemein sichtbar</span></header>
    <div class="employee-profile-overview-grid">
      <article class="employee-profile-overview-card"><span>Letzter Arbeitstag</span><strong>${escapeHtml(formatDate(currentCase.referenceTimes.lastWorkingDay, undefined, currentCase.referenceTimes.lastWorkingDay))}</strong></article>
      <article class="employee-profile-overview-card"><span>Rechtliches Austrittsdatum</span><strong>${escapeHtml(formatDate(currentCase.referenceTimes.legalExitDate, undefined, currentCase.referenceTimes.legalExitDate))}</strong></article>
      <article class="employee-profile-overview-card"><span>Zugriffssperre geplant</span><strong>${escapeHtml(employeeProfileFormatTimestamp(currentCase.referenceTimes.accessBlockAt))}</strong></article>
      <article class="employee-profile-overview-card"><span>Dringlichkeit</span><strong>${currentCase.urgency.mode === "time_critical" ? `Zeitkritisch · ${currentCase.urgency.approved ? "freigegeben" : "Freigabe ausstehend"}` : "Standard"}</strong></article>
    </div>
    <section class="employee-offboarding-confidential"><h4>Vertraulicher Fallinhalt</h4><p><strong>${escapeHtml(currentCase.confidential.exitReasonCode)}</strong> · ${escapeHtml(currentCase.confidential.exitReasonNote)}</p>${currentCase.confidential.hrNote ? `<p>${escapeHtml(currentCase.confidential.hrNote)}</p>` : ""}</section>
    <section><h4>Pflichtfamilien</h4><div class="employee-offboarding-package-list">${packageMarkup}</div></section>
    ${draft.error ? `<p class="employee-onboarding-start-message error" role="alert">${escapeHtml(draft.error)}</p>` : ""}
    ${actionMarkup ? `<section class="employee-offboarding-actions"><h4>Kontrollierte nächste Schritte</h4>${actionMarkup}</section>` : '<p class="employee-profile-boundary">Für den aktuellen Zustand ist keine weitere Aktion freigegeben.</p>'}
  </section>`;
}

function renderEmployeeProfileOffboarding(offboarding) {
  return offboarding.case
    ? renderEmployeeOffboardingCase(offboarding)
    : renderEmployeeOffboardingPreparation(offboarding);
}

function employeeOffboardingCurrentContext(employeeNumber, profileRequestToken, caseId = null) {
  return employeeProfileIsOpen()
    && state.employeeProfileTab === "offboarding"
    && state.employeeProfileEmployeeNumber === employeeNumber
    && state.employeeProfileRequestToken === profileRequestToken
    && (caseId === null
      || state.employeeProfileTabData.offboarding?.case?.caseId === caseId);
}

async function reloadEmployeeOffboardingProjection(employeeNumber = state.employeeProfileEmployeeNumber) {
  const normalizedEmployeeNumber = String(employeeNumber || "").trim();
  if (!employeeOffboardingCurrentContext(
    normalizedEmployeeNumber,
    state.employeeProfileRequestToken,
  )) return;
  state.employeeProfileTabData.offboarding = null;
  delete state.employeeProfileTabErrors.offboarding;
  await loadEmployeeProfileTab("offboarding", normalizedEmployeeNumber);
}

async function submitEmployeeOffboardingPreparation(event) {
  const form = event.target.closest("[data-employee-offboarding-prepare]");
  if (!form) return;
  event.preventDefault();
  if (typeof form.reportValidity === "function" && !form.reportValidity()) return;
  const offboarding = state.employeeProfileTabData.offboarding;
  const draft = employeeOffboardingDraftFor(offboarding);
  if (!offboarding || draft.pending) return;
  try {
    const references = Object.fromEntries([...form.querySelectorAll("[data-offboarding-reference]")]
      .map((input) => [input.dataset.offboardingReference, String(input.value || "").trim()]));
    const urgencyMode = String(form.querySelector("[data-offboarding-urgency]")?.value || "");
    const assignments = offboarding.preparation.packages.map((entry) => ({
      familyCode: entry.familyCode,
      assigneeActorId: String(form.querySelector(`[data-offboarding-assignee="${entry.familyCode}"]`)?.value || "").trim(),
      title: String(form.querySelector(`[data-offboarding-title="${entry.familyCode}"]`)?.value || "").trim(),
      instructions: String(form.querySelector(`[data-offboarding-instructions="${entry.familyCode}"]`)?.value || "").trim(),
    }));
    const requestWithoutOperation = {
      confirmation: "PREPARE_OFFBOARDING",
      referenceTimes: {
        plannedExitAt: employeeOffboardingIsoFromInput(references.plannedExitAt, "Der geplante Austrittszeitpunkt"),
        lastWorkingDay: references.lastWorkingDay,
        legalExitDate: references.legalExitDate,
        accessBlockAt: employeeOffboardingIsoFromInput(references.accessBlockAt, "Der Zugriffssperrzeitpunkt"),
      },
      urgency: urgencyMode === "time_critical" ? {
        mode: "time_critical",
        confirmation: "CONFIRM_TIME_CRITICAL_OFFBOARDING",
        exceptionReason: {
          code: String(form.querySelector("[data-offboarding-exception-code]")?.value || "").trim(),
          note: String(form.querySelector("[data-offboarding-exception-note]")?.value || "").trim(),
        },
        followUpDueAt: employeeOffboardingIsoFromInput(
          form.querySelector("[data-offboarding-follow-up]")?.value,
          "Der Nacharbeitstermin",
        ),
      } : {
        mode: "standard",
        confirmation: null,
        exceptionReason: null,
        followUpDueAt: null,
      },
      exitReason: {
        code: String(form.querySelector("[data-offboarding-exit-code]")?.value || "").trim(),
        note: String(form.querySelector("[data-offboarding-exit-note]")?.value || "").trim(),
      },
      hrNote: String(form.querySelector("[data-offboarding-hr-note]")?.value || "").trim(),
      documentReferenceIds: String(form.querySelector("[data-offboarding-documents]")?.value || "")
        .split(/\r?\n/).map((entry) => entry.trim()).filter(Boolean),
      assignments,
    };
    const operationId = employeeOffboardingOperationId(
      draft,
      "prepare",
      requestWithoutOperation,
    );
    const employeeNumber = state.employeeProfileEmployeeNumber;
    const profileRequestToken = state.employeeProfileRequestToken;
    draft.pending = "prepare";
    draft.error = "";
    renderEmployeeProfileContent();
    await api(`/api/portal/v1/personnel-lifecycle/employees/${encodeURIComponent(employeeNumber)}/offboarding-preparations`, {
      method: "POST",
      body: JSON.stringify({ operationId, ...requestWithoutOperation }),
    });
    if (!employeeOffboardingCurrentContext(employeeNumber, profileRequestToken)) return;
    clearEmployeeOffboardingState();
    await reloadEmployeeOffboardingProjection(employeeNumber);
    showToast("Offboarding wurde ausschließlich intern vorbereitet.");
  } catch (error) {
    const currentDraft = state.employeeOffboardingDraft;
    if (!currentDraft) return;
    currentDraft.pending = "";
    currentDraft.error = error.message || "Die interne Vorbereitung konnte nicht sicher gespeichert werden.";
    renderEmployeeProfileContent();
  }
}

async function submitEmployeeOffboardingAction(event) {
  const form = event.target.closest("[data-employee-offboarding-action]");
  if (!form) return;
  event.preventDefault();
  if (typeof form.reportValidity === "function" && !form.reportValidity()) return;
  const action = String(form.dataset.employeeOffboardingAction || "");
  const definition = EMPLOYEE_OFFBOARDING_ACTIONS[action];
  const offboarding = state.employeeProfileTabData.offboarding;
  const currentCase = offboarding?.case;
  const draft = employeeOffboardingDraftFor(offboarding);
  if (!definition || !currentCase || currentCase.allowedActions[action] !== true || draft.pending) return;
  const requestWithoutOperation = {
    expectedRevision: currentCase.revision,
    confirmation: definition.confirmation,
  };
  if (definition.reason) {
    requestWithoutOperation.reason = {
      code: String(form.querySelector("[data-offboarding-action-reason-code]")?.value || "").trim(),
      note: String(form.querySelector("[data-offboarding-action-reason-note]")?.value || "").trim(),
      documentReferenceIds: String(form.querySelector("[data-offboarding-action-documents]")?.value || "")
        .split(/\r?\n/).map((entry) => entry.trim()).filter(Boolean),
    };
  }
  if (definition.informedAt) {
    try {
      requestWithoutOperation.employeeInformedAt = employeeOffboardingIsoFromInput(
        form.querySelector("[data-offboarding-informed-at]")?.value,
        "Der Informationszeitpunkt",
      );
    } catch (error) {
      draft.error = error.message;
      renderEmployeeProfileContent();
      return;
    }
  }
  const employeeNumber = state.employeeProfileEmployeeNumber;
  const profileRequestToken = state.employeeProfileRequestToken;
  const caseId = currentCase.caseId;
  try {
    const operationId = employeeOffboardingOperationId(draft, action, requestWithoutOperation);
    draft.pending = action;
    draft.error = "";
    renderEmployeeProfileContent();
    await api(`/api/portal/v1/personnel-lifecycle/offboarding/cases/${encodeURIComponent(caseId)}/${definition.route}`, {
      method: "POST",
      body: JSON.stringify({ operationId, ...requestWithoutOperation }),
    });
    if (!employeeOffboardingCurrentContext(employeeNumber, profileRequestToken, caseId)) return;
    clearEmployeeOffboardingState();
    await reloadEmployeeOffboardingProjection(employeeNumber);
    showToast(`${definition.label} wurde sicher verarbeitet.`);
  } catch (error) {
    if (!employeeOffboardingCurrentContext(employeeNumber, profileRequestToken, caseId)) return;
    if ([403, 404, 409].includes(error.status)) {
      clearEmployeeOffboardingState();
      showToast(error.message, true);
      await reloadEmployeeOffboardingProjection(employeeNumber);
      return;
    }
    draft.pending = "";
    draft.error = error.message || "Die Offboarding-Aktion konnte nicht sicher bestätigt werden.";
    renderEmployeeProfileContent();
  }
}

function renderEmployeeProfileContent() {
  if (!elements.employeeProfileContent) return;
  const selectedTab = employeeProfileTabDefinition() ? state.employeeProfileTab : "";
  document.querySelectorAll("[data-employee-profile-tab]").forEach((button) => {
    const active = button.dataset.employeeProfileTab === selectedTab;
    const tab = employeeProfileTabDefinition(button.dataset.employeeProfileTab);
    const available = tab?.endpointTab
      ? state.employeeProfileTabAvailability[tab.id] === true
      : false;
    button.classList.toggle("active", active);
    button.classList.toggle("available", available);
    button.setAttribute("aria-selected", String(active));
    button.dataset.employeeProfileAvailable = String(available);
    button.tabIndex = active ? 0 : -1;
  });
  const activeTabButton = document.querySelector(`[data-employee-profile-tab="${selectedTab}"]`);
  if (activeTabButton?.id) elements.employeeProfileContent.setAttribute("aria-labelledby", activeTabButton.id);
  const activeLoading = employeeProfileTabIsLoading(selectedTab);
  const activeError = state.employeeProfileTabErrors[selectedTab] || state.employeeProfileLoadError;
  state.employeeProfileLoading = state.employeeProfileLoadingTabs.size > 0;
  const accessPending = state.employeeProfileTabAvailability[selectedTab] === null
    && state.employeeProfileLoading;
  if (elements.employeeProfileShell) elements.employeeProfileShell.setAttribute("aria-busy", String(activeLoading || accessPending));
  if (elements.employeeProfileMessage) elements.employeeProfileMessage.textContent = activeError;

  if (!selectedTab) {
    elements.employeeProfileContent.innerHTML = '<div class="employee-profile-empty employee-profile-locked"><span class="employee-profile-lock" aria-hidden="true">↗</span><strong>Bereich nicht verfügbar</strong><p>Dieser Profilbereich ist nicht freigegeben. Es wurden keine Daten geladen.</p></div>';
    return;
  }
  const selectedDefinition = employeeProfileTabDefinition(selectedTab);
  if (!selectedDefinition.endpointTab) {
    elements.employeeProfileContent.innerHTML = `<div class="employee-profile-empty employee-profile-locked">
      <span class="employee-profile-lock" aria-hidden="true">↗</span>
      <strong>${escapeHtml(selectedDefinition.label)}</strong>
      <p>Dieser Bereich ist im Grundgerüst vorbereitet, aber noch nicht freigeschaltet. Es werden keine zusätzlichen Daten geladen.</p>
    </div>`;
    return;
  }
  if (state.employeeProfileTabAvailability[selectedTab] !== true) {
    const pending = state.employeeProfileTabAvailability[selectedTab] === null
      && employeeProfileTabIsLoading("overview");
    elements.employeeProfileContent.innerHTML = `<div class="employee-profile-empty employee-profile-locked">
      <span class="employee-profile-lock" aria-hidden="true">↗</span>
      <strong>${pending ? "Berechtigungen werden geprüft" : "Bereich nicht freigegeben"}</strong>
      <p>${pending ? "Die Profilübersicht ermittelt zunächst die verfügbaren Bereiche." : "Es wurden keine Daten für diesen Profilbereich geladen."}</p>
    </div>`;
    return;
  }
  if (activeLoading) {
    elements.employeeProfileContent.innerHTML = `<div class="employee-profile-empty"><strong>${escapeHtml(selectedDefinition.label)} wird geladen</strong><p>Bitte einen Moment warten.</p></div>`;
    return;
  }
  if (activeError) {
    elements.employeeProfileContent.innerHTML = `<div class="employee-profile-empty"><strong>${escapeHtml(selectedDefinition.label)} nicht verfügbar</strong><p>Es werden keine Daten dieses Profilbereichs angezeigt.</p></div>`;
    return;
  }
  if (selectedTab === "masterData") {
    const data = state.employeeProfileTabData.masterData;
    elements.employeeProfileContent.innerHTML = data
      ? renderEmployeeProfileMasterData(data)
      : '<div class="employee-profile-empty"><strong>Stammdaten nicht geladen</strong><p>Es werden keine Profildaten angezeigt.</p></div>';
    return;
  }
  if (selectedTab === "documents") {
    const documents = state.employeeProfileTabData.documents;
    elements.employeeProfileContent.innerHTML = Array.isArray(documents)
      ? renderEmployeeProfileDocuments(documents)
      : '<div class="employee-profile-empty"><strong>Dokumente nicht geladen</strong><p>Es werden keine Dokumentmetadaten angezeigt.</p></div>';
    return;
  }
  if (selectedTab === "onboarding") {
    const onboardingPreview = state.employeeProfileTabData.onboarding;
    elements.employeeProfileContent.innerHTML = onboardingPreview
      ? renderEmployeeProfileOnboarding(onboardingPreview)
      : '<div class="employee-profile-empty"><strong>Onboarding-Vorschau nicht geladen</strong><p>Es werden keine Lifecycle-Daten angezeigt.</p></div>';
    return;
  }
  if (selectedTab === "offboarding") {
    const offboarding = state.employeeProfileTabData.offboarding;
    elements.employeeProfileContent.innerHTML = offboarding
      ? renderEmployeeProfileOffboarding(offboarding)
      : '<div class="employee-profile-empty"><strong>Vertrauliches Offboarding nicht geladen</strong><p>Es werden keine Lifecycle-Daten angezeigt.</p></div>';
    return;
  }
  if (!state.employeeProfile) {
    elements.employeeProfileContent.innerHTML = '<div class="employee-profile-empty"><strong>Übersicht nicht verfügbar</strong><p>Es werden keine Profildaten angezeigt.</p></div>';
    return;
  }
  const organization = state.employeeProfile.organization;
  const overviewRows = [
    ["Position", organization.positionName || "Nicht hinterlegt"],
    ["Kostenstelle", employeeProfileReferenceLabel(organization.costCenter, { includeCode: true })],
    ["Standort", employeeProfileReferenceLabel(organization.location)],
    ["Abteilung", employeeProfileReferenceLabel(organization.department)],
  ];
  elements.employeeProfileContent.innerHTML = `<div class="employee-profile-overview-grid">${overviewRows.map(([label, value]) => `
    <article class="employee-profile-overview-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></article>`).join("")}</div>
    <p class="employee-profile-boundary">Diese Übersicht enthält ausschließlich freigegebene Organisationsdaten. Geschützte Personalakt- und Prozessdaten werden nicht mitgeladen.</p>`;
}

function renderEmployeeProfile() {
  renderEmployeeProfileHeader();
  renderEmployeeProfileContent();
}

function syncEmployeeProfileWorkspace() {
  const open = employeeProfileIsOpen();
  const teamHost = state.employeeProfileHost === "team";
  const host = teamHost ? elements.employeeProfileTeamMount : elements.employeeProfileAdministrationMount;
  if (host && elements.employeeProfileWorkspace?.parentElement !== host) {
    host.append(elements.employeeProfileWorkspace);
  }
  elements.personnelDirectoryWorkspace?.classList.toggle("hidden", open && !teamHost);
  elements.teamDirectoryWorkspace?.classList.toggle("hidden", open && teamHost);
  elements.employeeProfileWorkspace?.classList.toggle("hidden", !open);
  elements.personnelDisplayColumnsButton?.classList.toggle("hidden", state.personnelAdministrationTab !== "employees" || (open && !teamHost));
  elements.teamDisplayColumnsButton?.classList.toggle("hidden", state.personnelTab !== "employees" || (open && teamHost));
}

function employeeProfileSensitiveAccessWasExposed(tabId) {
  return state.employeeProfileTabAvailability[tabId] === true
    || state.employeeProfileTabData[tabId] !== null
    || state.employeeProfileLoadingTabs.has(tabId)
    || Object.hasOwn(state.employeeProfileTabRequestTokens, tabId);
}

function reconcileOpenEmployeeProfileAccess(access = {}) {
  if (!employeeProfileIsOpen()) return true;
  const masterDataFieldAccessChanged = employeeProfileSensitiveAccessWasExposed("masterData")
    && access.masterData === true
    && typeof state.employeeProfileTabAccessFingerprints.masterData === "string"
    && state.employeeProfileTabAccessFingerprints.masterData
      !== String(access.masterDataFieldFingerprint || "");
  const sensitiveAccessLost = (
    employeeProfileSensitiveAccessWasExposed("masterData") && access.masterData !== true
  ) || (
    employeeProfileSensitiveAccessWasExposed("documents") && access.documents !== true
  ) || (
    employeeProfileSensitiveAccessWasExposed("onboarding") && access.onboarding !== true
  ) || (
    employeeProfileSensitiveAccessWasExposed("offboarding") && access.offboarding !== true
  );
  const selectedAccessAvailable = state.employeeProfileTab === "onboarding"
    ? access.onboarding === true
    : state.employeeProfileTab === "offboarding"
      ? access.offboarding === true
      : access.read === true;
  if (!selectedAccessAvailable || sensitiveAccessLost || masterDataFieldAccessChanged) {
    closeEmployeeProfile({ restoreFocus: false });
    return false;
  }
  return true;
}

function clearEmployeeProfileSensitiveTabs({ except = "" } = {}) {
  for (const tabId of ["masterData", "documents", "onboarding", "offboarding"]) {
    if (tabId === except) continue;
    if (tabId === "onboarding") clearEmployeeOnboardingStartState();
    if (tabId === "offboarding") clearEmployeeOffboardingState();
    state.employeeProfileTabData[tabId] = null;
    delete state.employeeProfileTabErrors[tabId];
    delete state.employeeProfileTabRequestTokens[tabId];
    delete state.employeeProfileTabAccessFingerprints[tabId];
    state.employeeProfileLoadingTabs.delete(tabId);
  }
}

function resetEmployeeProfileData({ accessPending = false, initialTab = "overview" } = {}) {
  clearEmployeeOnboardingStartState();
  clearEmployeeOffboardingState();
  state.employeeProfile = null;
  state.employeeProfileTabData = {
    masterData: null,
    documents: null,
    onboarding: null,
    offboarding: null,
  };
  state.employeeProfileTabAvailability = {
    overview: initialTab === "overview" ? true : (accessPending ? null : false),
    masterData: accessPending ? null : false,
    documents: accessPending ? null : false,
    onboarding: initialTab === "onboarding" ? true : (accessPending ? null : false),
    offboarding: initialTab === "offboarding" ? true : (accessPending ? null : false),
  };
  state.employeeProfileLoadingTabs = new Set();
  state.employeeProfileTabErrors = {};
  state.employeeProfileTabRequestTokens = {};
  state.employeeProfileTabAccessFingerprints = {};
  state.employeeProfileLoading = false;
}

function invalidateEmployeeProfileData(message) {
  state.employeeProfileRequestToken = Symbol("employee-profile-invalidated");
  state.employeeProfileEmployeeNumber = "";
  resetEmployeeProfileData();
  state.employeeProfileLoadError = String(message || "Der Profilzugriff ist nicht mehr verfügbar.");
  renderEmployeeProfile();
}

function setEmployeeProfileTab(tab, { focus = false } = {}) {
  const definition = employeeProfileTabDefinition(tab);
  if (!definition) {
    clearEmployeeProfileSensitiveTabs();
    state.employeeProfileTab = "";
    renderEmployeeProfileContent();
    return;
  }
  if (state.employeeProfileTab !== definition.id) clearEmployeeProfileSensitiveTabs({ except: definition.id });
  state.employeeProfileTab = definition.id;
  renderEmployeeProfileContent();
  if (focus) document.querySelector(`[data-employee-profile-tab="${definition.id}"]`)?.focus();
  if (definition.endpointTab && state.employeeProfileTabAvailability[definition.id] === true) {
    loadEmployeeProfileTab(definition.id);
  }
}

function employeeProfileTabHasData(tabId) {
  if (tabId === "overview") return Boolean(state.employeeProfile);
  if (tabId === "masterData") return Boolean(state.employeeProfileTabData.masterData);
  if (tabId === "documents") return Array.isArray(state.employeeProfileTabData.documents);
  if (tabId === "onboarding") return Boolean(state.employeeProfileTabData.onboarding);
  if (tabId === "offboarding") return Boolean(state.employeeProfileTabData.offboarding);
  return false;
}

function ensureEmployeeProfileActiveTabLoaded() {
  const definition = employeeProfileTabDefinition();
  if (!definition?.endpointTab || state.employeeProfileTabAvailability[definition.id] !== true
    || employeeProfileTabHasData(definition.id) || employeeProfileTabIsLoading(definition.id)) return;
  loadEmployeeProfileTab(definition.id);
}

async function loadEmployeeProfileTab(tabId, employeeNumber = state.employeeProfileEmployeeNumber) {
  const definition = employeeProfileTabDefinition(tabId);
  const normalizedEmployeeNumber = String(employeeNumber || "").trim();
  if (!definition?.endpointTab || !normalizedEmployeeNumber || !employeeProfileIsOpen()
    || state.employeeProfileTabAvailability[tabId] !== true
    || employeeProfileTabHasData(tabId) || employeeProfileTabIsLoading(tabId)) return;
  const profileRequestToken = state.employeeProfileRequestToken;
  const requestToken = Symbol(`employee-profile-${definition.endpointTab}`);
  state.employeeProfileTabRequestTokens[tabId] = requestToken;
  if (tabId === "masterData") {
    state.employeeProfileTabAccessFingerprints.masterData = String(
      currentEmployeeProfileAccess().masterDataFieldFingerprint || "",
    );
  }
  state.employeeProfileLoadingTabs.add(tabId);
  delete state.employeeProfileTabErrors[tabId];
  if (tabId !== "overview") state.employeeProfileTabData[tabId] = null;
  state.employeeProfileLoading = true;
  renderEmployeeProfile();
  try {
    const payload = await api(`/api/portal/v1/personnel-lifecycle/employees/${encodeURIComponent(normalizedEmployeeNumber)}/profile?tab=${definition.endpointTab}`);
    if (state.employeeProfileRequestToken !== profileRequestToken
      || state.employeeProfileTabRequestTokens[tabId] !== requestToken
      || state.employeeProfileEmployeeNumber !== normalizedEmployeeNumber
      || !employeeProfileIsOpen()) return;
    const normalized = tabId === "overview"
      ? normalizeEmployeeProfileOverview(payload, normalizedEmployeeNumber)
      : tabId === "masterData"
        ? normalizeEmployeeProfileMasterData(payload, normalizedEmployeeNumber)
        : tabId === "documents"
          ? normalizeEmployeeProfileDocuments(payload, normalizedEmployeeNumber)
          : tabId === "onboarding"
            ? normalizeEmployeeProfileOnboarding(payload, normalizedEmployeeNumber)
            : normalizeEmployeeProfileOffboarding(payload, normalizedEmployeeNumber);
    state.employeeProfile = tabId === "overview" ? normalized : normalized.profile;
    if (tabId === "masterData") {
      state.employeeProfileTabData.masterData = { fields: normalized.fields };
      state.employeeProfileTabAccessFingerprints.masterData = employeeProfileMasterDataFieldFingerprint(
        normalized.fields.map(({ key }) => key),
      );
    }
    if (tabId === "documents") state.employeeProfileTabData.documents = normalized.documents;
    if (tabId === "onboarding") {
      clearEmployeeOnboardingStartState();
      state.employeeProfileTabData.onboarding = {
        ...normalized.onboardingPreview,
        onboardingExecution: normalized.onboardingExecution,
        canStartOnboarding: normalized.capabilities.canStartOnboarding,
        canCloseOnboarding: normalized.capabilities.canCloseOnboarding,
      };
    }
    if (tabId === "offboarding") {
      clearEmployeeOffboardingState();
      state.employeeProfileTabData.offboarding = {
        ...normalized.offboarding,
        capabilities: normalized.capabilities,
      };
    }
    applyEmployeeProfileAccessProjection(normalized);
    state.employeeProfileLoadError = "";
  } catch (error) {
    if (state.employeeProfileRequestToken !== profileRequestToken
      || state.employeeProfileTabRequestTokens[tabId] !== requestToken
      || !employeeProfileIsOpen()) return;
    if ([401, 403, 404].includes(error.status)) {
      invalidateEmployeeProfileData("Der Profilzugriff ist nicht mehr verfügbar.");
      return;
    }
    if (tabId === "overview") state.employeeProfile = null;
    else state.employeeProfileTabData[tabId] = null;
    if (tabId === "onboarding") clearEmployeeOnboardingStartState();
    if (tabId === "offboarding") clearEmployeeOffboardingState();
    state.employeeProfileTabErrors[tabId] = `${definition.label} konnte nicht geladen werden.`;
  } finally {
    if (state.employeeProfileRequestToken === profileRequestToken
      && state.employeeProfileTabRequestTokens[tabId] === requestToken
      && employeeProfileIsOpen()) {
      delete state.employeeProfileTabRequestTokens[tabId];
      state.employeeProfileLoadingTabs.delete(tabId);
      state.employeeProfileLoading = state.employeeProfileLoadingTabs.size > 0;
      renderEmployeeProfile();
      if (tabId === "overview") ensureEmployeeProfileActiveTabLoaded();
    }
  }
}

function loadEmployeeProfileOverview(employeeNumber) {
  return loadEmployeeProfileTab("overview", employeeNumber);
}

function openEmployeeProfile(employeeNumber, trigger = null) {
  const normalizedEmployeeNumber = String(employeeNumber || "").trim();
  const teamTrigger = trigger?.dataset?.teamEmployeeProfileAccess === "true";
  const teamAccess = teamTrigger && canOpenTeamEmployeeProfileFoundation(normalizedEmployeeNumber);
  if (!normalizedEmployeeNumber || (teamTrigger ? !teamAccess : !canOpenEmployeeProfileFoundation())) return;
  const initialTab = canOpenStandardEmployeeProfileFoundation()
    ? "overview"
    : canReadEmployeeOnboardingPreview()
      ? "onboarding"
      : (canReadEmployeeOffboardingConfidential() ? "offboarding" : "");
  if (!initialTab) return;
  state.employeeProfileRequestToken = Symbol(`employee-profile-${normalizedEmployeeNumber}`);
  state.employeeProfileOpen = true;
  state.employeeProfileEmployeeNumber = normalizedEmployeeNumber;
  state.employeeProfileTab = initialTab;
  state.employeeProfileHost = teamAccess ? "team" : "administration";
  resetEmployeeProfileData({ accessPending: true, initialTab });
  state.employeeProfileLoadError = "";
  state.employeeProfileReturnFocus = trigger || document.activeElement;
  syncEmployeeProfileWorkspace();
  renderEmployeeProfile();
  elements.employeeProfileName?.focus({ preventScroll: true });
  loadEmployeeProfileTab(initialTab, normalizedEmployeeNumber);
}

function closeEmployeeProfile({ restoreFocus = true } = {}) {
  const returnFocus = state.employeeProfileReturnFocus;
  state.employeeProfileRequestToken = Symbol("employee-profile-closed");
  state.employeeProfileOpen = false;
  state.employeeProfileEmployeeNumber = "";
  state.employeeProfileTab = "overview";
  resetEmployeeProfileData();
  state.employeeProfileLoadError = "";
  state.employeeProfileReturnFocus = null;
  renderEmployeeProfile();
  syncEmployeeProfileWorkspace();
  state.employeeProfileHost = "administration";
  if (restoreFocus && returnFocus && typeof returnFocus.focus === "function") returnFocus.focus();
}

function renderCostCenterTypes() {
  if (!elements.costCenterTypeList) return;
  const canEdit = canWriteCostCenters();
  const types = state.costCenterTypes.slice().sort((left, right) =>
    Number(right.active) - Number(left.active)
      || Number(left.sortOrder) - Number(right.sortOrder)
      || left.name.localeCompare(right.name, "de-AT", { sensitivity: "base" }));
  elements.costCenterTypeList.innerHTML = types.length ? types.map((type) => {
    const positions = type.positions.length
      ? type.positions
      : type.positionIds.map((id) => state.positions.find((position) => String(position.id) === String(id)))
        .filter(Boolean);
    const visiblePositions = positions.slice(0, 6);
    const remainingPositions = Math.max(0, positions.length - visiblePositions.length);
    return `<article class="cost-center-type-card ${type.active ? "" : "inactive"}">
      <span class="eyebrow">${type.isBranch ? "Filialtyp" : "Kostenstellentyp"}</span>
      <h4>${escapeHtml(type.name || type.code || "Kostenstellentyp")}</h4>
      <p><code>${escapeHtml(type.code || "–")}</code>${type.description ? ` · ${escapeHtml(type.description)}` : ""}</p>
      <div class="cost-center-type-card-meta">
        <span>${type.active ? "Aktiv" : "Archiviert"}</span>
        <span>${type.builtin ? "Standardtyp" : "Eigener Typ"}</span>
        <span>${Number(type.costCenterCount)} Kostenstelle(n)</span>
        ${type.isBranch ? `<span>${Number(type.locationCount)} Standort(e)</span>` : ""}
      </div>
      <div class="cost-center-type-card-positions">${
        visiblePositions.length
          ? visiblePositions.map((position) => `<span>${escapeHtml(position.name || position.id)}</span>`).join("")
          : "<span>Keine Positionen zugeordnet</span>"
      }${remainingPositions ? `<span>+ ${remainingPositions} weitere</span>` : ""}</div>
      ${canEdit ? `<button type="button" class="edit-button" data-edit-cost-center-type="${escapeHtmlAttribute(type.id)}">Bearbeiten</button>` : ""}
    </article>`;
  }).join("") : '<p class="settings-note">Noch keine Kostenstellentypen angelegt.</p>';
}

function renderCostCenters() {
  if (!elements.costCenterList) return;
  const canEdit = canWriteCostCenters();
  const centers = state.costCenters.slice().sort((left, right) => left.code.localeCompare(right.code, "de-AT", { numeric: true, sensitivity: "base" }));
  elements.costCenterList.innerHTML = centers.length ? centers.map((center) => `
    <article class="cost-center-card ${center.active ? "" : "inactive"}">
      <div class="cost-center-card-code"><strong>${escapeHtml(center.code || "–")}</strong><span class="status-badge ${center.active ? "" : "inactive"}">${center.active ? "Aktiv" : "Inaktiv"}</span></div>
      <div class="cost-center-card-copy"><span class="eyebrow">${escapeHtml(costCenterTypeLabel(center))}</span><h3>${escapeHtml(center.name || center.code || "Kostenstelle")}</h3>${center.description ? `<p>${escapeHtml(center.description)}</p>` : ""}</div>
      <div class="cost-center-card-counts"><span><strong>${Number(center.employee_count)}</strong> Beschäftigte</span><span><strong>${Number(center.location_count)}</strong> Standorte</span></div>
      ${canEdit ? `<button type="button" class="edit-button" data-edit-cost-center="${escapeHtmlAttribute(String(center.id))}">Bearbeiten</button>` : ""}
    </article>`).join("") : '<p class="settings-note">Noch keine Kostenstelle angelegt.</p>';
}

function normalizeCentralVacation(item = {}) {
  return {
    ...item,
    group_id: String(item.group_id ?? item.groupId ?? item.id ?? ""),
    employee_number: String(item.employee_number ?? item.employeeNumber ?? ""),
    full_name: String(item.full_name ?? item.fullName ?? ""),
    nickname: String(item.nickname ?? ""),
    date_from: String(item.date_from ?? item.dateFrom ?? ""),
    date_to: String(item.date_to ?? item.dateTo ?? ""),
    days: Number(item.days ?? item.vacation_days ?? item.vacationDays ?? NaN),
    cost_center_id: String(item.cost_center_id ?? item.costCenterId ?? ""),
    cost_center_code: String(item.cost_center_code ?? item.costCenterCode ?? ""),
    cost_center_name: String(item.cost_center_name ?? item.costCenterName ?? ""),
    home_location_id: String(item.home_location_id ?? item.homeLocationId ?? ""),
    home_location_name: String(item.home_location_name ?? item.homeLocationName ?? ""),
    preferred_department_name: String(item.preferred_department_name ?? item.preferredDepartmentName ?? ""),
    source: String(item.source ?? item.origin ?? "direct"),
  };
}

function centralVacationSourceLabel(source) {
  return ({ request: "Genehmigter Antrag", approved_request: "Genehmigter Antrag", direct: "Direkt erfasst", import: "Import" })[source]
    || "Erfasst";
}

async function loadCentralVacations({ force = false } = {}) {
  if (!canReadCentralVacations() || state.centralVacationLoading) return;
  const year = Number(state.centralVacationYear || new Date().getFullYear());
  if (!force && state.centralVacationLoadedYear === year) {
    renderCentralVacations();
    return;
  }
  state.centralVacationLoading = true;
  if (elements.centralVacationList) elements.centralVacationList.innerHTML = '<tr><td colspan="7">Unternehmensweite Urlaubsdaten werden geladen.</td></tr>';
  try {
    const payload = await api(`/api/personnel-vacations?year=${encodeURIComponent(year)}`);
    state.centralVacations = apiList(payload, ["vacations", "items", "entries"]).map(normalizeCentralVacation);
    state.centralVacationYear = Number(payload?.year || year);
    state.centralVacationLoadedYear = state.centralVacationYear;
    renderCentralVacations();
  } catch (error) {
    if (elements.centralVacationList) elements.centralVacationList.innerHTML = `<tr><td colspan="7">${escapeHtml(error.message)}</td></tr>`;
    showToast(error.message, true);
  } finally {
    state.centralVacationLoading = false;
  }
}

function filteredCentralVacations() {
  const search = state.centralVacationSearch.trim().toLocaleLowerCase("de-AT");
  const costCenterId = String(state.centralVacationCostCenterFilter || "");
  return state.centralVacations.filter((vacation) => {
    if (costCenterId && vacation.cost_center_id !== costCenterId) return false;
    if (!search) return true;
    return [vacation.employee_number, vacation.full_name, vacation.nickname, vacation.cost_center_code,
      vacation.cost_center_name, vacation.home_location_id, vacation.home_location_name, vacation.preferred_department_name]
      .some((value) => String(value || "").toLocaleLowerCase("de-AT").includes(search));
  }).sort((left, right) => left.date_from.localeCompare(right.date_from)
    || left.employee_number.localeCompare(right.employee_number, "de-AT", { numeric: true, sensitivity: "base" }));
}

function renderCentralVacationSummary() {
  if (!elements.centralVacationSummary) return;
  const today = toIsoDate(new Date());
  const active = state.centralVacations.filter((vacation) => vacation.date_from <= today && vacation.date_to >= today).length;
  const upcoming = state.centralVacations.filter((vacation) => vacation.date_from > today).length;
  const employees = new Set(state.centralVacations.map((vacation) => vacation.employee_number).filter(Boolean)).size;
  const costCenters = new Set(state.centralVacations.map((vacation) => vacation.cost_center_id).filter(Boolean)).size;
  elements.centralVacationSummary.innerHTML = [
    ["Urlaubseinträge", state.centralVacations.length, `im Jahr ${state.centralVacationYear}`],
    ["Beschäftigte", employees, "mit Urlaubseintrag"],
    ["Heute abwesend", active, "genehmigte Urlaube"],
    ["Kommend", upcoming, `${costCenters} Kostenstelle${costCenters === 1 ? "" : "n"}`],
  ].map(([label, value, note]) => `<article class="personnel-administration-stat"><span>${escapeHtml(label)}</span><strong>${Number(value)}</strong><small>${escapeHtml(note)}</small></article>`).join("");
}

function renderCentralVacations() {
  if (!elements.centralVacationList || !canReadCentralVacations()) return;
  if (elements.centralVacationYear) elements.centralVacationYear.value = state.centralVacationYear;
  const currentCostCenter = String(state.centralVacationCostCenterFilter || "");
  const centersById = new Map(state.costCenters.map((center) => [String(center.id), center]));
  for (const vacation of state.centralVacations) {
    if (vacation.cost_center_id && !centersById.has(vacation.cost_center_id)) {
      centersById.set(vacation.cost_center_id, {
        id: vacation.cost_center_id,
        code: vacation.cost_center_code,
        name: vacation.cost_center_name,
        active: true,
      });
    }
  }
  elements.centralVacationCostCenterFilter.innerHTML = `<option value="">Alle Kostenstellen</option>${[...centersById.values()]
    .sort((left, right) => String(left.code || left.name).localeCompare(String(right.code || right.name), "de-AT", { numeric: true }))
    .map((center) => `<option value="${escapeHtmlAttribute(String(center.id))}">${escapeHtml([center.code, center.name].filter(Boolean).join(" · ") || "Kostenstelle")}</option>`).join("")}`;
  if ([...elements.centralVacationCostCenterFilter.options].some((option) => option.value === currentCostCenter)) {
    elements.centralVacationCostCenterFilter.value = currentCostCenter;
  } else {
    state.centralVacationCostCenterFilter = "";
  }
  renderCentralVacationSummary();
  const rows = filteredCentralVacations();
  elements.centralVacationList.innerHTML = rows.length ? rows.map((vacation) => {
    const personName = vacation.full_name || vacation.nickname || "–";
    const costCenter = [vacation.cost_center_code, vacation.cost_center_name].filter(Boolean).join(" · ") || "Nicht zugeordnet";
    const location = [vacation.home_location_name || vacation.home_location_id, vacation.preferred_department_name].filter(Boolean).join(" · ") || "Kein zugeordneter Standort";
    const period = vacation.date_from === vacation.date_to
      ? formatDate(vacation.date_from)
      : `${formatDate(vacation.date_from)} – ${formatDate(vacation.date_to)}`;
    return `<tr>
      <td data-label="Zeitraum"><strong>${escapeHtml(period)}</strong></td>
      <td data-label="Personalnr.">${escapeHtml(vacation.employee_number || "–")}</td>
      <td data-label="Name"><strong>${escapeHtml(personName)}</strong>${vacation.nickname && vacation.nickname !== personName ? `<small>${escapeHtml(vacation.nickname)}</small>` : ""}</td>
      <td data-label="Kostenstelle"><span class="status-badge ${vacation.cost_center_id ? "" : "warning"}">${escapeHtml(costCenter)}</span></td>
      <td data-label="Filiale / Abteilung">${escapeHtml(location)}</td>
      <td data-label="Tage">${Number.isFinite(vacation.days) ? escapeHtml(formatDaysLong(vacation.days)) : "–"}</td>
      <td data-label="Quelle">${escapeHtml(centralVacationSourceLabel(vacation.source))}</td>
    </tr>`;
  }).join("") : '<tr><td colspan="7" class="personnel-directory-empty">Keine passenden Urlaubseinträge gefunden.</td></tr>';
}

function governanceEmployeeLabel(employeeNumber) {
  const normalized = String(employeeNumber || "");
  const employee = [...(state.personnelDirectory || []), ...(state.allEmployees || [])]
    .find((item) => String(item.personnel_number ?? item.employeeNumber ?? "") === normalized);
  const name = employee?.full_name || employee?.fullName || employee?.nickname || "";
  return [normalized, name].filter(Boolean).join(" · ") || "Nicht zugeordnet";
}

function vacationAccountStatusLabel(value) {
  return ({
    confirmed: "Bestätigter Stand",
    draft: "Entwurf",
    manual_review: "Manuell prüfen",
    active: "Aktiv",
    closed: "Abgeschlossen",
  })[String(value || "")] || String(value || "Prüfstatus offen");
}

function vacationExpiryStatus(value) {
  return ({
    protected: ["Geschützt", "active"],
    not_due: ["Noch nicht fällig", "active"],
    candidate: ["Mögliche Verfallsprüfung", "warning"],
    manual_review: ["Manuell prüfen", "warning"],
    evidence_incomplete: ["Nachweis prüfen", "warning"],
    expired: ["Als verfallen dokumentiert", "inactive"],
  })[String(value || "")] || ["Einzelfall prüfen", "warning"];
}

function renderVacationAccounts() {
  if (!elements.vacationAccountsList || !canReadVacationAccounts()) return;
  const payload = state.vacationAccounts || {};
  const accounts = apiList(payload, ["accounts", "items"]);
  const year = Number(payload.year || elements.vacationAccountsYear?.value || state.centralVacationYear);
  const total = accounts.reduce((sum, account) => sum + Number(account.totalDays || 0), 0);
  const consumed = accounts.reduce((sum, account) => sum + Number(account.consumedDays || 0), 0);
  const remaining = accounts.reduce((sum, account) => sum + Number(account.remainingDays || 0), 0);
  const reviewCount = accounts.filter((account) => ["candidate", "manual_review", "evidence_incomplete"]
    .includes(String(account.expiryStatus || ""))).length;
  elements.vacationAccountsSummary.innerHTML = [
    ["Konten", accounts.length, `im Jahr ${year}`],
    ["Anspruch", formatDaysLong(total), "dokumentierter Kontostand"],
    ["Verbraucht", formatDaysLong(consumed), "gebuchte Urlaubstage"],
    ["Verbleibend", formatDaysLong(remaining), `${reviewCount} Hinweis${reviewCount === 1 ? "" : "e"} zu prüfen`],
  ].map(([label, value, note]) => `<article><span>${escapeHtml(String(label))}</span><strong>${escapeHtml(String(value))}</strong><small>${escapeHtml(String(note))}</small></article>`).join("");
  elements.vacationAccountsList.innerHTML = accounts.length ? accounts.map((account) => {
    const [expiryLabel, expiryClass] = vacationExpiryStatus(account.expiryStatus);
    return `<article class="governance-record-card">
      <div class="governance-record-heading">
        <div><span class="eyebrow">Urlaubskonto ${escapeHtml(String(account.leaveYear || year))}</span><h3>${escapeHtml(governanceEmployeeLabel(account.employeeNumber))}</h3></div>
        <span class="status-badge ${escapeHtml(expiryClass)}">${escapeHtml(expiryLabel)}</span>
      </div>
      <div class="governance-record-metrics">
        <span><small>Anspruch</small><strong>${escapeHtml(formatDaysLong(Number(account.totalDays || 0)))}</strong></span>
        <span><small>Verbraucht</small><strong>${escapeHtml(formatDaysLong(Number(account.consumedDays || 0)))}</strong></span>
        <span><small>Rest</small><strong>${escapeHtml(formatDaysLong(Number(account.remainingDays || 0)))}</strong></span>
      </div>
      <p>${escapeHtml(vacationAccountStatusLabel(account.status))} · Revision ${escapeHtml(String(account.revision || 1))}${account.expiryCandidateOn ? ` · möglicher Prüfstichtag ${escapeHtml(formatDate(account.expiryCandidateOn))}` : ""}</p>
    </article>`;
  }).join("") : '<p class="settings-note">Für dieses Jahr sind noch keine Urlaubskonten vorhanden.</p>';
}

async function loadVacationAccounts({ force = false } = {}) {
  if (!canReadVacationAccounts() || state.vacationAccountsLoading) return;
  const year = Number(elements.vacationAccountsYear?.value || state.centralVacationYear || new Date().getFullYear());
  if (!Number.isInteger(year) || year < 2000 || year > 2100) {
    showToast("Bitte ein gültiges Jahr für die Urlaubskonten auswählen.", true);
    return;
  }
  if (!force && Number(state.vacationAccounts?.year) === year) {
    renderVacationAccounts();
    return;
  }
  state.vacationAccountsLoading = true;
  if (elements.vacationAccountsList) elements.vacationAccountsList.innerHTML = '<p class="settings-note">Urlaubskonten werden geladen.</p>';
  try {
    state.vacationAccounts = await api(`/api/vacation-accounts?year=${encodeURIComponent(year)}`);
    renderVacationAccounts();
  } catch (error) {
    if (elements.vacationAccountsList) elements.vacationAccountsList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  } finally {
    state.vacationAccountsLoading = false;
  }
}

function openVacationAccounts() {
  if (!canReadVacationAccounts() || !elements.vacationAccountsModal) return;
  elements.vacationAccountsYear.value = Number(state.centralVacationYear || state.vacationYear || new Date().getFullYear());
  elements.vacationAccountsModal.showModal();
  loadVacationAccounts({ force: true });
}

function timeStatementStatusLabel(value) {
  return ({
    draft: "Entwurf",
    reviewed: "Geprüft",
    needs_correction: "Korrektur erforderlich",
    finalized: "Abgeschlossen",
    superseded: "Ersetzt",
  })[String(value || "")] || String(value || "Prüfstatus offen");
}

function renderMonthlyTimeRecords(errors = []) {
  if (!elements.monthlyTimeRecordsList || !canReadMonthlyTimeRecords()) return;
  const payload = state.monthlyTimeRecords || {};
  const latestByEmployee = new Map();
  for (const statement of apiList(payload, ["statements", "items"])) {
    const employeeNumber = String(statement.employeeNumber || "");
    const existing = latestByEmployee.get(employeeNumber);
    if (!existing || Number(statement.revision || 0) > Number(existing.revision || 0)) {
      latestByEmployee.set(employeeNumber, statement);
    }
  }
  const statements = [...latestByEmployee.values()].sort((left, right) =>
    String(left.employeeNumber || "").localeCompare(String(right.employeeNumber || ""), "de-AT", { numeric: true }));
  const month = String(payload.month || elements.monthlyTimeRecordsMonth?.value || "");
  const completed = statements.filter((statement) => statement.status === "finalized").length;
  const incomplete = statements.filter((statement) => statement.completeness !== "complete").length;
  const actualMinutes = statements.reduce((sum, statement) => sum + Number(statement.actualMinutes || 0), 0);
  elements.monthlyTimeRecordsSummary.innerHTML = [
    ["Nachweise", statements.length, month || "ausgewählter Monat"],
    ["Abgeschlossen", completed, "serverseitig belegter Status"],
    ["Prüfbedarf", incomplete, "unvollständige Ist-Buchungen"],
    ["Erfasste Ist-Zeit", formatHours(actualMinutes), "keine Planzeit"],
  ].map(([label, value, note]) => `<article><span>${escapeHtml(String(label))}</span><strong>${escapeHtml(String(value))}</strong><small>${escapeHtml(String(note))}</small></article>`).join("");
  const errorMarkup = Array.isArray(errors) && errors.length
    ? `<section class="governance-generation-errors"><strong>${errors.length} Nachweis${errors.length === 1 ? "" : "e"} nicht erzeugt</strong><ul>${errors.map((item) => `<li>${escapeHtml(governanceEmployeeLabel(item.employeeNumber))}: ${escapeHtml(item.message || item.error || "Prüfung fehlgeschlagen")}</li>`).join("")}</ul></section>`
    : "";
  const recordsMarkup = statements.length ? statements.map((statement) => {
    const complete = statement.completeness === "complete";
    const status = timeStatementStatusLabel(statement.status);
    const actions = [];
    if (canGenerateMonthlyTimeRecords() && statement.status === "draft") {
      if (complete) {
        actions.push(`<button type="button" class="secondary-button" data-time-record-action="review" data-time-record-id="${escapeHtmlAttribute(statement.id)}" data-time-record-decision="approved">Ist-Zeiten prüfen</button>`);
      }
      actions.push(`<button type="button" class="secondary-button" data-time-record-action="review" data-time-record-id="${escapeHtmlAttribute(statement.id)}" data-time-record-decision="needs_correction">Korrektur erforderlich</button>`);
    }
    if (canGenerateMonthlyTimeRecords() && statement.status === "reviewed") {
      actions.push(`<button type="button" class="primary-button" data-time-record-action="finalize" data-time-record-id="${escapeHtmlAttribute(statement.id)}">Nachweis abschließen</button>`);
    }
    if (statement.status === "finalized") {
      actions.push(`<a class="secondary-button" href="/api/time-record-statements/${encodeURIComponent(String(statement.id))}/download">PDF herunterladen</a>`);
    }
    return `<article class="governance-record-card">
      <div class="governance-record-heading">
        <div><span class="eyebrow">Monatsnachweis ${escapeHtml(statement.month || month)}</span><h3>${escapeHtml(governanceEmployeeLabel(statement.employeeNumber))}</h3></div>
        <span class="status-badge ${statement.status === "finalized" ? "active" : complete ? "" : "warning"}">${escapeHtml(status)}</span>
      </div>
      <div class="governance-record-metrics">
        <span><small>Erfasste Ist-Zeit</small><strong>${escapeHtml(formatHours(Number(statement.actualMinutes || 0)))}</strong></span>
        <span><small>Pausen</small><strong>${escapeHtml(formatHours(Number(statement.breakMinutes || 0)))}</strong></span>
        <span><small>Prüfhinweise</small><strong>${Number(statement.issueCount || 0)}</strong></span>
      </div>
      <p>${complete ? "Ist-Buchungen vollständig" : "Ist-Buchungen unvollständig oder zu prüfen"} · Revision ${escapeHtml(String(statement.revision || 1))}${statement.finalizedAt ? ` · abgeschlossen ${escapeHtml(diagnosticTimestamp(statement.finalizedAt))}` : ` · erstellt ${escapeHtml(diagnosticTimestamp(statement.createdAt))}`}</p>
      ${actions.length ? `<div class="governance-card-actions"><span>Jeder Bearbeitungsschritt erzeugt eine neue, unveränderliche Revision.</span><div class="governance-record-actions">${actions.join("")}</div></div>` : ""}
    </article>`;
  }).join("") : '<p class="settings-note">Für diesen Monat sind noch keine Monatsnachweise vorhanden.</p>';
  elements.monthlyTimeRecordsList.innerHTML = `${errorMarkup}${recordsMarkup}`;
}

async function loadMonthlyTimeRecords({ force = false } = {}) {
  if (!canReadMonthlyTimeRecords() || state.monthlyTimeRecordsLoading) return;
  const month = String(elements.monthlyTimeRecordsMonth?.value || toIsoDate(new Date()).slice(0, 7));
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
    showToast("Bitte einen gültigen Monat auswählen.", true);
    return;
  }
  if (!force && state.monthlyTimeRecords?.month === month) {
    renderMonthlyTimeRecords();
    return;
  }
  state.monthlyTimeRecordsLoading = true;
  if (elements.monthlyTimeRecordsList) elements.monthlyTimeRecordsList.innerHTML = '<p class="settings-note">Monatsnachweise werden geladen.</p>';
  try {
    state.monthlyTimeRecords = await api(`/api/time-record-statements?month=${encodeURIComponent(month)}`);
    renderMonthlyTimeRecords();
  } catch (error) {
    if (elements.monthlyTimeRecordsList) elements.monthlyTimeRecordsList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  } finally {
    state.monthlyTimeRecordsLoading = false;
  }
}

async function generateMonthlyTimeRecords() {
  if (!canGenerateMonthlyTimeRecords() || state.monthlyTimeRecordsLoading) return;
  const month = String(elements.monthlyTimeRecordsMonth?.value || "");
  if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) {
    showToast("Bitte einen gültigen Monat auswählen.", true);
    return;
  }
  state.monthlyTimeRecordsLoading = true;
  elements.generateMonthlyTimeRecordsButton.disabled = true;
  try {
    const result = await api("/api/time-record-statements/generate", {
      method: "POST",
      body: JSON.stringify({ month }),
    });
    state.monthlyTimeRecords = { month, statements: apiList(result, ["statements", "items"]) };
    renderMonthlyTimeRecords(result?.errors || []);
    showToast(result?.errors?.length
      ? "Nachweise wurden erzeugt; einzelne Fälle benötigen eine Prüfung."
      : "Monatsnachweise wurden aus den Ist-Buchungen erzeugt.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    state.monthlyTimeRecordsLoading = false;
    elements.generateMonthlyTimeRecordsButton.disabled = false;
  }
}

function openMonthlyTimeRecordAction(statementId, action, decision = "") {
  if (!canGenerateMonthlyTimeRecords() || state.monthlyTimeRecordsLoading || !statementId
    || !elements.monthlyTimeRecordActionModal) return;
  const statement = apiList(state.monthlyTimeRecords || {}, ["statements", "items"])
    .find((item) => String(item.id) === String(statementId));
  if (!statement) return;
  const normalizedAction = action === "finalize" ? "finalize" : "review";
  const normalizedDecision = decision === "needs_correction" ? "needs_correction" : "approved";
  elements.monthlyTimeRecordActionForm.reset();
  elements.monthlyTimeRecordActionId.value = String(statementId);
  elements.monthlyTimeRecordActionType.value = normalizedAction;
  elements.monthlyTimeRecordActionDecision.value = normalizedDecision;
  elements.monthlyTimeRecordActionTitle.textContent = normalizedAction === "finalize"
    ? "Monatsnachweis abschließen"
    : normalizedDecision === "approved"
      ? "Ist-Zeiten prüfen"
      : "Korrekturbedarf dokumentieren";
  elements.monthlyTimeRecordActionSummary.textContent = `${governanceEmployeeLabel(statement.employeeNumber)} · ${statement.month} · Revision ${statement.revision || 1}`;
  elements.monthlyTimeRecordActionNoteField.classList.toggle("hidden", normalizedAction === "finalize");
  elements.monthlyTimeRecordActionNote.value = normalizedDecision === "approved"
    ? "Ist-Zeitbuchungen und Pausen wurden geprüft."
    : "Die Ist-Zeitbuchungen benötigen eine nachvollziehbare Korrektur.";
  elements.monthlyTimeRecordActionMessage.classList.add("hidden");
  elements.monthlyTimeRecordActionMessage.textContent = "";
  elements.saveMonthlyTimeRecordActionButton.textContent = normalizedAction === "finalize"
    ? "Revisionssicher abschließen"
    : "Prüfung dokumentieren";
  elements.monthlyTimeRecordActionModal.showModal();
}

async function saveMonthlyTimeRecordAction(event) {
  event.preventDefault();
  if (!canGenerateMonthlyTimeRecords() || state.monthlyTimeRecordsLoading) return;
  const statementId = elements.monthlyTimeRecordActionId.value;
  const action = elements.monthlyTimeRecordActionType.value;
  const decision = elements.monthlyTimeRecordActionDecision.value;
  const body = { action };
  if (action === "review") {
    body.decision = decision === "needs_correction" ? "needs_correction" : "approved";
    const defaultNote = body.decision === "approved"
      ? "Ist-Zeitbuchungen und Pausen wurden geprüft."
      : "Die Ist-Zeitbuchungen benötigen eine nachvollziehbare Korrektur.";
    body.note = elements.monthlyTimeRecordActionNote.value.trim() || defaultNote;
  }
  state.monthlyTimeRecordsLoading = true;
  elements.saveMonthlyTimeRecordActionButton.disabled = true;
  try {
    await api(`/api/time-record-statements/${encodeURIComponent(String(statementId))}`, {
      method: "PATCH",
      body: JSON.stringify(body),
    });
    state.monthlyTimeRecords = null;
    elements.monthlyTimeRecordActionModal.close();
    showToast(action === "finalize"
      ? "Der Monatsnachweis wurde revisionssicher abgeschlossen."
      : body.decision === "approved"
        ? "Die Prüfung der Ist-Zeiten wurde dokumentiert."
        : "Der Korrekturbedarf wurde dokumentiert.");
  } catch (error) {
    elements.monthlyTimeRecordActionMessage.textContent = error.message;
    elements.monthlyTimeRecordActionMessage.classList.remove("hidden");
  } finally {
    state.monthlyTimeRecordsLoading = false;
    elements.saveMonthlyTimeRecordActionButton.disabled = false;
    await loadMonthlyTimeRecords({ force: true });
  }
}

function openMonthlyTimeRecords() {
  if (!canReadMonthlyTimeRecords() || !elements.monthlyTimeRecordsModal) return;
  elements.monthlyTimeRecordsMonth.value = toIsoDate(new Date()).slice(0, 7);
  elements.monthlyTimeRecordsModal.showModal();
  loadMonthlyTimeRecords({ force: true });
}

function dataSubjectRequestStatusLabel(value) {
  return ({
    received: "Eingelangt",
    identity_pending: "Identität offen",
    in_review: "In Prüfung",
    extended: "Frist verlängert",
    approved: "Genehmigt",
    partially_approved: "Teilweise genehmigt",
    rejected: "Abgelehnt",
    fulfilled: "Erfüllt",
    partially_fulfilled: "Teilweise erfüllt",
    withdrawn: "Zurückgezogen",
  })[String(value || "")] || String(value || "Status offen");
}

function dataSubjectRequestTypeLabel(value) {
  const match = (state.dataSubjectRequestTypes || []).find((item) => item.id === value);
  return match?.label || ({
    access: "Auskunft",
    rectification: "Berichtigung",
    erasure: "Löschung",
    restriction: "Einschränkung",
    portability: "Datenübertragbarkeit",
    objection: "Widerspruch",
  })[String(value || "")] || String(value || "Datenanfrage");
}

function dataSubjectRequestIsActionable(request) {
  return !["rejected", "fulfilled", "partially_fulfilled", "withdrawn"].includes(String(request?.status || ""));
}

function dataSubjectRequestDeadlineState(request) {
  const due = new Date(request?.dueAt || request?.deadline?.extendedTargetAt || request?.deadline?.initialTargetAt || "");
  if (!Number.isFinite(due.getTime()) || !dataSubjectRequestIsActionable(request)) return { className: "", label: "" };
  const days = Math.ceil((due.getTime() - Date.now()) / 86_400_000);
  if (days < 0) return { className: "critical", label: `${Math.abs(days)} Tag${Math.abs(days) === 1 ? "" : "e"} überfällig` };
  if (days <= 7) return { className: "warning", label: `${days} Tag${days === 1 ? "" : "e"} verbleibend` };
  return { className: "active", label: `${days} Tage verbleibend` };
}

function availableDataSubjectRequestActions(request) {
  if (Array.isArray(request?.availableActions)) return request.availableActions.map(String);
  return ({
    received: ["verify_identity", "withdraw"],
    identity_pending: ["verify_identity", "withdraw"],
    in_review: ["extend", "approve", "reject", "withdraw"],
    extended: ["approve", "reject", "withdraw"],
    approved: ["complete", "withdraw"],
    partially_approved: ["complete", "withdraw"],
  })[String(request?.status || "")] || [];
}

function dataSubjectRequestActionLabel(action) {
  return ({
    verify_identity: "Identität prüfen",
    extend: "Frist verlängern",
    approve: "Genehmigen",
    reject: "Ablehnen",
    complete: "Als erfüllt abschließen",
    withdraw: "Zurückziehen",
  })[String(action || "")] || String(action || "");
}

function updateDataSubjectRequestCounts() {
  const actionable = (state.dataSubjectRequests || []).filter(dataSubjectRequestIsActionable).length;
  for (const counter of [elements.dataSubjectRequestsNavCount, elements.dataSubjectRequestsTabCount]) {
    if (!counter) continue;
    counter.textContent = String(actionable);
    counter.classList.toggle("hidden", actionable === 0);
  }
}

function filteredDataSubjectRequests() {
  const search = String(state.dataSubjectRequestSearch || "").trim().toLocaleLowerCase("de-AT");
  const status = String(state.dataSubjectRequestStatusFilter || "");
  const type = String(state.dataSubjectRequestTypeFilter || "");
  return (state.dataSubjectRequests || []).filter((request) => {
    if (status === "actionable" && !dataSubjectRequestIsActionable(request)) return false;
    if (status && status !== "actionable" && request.status !== status) return false;
    if (type && request.type !== type) return false;
    if (!search) return true;
    return [request.id, request.employeeNumber, request.typeLabel, request.type, governanceEmployeeLabel(request.employeeNumber)]
      .some((value) => String(value || "").toLocaleLowerCase("de-AT").includes(search));
  }).sort((left, right) => String(right.receivedAt || "").localeCompare(String(left.receivedAt || "")));
}

function renderDataSubjectRequests() {
  if (!elements.dataSubjectRequestList || !canReadDataSubjectRequests()) return;
  updateDataSubjectRequestCounts();
  const total = state.dataSubjectRequests.length;
  const actionable = state.dataSubjectRequests.filter(dataSubjectRequestIsActionable).length;
  const overdue = state.dataSubjectRequests.filter((request) => dataSubjectRequestDeadlineState(request).className === "critical").length;
  const identityPending = state.dataSubjectRequests.filter((request) => request.identityStatus === "pending"
    || request.status === "identity_pending").length;
  elements.dataSubjectRequestSummary.innerHTML = [
    ["Anfragen", total, "dokumentierte Vorgänge"],
    ["Zu bearbeiten", actionable, "nicht abgeschlossene Anfragen"],
    ["Frist überschritten", overdue, "sofortige Einzelfallprüfung"],
    ["Identität offen", identityPending, "vor einer Herausgabe prüfen"],
  ].map(([label, value, note]) => `<article class="personnel-administration-stat"><span>${escapeHtml(String(label))}</span><strong>${Number(value)}</strong><small>${escapeHtml(String(note))}</small></article>`).join("");
  const currentType = elements.dataSubjectRequestTypeFilter?.value || state.dataSubjectRequestTypeFilter;
  if (elements.dataSubjectRequestTypeFilter) {
    elements.dataSubjectRequestTypeFilter.innerHTML = `<option value="">Alle Arten</option>${state.dataSubjectRequestTypes
      .map((item) => `<option value="${escapeHtmlAttribute(item.id)}">${escapeHtml(item.label)}</option>`).join("")}`;
    elements.dataSubjectRequestTypeFilter.value = state.dataSubjectRequestTypes.some((item) => item.id === currentType) ? currentType : "";
  }
  const requests = filteredDataSubjectRequests();
  elements.dataSubjectRequestList.innerHTML = requests.length ? requests.map((request) => {
    const deadline = dataSubjectRequestDeadlineState(request);
    const scope = Array.isArray(request.scope) && request.scope.length
      ? request.scope.join(", ")
      : "Umfang wird im Vorgang geprüft";
    return `<article class="data-subject-request-card">
      <div class="data-subject-request-card-heading">
        <div><span class="eyebrow">${escapeHtml(dataSubjectRequestTypeLabel(request.type))}</span><h3>${escapeHtml(governanceEmployeeLabel(request.employeeNumber))}</h3><small>${escapeHtml(request.id || "Anfrage ohne Kennung")}</small></div>
        <span class="status-badge ${dataSubjectRequestIsActionable(request) ? (deadline.className || "warning") : "inactive"}">${escapeHtml(dataSubjectRequestStatusLabel(request.status))}</span>
      </div>
      <dl class="data-subject-request-facts">
        <div><dt>Eingang</dt><dd>${escapeHtml(diagnosticTimestamp(request.receivedAt))}</dd></div>
        <div><dt>Frist</dt><dd>${escapeHtml(diagnosticTimestamp(request.dueAt))}${deadline.label ? `<small class="${escapeHtml(deadline.className)}">${escapeHtml(deadline.label)}</small>` : ""}</dd></div>
        <div><dt>Identität</dt><dd>${escapeHtml(request.identityStatus === "verified" ? "Bestätigt" : request.identityStatus === "insufficient" ? "Weitere Prüfung" : "Offen")}</dd></div>
        <div><dt>Umfang</dt><dd>${escapeHtml(scope)}</dd></div>
      </dl>
      <div class="governance-card-actions"><span>${request.updatedAt ? `Zuletzt geändert ${escapeHtml(diagnosticTimestamp(request.updatedAt))}` : ""}</span><button type="button" class="secondary-button" data-open-data-subject-request="${escapeHtmlAttribute(request.id)}">${canManageDataSubjectRequests() ? "Anfrage bearbeiten" : "Anfrage ansehen"}</button></div>
    </article>`;
  }).join("") : '<p class="settings-note">Keine Datenanfragen entsprechen den gewählten Filtern.</p>';
}

async function loadDataSubjectRequests({ force = false } = {}) {
  if (!canReadDataSubjectRequests() || state.dataSubjectRequestsLoading) return;
  if (!force && state.dataSubjectRequests.length) {
    renderDataSubjectRequests();
    return;
  }
  state.dataSubjectRequestsLoading = true;
  if (elements.addDataSubjectRequestButton) elements.addDataSubjectRequestButton.disabled = true;
  if (elements.dataSubjectRequestList) elements.dataSubjectRequestList.innerHTML = '<p class="settings-note">Datenanfragen werden geladen.</p>';
  try {
    const payload = await api("/api/privacy-governance/requests");
    state.dataSubjectRequestTypes = apiList(payload, ["requestTypes", "types"]).map((item) => ({
      id: String(item.id || item.value || ""),
      label: String(item.label || item.id || ""),
    })).filter((item) => item.id);
    state.dataSubjectRequests = apiList(payload, ["requests", "items"]).map((request) => ({ ...request }));
    renderDataSubjectRequests();
  } catch (error) {
    if (elements.dataSubjectRequestList) elements.dataSubjectRequestList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  } finally {
    state.dataSubjectRequestsLoading = false;
    if (elements.addDataSubjectRequestButton) elements.addDataSubjectRequestButton.disabled = !canManageDataSubjectRequests();
  }
}

function renderDataSubjectRequestDialog(request = null) {
  const editing = Boolean(request?.id);
  const canManage = canManageDataSubjectRequests();
  elements.dataSubjectRequestId.value = request?.id || "";
  elements.dataSubjectRequestModalTitle.textContent = editing ? "Datenanfrage prüfen" : "Datenanfrage erfassen";
  elements.dataSubjectRequestCreateFields.classList.toggle("hidden", editing);
  elements.dataSubjectRequestDetail.classList.toggle("hidden", !editing);
  elements.saveDataSubjectRequestButton.classList.toggle("hidden", !canManage || (editing && !availableDataSubjectRequestActions(request).length));
  elements.downloadDataSubjectRequestExportButton?.classList.toggle("hidden", !editing || !dataSubjectRequestCanBeExported(request));
  if (elements.downloadDataSubjectRequestExportButton) elements.downloadDataSubjectRequestExportButton.disabled = false;
  if (!editing) {
    elements.dataSubjectRequestForm.reset();
    elements.dataSubjectRequestType.innerHTML = state.dataSubjectRequestTypes
      .map((item) => `<option value="${escapeHtmlAttribute(item.id)}">${escapeHtml(item.label)}</option>`).join("");
    elements.saveDataSubjectRequestButton.textContent = "Anfrage erfassen";
    return;
  }
  const deadline = dataSubjectRequestDeadlineState(request);
  elements.dataSubjectRequestDetailSummary.innerHTML = [
    ["Person", governanceEmployeeLabel(request.employeeNumber)],
    ["Art", dataSubjectRequestTypeLabel(request.type)],
    ["Status", dataSubjectRequestStatusLabel(request.status)],
    ["Frist", `${diagnosticTimestamp(request.dueAt)}${deadline.label ? ` · ${deadline.label}` : ""}`],
  ].map(([label, value]) => `<article><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></article>`).join("");
  const events = Array.isArray(request.events) ? request.events : [];
  elements.dataSubjectRequestEventHistory.innerHTML = events.length
    ? `<h3>Bearbeitungsverlauf</h3>${events.map((event) => `<article><span>${escapeHtml(diagnosticTimestamp(event.at))}</span><strong>${escapeHtml(String(event.type || "Dokumentierter Schritt").replaceAll("_", " "))}</strong><small>${escapeHtml(event.actor || "")}</small></article>`).join("")}`
    : '<p class="settings-note">In dieser Übersicht werden Status, Frist und letzter Änderungszeitpunkt gezeigt. Weitere Nachweise verbleiben geschützt im Vorgang.</p>';
  const actions = canManage ? availableDataSubjectRequestActions(request) : [];
  elements.dataSubjectRequestAction.innerHTML = actions.map((action) => `<option value="${escapeHtmlAttribute(action)}">${escapeHtml(dataSubjectRequestActionLabel(action))}</option>`).join("");
  elements.dataSubjectRequestAction.disabled = actions.length === 0;
  elements.dataSubjectRequestActionNote.value = "";
  elements.saveDataSubjectRequestButton.textContent = "Schritt dokumentieren";
  updateDataSubjectRequestActionFields();
}

async function openDataSubjectRequest(request = null) {
  if ((!request && !canManageDataSubjectRequests()) || !canReadDataSubjectRequests() || !elements.dataSubjectRequestModal) return;
  state.selectedDataSubjectRequest = request;
  elements.dataSubjectRequestMessage.classList.add("hidden");
  elements.dataSubjectRequestMessage.textContent = "";
  renderDataSubjectRequestDialog(request);
  elements.dataSubjectRequestModal.showModal();
  if (!request?.id) return;
  try {
    const detail = await api(`/api/privacy-governance/requests/${encodeURIComponent(request.id)}`);
    const complete = {
      ...request,
      ...(detail?.summary || {}),
      ...(detail?.request || {}),
      employeeNumber: detail?.summary?.employeeNumber || detail?.request?.subjectId || request.employeeNumber,
      typeLabel: detail?.summary?.typeLabel || request.typeLabel,
      identityStatus: detail?.summary?.identityStatus || detail?.request?.identity?.status || request.identityStatus,
      dueAt: detail?.summary?.dueAt || detail?.request?.deadline?.extendedTargetAt
        || detail?.request?.deadline?.initialTargetAt || request.dueAt,
    };
    state.selectedDataSubjectRequest = complete;
    if (elements.dataSubjectRequestModal.open) renderDataSubjectRequestDialog(complete);
  } catch (error) {
    elements.dataSubjectRequestMessage.textContent = error.message;
    elements.dataSubjectRequestMessage.classList.remove("hidden");
  }
}

async function downloadDataSubjectRequestExport() {
  const request = state.selectedDataSubjectRequest;
  if (!dataSubjectRequestCanBeExported(request) || !request?.id) return;
  elements.downloadDataSubjectRequestExportButton.disabled = true;
  elements.dataSubjectRequestMessage.classList.add("hidden");
  try {
    const response = await rawApi(
      `/api/privacy-governance/requests/${encodeURIComponent(request.id)}/export`,
    );
    const subject = String(request.subjectId || request.employeeNumber || "Person")
      .replace(/[^a-z0-9_-]/gi, "-");
    await downloadFileResponse(response, `Datenauskunft-${subject}.json`);
    showToast("Das genehmigte Datenauskunftspaket wurde heruntergeladen.");
  } catch (error) {
    elements.dataSubjectRequestMessage.textContent = error.message;
    elements.dataSubjectRequestMessage.classList.remove("hidden");
  } finally {
    elements.downloadDataSubjectRequestExportButton.disabled = false;
  }
}

function updateDataSubjectRequestActionFields() {
  const action = elements.dataSubjectRequestAction?.value || "";
  elements.dataSubjectRequestIdentityField?.classList.toggle("hidden", action !== "verify_identity");
  elements.dataSubjectRequestExtensionField?.classList.toggle("hidden", action !== "extend");
  const noteRequired = ["reject", "extend", "complete"].includes(action);
  if (elements.dataSubjectRequestActionNote) elements.dataSubjectRequestActionNote.required = noteRequired;
}

async function saveDataSubjectRequest(event) {
  event.preventDefault();
  if (!canManageDataSubjectRequests()) return;
  const id = elements.dataSubjectRequestId.value;
  elements.saveDataSubjectRequestButton.disabled = true;
  elements.dataSubjectRequestMessage.classList.add("hidden");
  try {
    if (!id) {
      const scope = elements.dataSubjectRequestScope.value.split(/[\n,;]+/)
        .map((item) => item.trim()).filter(Boolean);
      const body = {
        employeeNumber: elements.dataSubjectRequestEmployeeNumber.value.trim(),
        type: elements.dataSubjectRequestType.value,
      };
      if (scope.length) body.scope = scope;
      await api("/api/privacy-governance/requests", {
        method: "POST",
        body: JSON.stringify(body),
      });
      showToast("Datenanfrage wurde nachvollziehbar erfasst.");
    } else {
      const action = elements.dataSubjectRequestAction.value;
      const note = elements.dataSubjectRequestActionNote.value.trim();
      const body = { action };
      if (action === "verify_identity") {
        body.status = elements.dataSubjectRequestIdentityStatus.value;
        body.reasonCode = body.status === "verified" ? "manual_identity_check" : "additional_evidence_needed";
      } else if (action === "extend") {
        body.months = Number(elements.dataSubjectRequestExtensionMonths.value);
        body.reasonCode = "documented_complexity";
        body.reason = note;
      } else if (action === "approve") {
        body.summary = note || "Der beantragte Umfang wurde durch eine berechtigte Person geprüft.";
      } else if (action === "reject") {
        body.reasonCode = "documented_exception";
        body.reason = note;
        body.summary = note;
      } else if (action === "complete") {
        body.reference = note;
      } else if (action === "withdraw") {
        body.reasonCode = "documented_withdrawal";
      }
      await api(`/api/privacy-governance/requests/${encodeURIComponent(id)}`, {
        method: "PATCH",
        body: JSON.stringify(body),
      });
      showToast("Bearbeitungsschritt wurde dokumentiert.");
    }
    elements.dataSubjectRequestModal.close();
    state.selectedDataSubjectRequest = null;
    state.dataSubjectRequests = [];
    await loadDataSubjectRequests({ force: true });
  } catch (error) {
    elements.dataSubjectRequestMessage.textContent = error.message;
    elements.dataSubjectRequestMessage.classList.remove("hidden");
  } finally {
    elements.saveDataSubjectRequestButton.disabled = false;
  }
}

function retentionStatusLabel(value) {
  return ({ active: "Aktiv", draft: "Entwurf", retired: "Außer Kraft" })[String(value || "")]
    || String(value || "Status offen");
}

function retentionTriggerLabel(value) {
  return ({
    record_created: "Erstellung des Datensatzes",
    record_closed: "Abschluss des Datensatzes",
    case_resolved: "Abschluss des Falls",
    employment_ended: "Ende des Arbeitsverhältnisses",
    contract_ended: "Vertragsende",
    purpose_ended: "Ende des Verwendungszwecks",
    custom_event: "Dokumentiertes Einzelereignis",
  })[String(value || "")] || String(value || "Auslöser zu prüfen");
}

function retentionDispositionLabel(value) {
  return ({
    manual_review: "Manuelle Prüfung",
    delete: "Löschung nach gesonderter Freigabe",
    anonymize: "Anonymisierung nach gesonderter Freigabe",
    archive: "Archivierung nach gesonderter Freigabe",
  })[String(value || "")] || String(value || "Folgemaßnahme offen");
}

function retentionDurationLabel(retention = {}) {
  const value = Number(retention.value || 0);
  const unit = ({ days: value === 1 ? "Tag" : "Tage", months: value === 1 ? "Monat" : "Monate", years: value === 1 ? "Jahr" : "Jahre" })[retention.unit]
    || retention.unit || "Einheit";
  return `${new Intl.NumberFormat("de-AT").format(value)} ${unit}`;
}

function retentionGovernanceRules() {
  return apiList(state.retentionGovernance || {}, ["rules", "items"]);
}

function openRetentionRuleDialog(template = null) {
  if (!canManageRetentionGovernance() || !elements.retentionRuleModal) return;
  const rules = retentionGovernanceRules();
  const category = String(template?.category || "custom_records");
  let version = Math.max(0, ...rules.filter((rule) => rule.category === category)
    .map((rule) => Number(rule.version) || 0)) + 1;
  const idBase = String(template?.id || `retention-${category}`).replace(/-v\d+$/i, "");
  let id = `${idBase}-v${version}`;
  while (rules.some((rule) => rule.id === id)) {
    version += 1;
    id = `${idBase}-v${version}`;
  }
  const source = template?.sources?.[0] || {
    id: "eu-gdpr",
    authority: "Europäische Union",
    title: "Verordnung (EU) 2016/679 (Datenschutz-Grundverordnung)",
    url: "https://eur-lex.europa.eu/eli/reg/2016/679/oj",
    jurisdiction: "EU",
    reference: "insbesondere Art. 5, 6, 17 und 30",
  };
  elements.retentionRuleForm.reset();
  elements.retentionRuleModalTitle.textContent = template
    ? `Neue Version · ${template.title || template.category}`
    : "Regelversion anlegen";
  elements.retentionRuleId.value = id;
  elements.retentionRuleVersion.value = String(version);
  elements.retentionRuleCategory.value = category;
  elements.retentionRuleStatus.value = "draft";
  elements.retentionRuleTitle.value = template?.title || "Neue Aufbewahrungsregel";
  elements.retentionRuleValidFrom.value = toIsoDate(new Date());
  elements.retentionRuleValidTo.value = "";
  elements.retentionRuleStartTrigger.value = template?.startTrigger || "record_closed";
  elements.retentionRuleDisposition.value = template?.disposition || "manual_review";
  elements.retentionRuleDurationValue.value = String(template?.retention?.value || 1);
  elements.retentionRuleDurationUnit.value = template?.retention?.unit || "years";
  elements.retentionRuleSourceId.value = source.id || "";
  elements.retentionRuleSourceJurisdiction.value = source.jurisdiction || "";
  elements.retentionRuleSourceAuthority.value = source.authority || "";
  elements.retentionRuleSourceReference.value = source.reference || "";
  elements.retentionRuleSourceTitle.value = source.title || "";
  elements.retentionRuleSourceUrl.value = source.url || "";
  elements.retentionRuleMessage.textContent = "";
  elements.retentionRuleMessage.classList.add("hidden");
  elements.saveRetentionRuleButton.disabled = false;
  elements.retentionRuleModal.showModal();
}

async function saveRetentionRule(event) {
  event.preventDefault();
  if (!canManageRetentionGovernance()) return;
  elements.saveRetentionRuleButton.disabled = true;
  elements.retentionRuleMessage.classList.add("hidden");
  try {
    const body = {
      schemaVersion: 1,
      id: elements.retentionRuleId.value.trim(),
      version: String(Number(elements.retentionRuleVersion.value)),
      category: elements.retentionRuleCategory.value.trim(),
      title: elements.retentionRuleTitle.value.trim(),
      status: elements.retentionRuleStatus.value,
      validFrom: elements.retentionRuleValidFrom.value,
      validTo: elements.retentionRuleValidTo.value || null,
      sources: [{
        id: elements.retentionRuleSourceId.value.trim(),
        authority: elements.retentionRuleSourceAuthority.value.trim(),
        title: elements.retentionRuleSourceTitle.value.trim(),
        url: elements.retentionRuleSourceUrl.value.trim(),
        jurisdiction: elements.retentionRuleSourceJurisdiction.value.trim(),
        reference: elements.retentionRuleSourceReference.value.trim(),
      }],
      startTrigger: elements.retentionRuleStartTrigger.value,
      retention: {
        value: Number(elements.retentionRuleDurationValue.value),
        unit: elements.retentionRuleDurationUnit.value,
      },
      disposition: elements.retentionRuleDisposition.value,
      legalHold: { behavior: "exclude_while_active" },
    };
    await api("/api/privacy-governance/retention/rules", {
      method: "POST",
      body: JSON.stringify(body),
    });
    elements.retentionRuleModal.close();
    state.retentionGovernance = null;
    await loadRetentionGovernance({ force: true });
    showToast("Die neue unveränderliche Regelversion wurde angelegt.");
  } catch (error) {
    elements.retentionRuleMessage.textContent = error.message;
    elements.retentionRuleMessage.classList.remove("hidden");
  } finally {
    elements.saveRetentionRuleButton.disabled = false;
  }
}

function openRetentionHoldDialog(category = "") {
  if (!canManageRetentionGovernance() || !elements.retentionHoldModal) return;
  elements.retentionHoldForm.reset();
  elements.retentionHoldCategory.value = String(category || "");
  elements.retentionHoldValidFrom.value = toIsoDate(new Date());
  elements.retentionHoldMessage.textContent = "";
  elements.retentionHoldMessage.classList.add("hidden");
  elements.saveRetentionHoldButton.disabled = false;
  elements.retentionHoldModal.showModal();
}

async function saveRetentionHold(event) {
  event.preventDefault();
  if (!canManageRetentionGovernance()) return;
  elements.saveRetentionHoldButton.disabled = true;
  elements.retentionHoldMessage.classList.add("hidden");
  try {
    const body = {
      category: elements.retentionHoldCategory.value.trim(),
      employeeNumber: elements.retentionHoldEmployeeNumber.value.trim(),
      reasonCode: elements.retentionHoldReasonCode.value.trim(),
      validFrom: elements.retentionHoldValidFrom.value,
    };
    if (elements.retentionHoldValidTo.value) body.validTo = elements.retentionHoldValidTo.value;
    await api("/api/privacy-governance/retention/holds", {
      method: "POST",
      body: JSON.stringify(body),
    });
    elements.retentionHoldModal.close();
    state.retentionGovernance = null;
    await loadRetentionGovernance({ force: true });
    showToast("Die Schutzsperre wurde angelegt.");
  } catch (error) {
    elements.retentionHoldMessage.textContent = error.message;
    elements.retentionHoldMessage.classList.remove("hidden");
  } finally {
    elements.saveRetentionHoldButton.disabled = false;
  }
}

async function releaseRetentionHold(id) {
  if (!canManageRetentionGovernance() || !id) return;
  if (!window.confirm("Diese aktive Schutzsperre wirklich freigeben? Es werden dadurch keine Daten gelöscht.")) return;
  try {
    await api(`/api/privacy-governance/retention/holds/${encodeURIComponent(id)}/release`, {
      method: "POST",
      body: JSON.stringify({}),
    });
    state.retentionGovernance = null;
    await loadRetentionGovernance({ force: true });
    showToast("Die Schutzsperre wurde freigegeben.");
  } catch (error) {
    showToast(error.message, true);
  }
}

function renderRetentionPreview(preview) {
  if (!elements.retentionPreviewResult) return;
  if (!preview) {
    elements.retentionPreviewResult.innerHTML = '<p class="settings-note">Noch keine Vorschau berechnet.</p>';
    return;
  }
  const actual = preview.preview || preview;
  const counts = actual.counts || preview.summary || {};
  const assessments = apiList(actual, ["assessments", "items"]);
  const candidates = apiList(actual, ["candidates"]);
  elements.retentionPreviewResult.innerHTML = `
    <div class="governance-summary">
      ${[
        ["Datensätze", Number(counts.records || assessments.length || 0)],
        ["Vorschaukandidaten", Number(counts.candidates || candidates.length || 0)],
        ["Schutzsperren", Number(counts.legalHold || 0)],
        ["Manuell prüfen", Number(counts.manualReview || 0)],
      ].map(([label, value]) => `<article><span>${escapeHtml(label)}</span><strong>${value}</strong></article>`).join("")}
    </div>
    <p class="settings-note">Prüfstand ${escapeHtml(formatDate(actual.asOf || preview.asOf))}${preview.createdAt ? ` · erstellt ${escapeHtml(diagnosticTimestamp(preview.createdAt))}` : ""}. Vorschau-only: Es wurde nichts gelöscht oder verändert.</p>
    ${assessments.length ? `<div class="privacy-preview-assessments">${assessments.slice(0, 50).map((assessment) => {
      const stateLabel = ({
        candidate: "Möglicher Kandidat",
        legal_hold: "Durch Schutzsperre ausgenommen",
        manual_review: "Manuell prüfen",
        not_due: "Frist läuft",
      })[assessment.state] || assessment.state;
      const className = assessment.state === "candidate" ? "warning"
        : assessment.state === "legal_hold" ? "active"
          : assessment.state === "manual_review" ? "critical" : "";
      return `<article><div><strong>${escapeHtml(assessment.recordId || "Datensatz")}</strong><small>${escapeHtml(assessment.category || "")}${assessment.dueAt ? ` · rechnerischer Stichtag ${escapeHtml(formatDate(assessment.dueAt))}` : ""}</small></div><span class="status-badge ${escapeHtml(className)}">${escapeHtml(stateLabel)}</span></article>`;
    }).join("")}</div>${assessments.length > 50 ? `<p class="settings-note">Weitere ${assessments.length - 50} Einträge sind im unveränderten serverseitigen Prüfnachweis enthalten.</p>` : ""}` : ""}`;
}

function renderRetentionGovernance() {
  if (!canReadRetentionGovernance() || !elements.retentionPolicyList) return;
  const payload = state.retentionGovernance || {};
  const rules = apiList(payload, ["rules", "items"]);
  const holds = apiList(payload, ["holds", "legalHolds"]);
  const activeRules = rules.filter((rule) => rule.status === "active").length;
  const activeHolds = holds.filter((hold) => hold.status === "active" || hold.active === true).length;
  elements.retentionPolicyNotice.textContent = payload.notice
    || "Die Regeln unterstützen eine dokumentierte Prüfung; konkrete Fristen und Rechtsgrundlagen sind im Einzelfall zu bestätigen.";
  elements.retentionPolicySummary.innerHTML = [
    ["Regelversionen", rules.length, `${activeRules} aktiv`],
    ["Aktive Schutzsperren", activeHolds, "von einer Vorschau auszunehmen"],
    ["Letzte Vorschau", payload.latestPreview ? formatDate(payload.latestPreview.asOf) : "Noch keine", payload.latestPreview ? diagnosticTimestamp(payload.latestPreview.createdAt) : "keine Ausführung"],
  ].map(([label, value, note]) => `<article><span>${escapeHtml(String(label))}</span><strong>${escapeHtml(String(value))}</strong><small>${escapeHtml(String(note))}</small></article>`).join("");
  const canManage = canManageRetentionGovernance();
  const ruleMarkup = rules.length ? rules.map((rule) => `<article class="privacy-retention-rule">
    <div class="privacy-retention-rule-heading"><div><span class="eyebrow">${escapeHtml(rule.category || "Datenkategorie")}</span><h3>${escapeHtml(rule.title || rule.id || "Aufbewahrungsregel")}</h3></div><span class="status-badge ${rule.status === "active" ? "active" : rule.status === "draft" ? "warning" : "inactive"}">${escapeHtml(retentionStatusLabel(rule.status))}</span></div>
    <dl>
      <div><dt>Version</dt><dd>${escapeHtml(String(rule.version || "–"))}</dd></div>
      <div><dt>Gültigkeit</dt><dd>${escapeHtml(formatDate(rule.validFrom))}${rule.validTo ? ` – ${escapeHtml(formatDate(rule.validTo))}` : " – offen"}</dd></div>
      <div><dt>Fristbeginn</dt><dd>${escapeHtml(retentionTriggerLabel(rule.startTrigger))}</dd></div>
      <div><dt>Dauer</dt><dd>${escapeHtml(retentionDurationLabel(rule.retention))}</dd></div>
      <div class="wide"><dt>Vorgesehene Folge</dt><dd>${escapeHtml(retentionDispositionLabel(rule.disposition))}</dd></div>
    </dl>
    ${canManage ? `<div class="governance-card-actions"><span>Bestehende Version unveränderlich</span><button type="button" class="secondary-button" data-new-retention-rule-version="${escapeHtmlAttribute(rule.id)}">Neue Version</button></div>` : ""}
  </article>`).join("") : '<p class="settings-note">Noch keine versionierten Aufbewahrungsregeln vorhanden.</p>';
  const holdsMarkup = holds.length ? `<details class="privacy-holds"><summary>Schutzsperren (${holds.length})</summary><div>${holds.map((hold) => {
    const active = hold.status === "active" || hold.active === true;
    const scope = hold.subjectId ? ` · Personalnummer ${hold.subjectId}` : "";
    const validity = ` · ${formatDate(hold.validFrom)}${hold.validTo ? ` bis ${formatDate(hold.validTo)}` : " bis auf Widerruf"}`;
    return `<article><div><strong>${escapeHtml(hold.category || "Kategorieübergreifend")}</strong><small>${escapeHtml(hold.reasonCode || hold.reason || "Dokumentierter Schutzgrund")}${escapeHtml(scope)}${escapeHtml(validity)}</small></div><div class="governance-record-actions"><span class="status-badge ${active ? "active" : "inactive"}">${active ? "Aktiv" : "Freigegeben"}</span>${canManage && active ? `<button type="button" class="secondary-button" data-release-retention-hold="${escapeHtmlAttribute(hold.id)}">Freigeben</button>` : ""}</div></article>`;
  }).join("")}</div></details>` : "";
  elements.retentionPolicyList.innerHTML = `${ruleMarkup}${holdsMarkup}`;
  renderRetentionPreview(payload.latestPreview);
}

async function loadRetentionGovernance({ force = false } = {}) {
  if (!canReadRetentionGovernance()) return;
  if (!force && state.retentionGovernance) {
    renderRetentionGovernance();
    return;
  }
  if (elements.retentionPolicyList) elements.retentionPolicyList.innerHTML = '<p class="settings-note">Aufbewahrungsregeln werden geladen.</p>';
  try {
    state.retentionGovernance = await api("/api/privacy-governance/retention");
    renderRetentionGovernance();
  } catch (error) {
    if (elements.retentionPolicyList) elements.retentionPolicyList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  }
}

async function runRetentionPreview(event) {
  event.preventDefault();
  if (!canManageRetentionGovernance() || state.retentionPreviewLoading) return;
  state.retentionPreviewLoading = true;
  elements.runRetentionPreviewButton.disabled = true;
  elements.retentionPreviewResult.innerHTML = '<p class="settings-note">Die reine Vorschau wird berechnet. Es wird nichts gelöscht.</p>';
  try {
    const asOf = elements.retentionPreviewAsOf.value;
    const body = asOf ? { asOf } : {};
    const result = await api("/api/privacy-governance/retention/preview", {
      method: "POST",
      body: JSON.stringify(body),
    });
    const preview = result?.preview || result;
    state.retentionGovernance = {
      ...(state.retentionGovernance || {}),
      latestPreview: {
        ...(preview || {}),
        preview: preview?.preview || preview,
        summary: preview?.summary || preview?.counts,
      },
    };
    renderRetentionGovernance();
    renderRetentionPreview(state.retentionGovernance.latestPreview);
    showToast("Die reine Löschvorschau wurde erstellt; es wurden keine Daten verändert.");
  } catch (error) {
    elements.retentionPreviewResult.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    showToast(error.message, true);
  } finally {
    state.retentionPreviewLoading = false;
    elements.runRetentionPreviewButton.disabled = false;
  }
}

function customWorkRuleCatalogEntry(catalogName, id) {
  return (state.customWorkRuleRegistry?.catalogs?.[catalogName] || [])
    .find((entry) => entry.id === id) || null;
}

function customWorkRuleCatalogLabel(catalogName, id, fallback = "") {
  return customWorkRuleCatalogEntry(catalogName, id)?.label || fallback || id || "–";
}

function customWorkRuleConditionLabel(definition = {}) {
  const metric = customWorkRuleCatalogEntry("metrics", definition.metric);
  const unit = metric?.valueType === "time" ? "Uhr" : (metric?.unitLabel || definition.unit || "");
  return [
    metric?.label || definition.metric || "Regelbaustein",
    metric?.operatorLabel || definition.operator || "",
    definition.threshold ?? "–",
    unit,
  ].filter((entry) => entry !== "").join(" · ");
}

async function loadCustomWorkRuleRegistry({ force = false } = {}) {
  if (!canAccessCustomWorkRuleGovernance() || state.customWorkRulesLoading) return;
  if (state.customWorkRuleRegistry && state.workRuleGovernance && !force) {
    renderCustomWorkRuleRegistry();
    return;
  }
  state.customWorkRulesLoading = true;
  if (elements.customWorkRuleList) {
    elements.customWorkRuleList.innerHTML = '<p class="settings-note">Regelwerk und offene Aufgaben werden geladen.</p>';
  }
  try {
    const [registryResult, governanceResult] = await Promise.allSettled([
      api("/api/work-rules/drafts"),
      api("/api/work-rules/governance"),
    ]);
    if (registryResult.status === "rejected" && governanceResult.status === "rejected") {
      throw registryResult.reason;
    }
    state.customWorkRuleRegistry = registryResult.status === "fulfilled"
      ? registryResult.value
      : {
        generatedAt: governanceResult.value?.generatedAt,
        notice: "Entwürfe, Freigaben, Veröffentlichungen und Zuordnungen bleiben getrennte, nachvollziehbare Vorgänge.",
        capabilities: {},
        summary: {},
        catalogs: {},
        organizationalScopes: {},
        drafts: [],
      };
    state.workRuleGovernance = governanceResult.status === "fulfilled"
      ? governanceResult.value
      : {
        generatedAt: state.customWorkRuleRegistry.generatedAt,
        capabilities: state.customWorkRuleRegistry.capabilities || {},
        requests: [],
        publications: [],
        assignments: [],
        events: [],
      };
    const ids = new Set((state.customWorkRuleRegistry.drafts || []).map((draft) => draft.id));
    if (!ids.has(state.selectedCustomWorkRuleId)) {
      state.selectedCustomWorkRuleId = state.customWorkRuleRegistry.drafts?.[0]?.id || "";
    }
    renderCustomWorkRuleRegistry();
  } catch (error) {
    state.customWorkRuleRegistry = null;
    if (elements.customWorkRuleList) {
      elements.customWorkRuleList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    }
    showToast(error.message, true);
  } finally {
    state.customWorkRulesLoading = false;
  }
}

function workRuleGovernanceCapabilities() {
  const registry = state.customWorkRuleRegistry?.capabilities || {};
  const governance = state.workRuleGovernance?.capabilities || {};
  return {
    canDraft: governance.canDraft ?? registry.canDraft ?? canDraftCustomWorkRules(),
    canRevise: governance.canRevise ?? registry.canRevise ?? canDraftCustomWorkRules(),
    canSubmitForReview: governance.canSubmitForReview ?? registry.canSubmitForReview ?? canDraftCustomWorkRules(),
    canReview: governance.canReview ?? governance.canApprove ?? registry.canReview ?? registry.canApprove ?? canReviewCustomWorkRules(),
    canPublish: governance.canPublish ?? registry.canPublish ?? canPublishCustomWorkRules(),
    canAssign: governance.canAssign ?? governance.canActivate ?? registry.canAssign ?? registry.canActivate ?? canAssignCustomWorkRules(),
    canDeactivate: (governance.canAssign ?? registry.canAssign ?? canAssignCustomWorkRules())
      || (governance.canPublish ?? registry.canPublish ?? canPublishCustomWorkRules()),
    canDeactivateAssignment: governance.canAssign ?? registry.canAssign ?? canAssignCustomWorkRules(),
    canWithdrawPublication: governance.canPublish ?? registry.canPublish ?? canPublishCustomWorkRules(),
    canAudit: governance.canAudit ?? registry.canAudit ?? canAuditCustomWorkRules(),
  };
}

function workRuleProfileId(value = "") {
  const normalized = String(value || "");
  if (!normalized.startsWith("custom:")) return "";
  const separator = normalized.indexOf("@");
  return separator === -1 ? normalized : normalized.slice(0, separator);
}

function workRuleGovernanceEntries(key) {
  return Array.isArray(state.workRuleGovernance?.[key]) ? state.workRuleGovernance[key] : [];
}

function workRuleRequestDecisions(request = {}) {
  return Array.isArray(request.decisions) ? request.decisions : [];
}

function workRuleRequestState(request = {}) {
  const decisions = workRuleRequestDecisions(request);
  if (request.state) return request.state;
  if (decisions.some((entry) => entry.decision === "reject")) return "rejected";
  const approvals = decisions.filter((entry) => entry.decision === "approve").length;
  if (approvals >= Number(request.requiredApprovals || 2)) return "approved";
  return "in_review";
}

function workRuleRequestApprovalCount(request = {}) {
  const decisions = workRuleRequestDecisions(request);
  if (decisions.length) return decisions.filter((entry) => entry.decision === "approve").length;
  return Number(request.approvalCount || 0);
}

function workRuleConflict(value = {}) {
  const referencedRun = value?.conflictRunId
    ? workRuleGovernanceEntries("conflictRuns").find((entry) => entry.id === value.conflictRunId)
    : null;
  const source = value?.preview || value?.conflictRun || value?.conflict || referencedRun || value || {};
  const result = source.result || source.details || source;
  const outcome = String(source.outcome || result.outcome || "warning");
  const issues = [
    ...(Array.isArray(result.blockers) ? result.blockers : []),
    ...(Array.isArray(result.warnings) ? result.warnings : []),
    ...(Array.isArray(result.issues) ? result.issues : []),
    ...(Array.isArray(result.conflicts) ? result.conflicts : []),
  ];
  return {
    outcome: ["pass", "warning", "blocked"].includes(outcome) ? outcome : "warning",
    title: source.title || result.title || ({
      pass: "Keine blockierende Überschneidung erkannt",
      warning: "Fachliche Prüfung erforderlich",
      blocked: "Konflikt verhindert den Vorgang",
    })[outcome] || "Fachliche Prüfung erforderlich",
    note: source.note || result.note || result.message || "",
    issues,
    checkedAt: source.createdAt || source.checkedAt || "",
    receipt: source.receiptSha256 || source.resultSha256 || "",
  };
}

function workRuleConflictMarkup(value, { compact = false } = {}) {
  const conflict = workRuleConflict(value);
  const issueMarkup = !compact && conflict.issues.length
    ? `<ul>${conflict.issues.slice(0, 5).map((issue) => `<li>${escapeHtml(issue.message || issue.label || String(issue))}</li>`).join("")}</ul>`
    : "";
  return `<div class="custom-work-rule-conflict ${escapeHtmlAttribute(conflict.outcome)}">
    <span class="custom-work-rule-conflict-mark" aria-hidden="true">${conflict.outcome === "pass" ? "✓" : conflict.outcome === "blocked" ? "!" : "…"}</span>
    <div><strong>${escapeHtml(conflict.title)}</strong>${conflict.note ? `<p>${escapeHtml(conflict.note)}</p>` : ""}${issueMarkup}${conflict.checkedAt ? `<small>Geprüft ${escapeHtml(new Date(conflict.checkedAt).toLocaleString("de-AT"))}</small>` : ""}</div>
  </div>`;
}

function workRuleActorLabel() {
  const actor = state.workRuleGovernance?.currentActor || state.portalSession?.user || {};
  const number = actor.employeeNumber || actor.actorEmployeeNumber || "";
  const name = actor.fullName || actor.nickname || actor.name || "";
  const role = actor.roleName || actor.role || "";
  return [number && name ? `${number} · ${name}` : (name || number || "Aktuell angemeldeter Zugang"), role]
    .filter(Boolean)
    .join(" · ");
}

function workRulePublicationState(publication = {}) {
  if (publication.state) return publication.state;
  const events = Array.isArray(publication.events) ? publication.events : [];
  const lastEvent = events.at(-1);
  if (lastEvent?.eventType === "withdrawn") return "withdrawn";
  if (lastEvent?.eventType === "superseded") return "superseded";
  return "published";
}

function workRuleAssignmentState(assignment = {}) {
  if (assignment.active === true) return "active";
  if (assignment.state) return assignment.state;
  const events = Array.isArray(assignment.events) ? assignment.events : [];
  const lastEvent = events.at(-1);
  if (lastEvent?.eventType === "deactivated") return "ended";
  if (lastEvent?.eventType === "superseded") return "superseded";
  const today = toIsoDate(new Date());
  if (assignment.active === false && assignment.validFrom && assignment.validFrom <= today) return "ended";
  if (assignment.validTo && assignment.validTo < today) return "ended";
  if (assignment.validFrom && assignment.validFrom > today) return "planned";
  return events.some((entry) => entry.eventType === "activated") ? "active" : "planned";
}

function customWorkRuleContext(profileId) {
  const draft = (state.customWorkRuleRegistry?.drafts || []).find((entry) => entry.id === profileId) || null;
  const publications = workRuleGovernanceEntries("publications")
    .filter((entry) => workRuleProfileId(entry.profileId || entry.releasedProfileVersionId || entry.sourceProfileVersionId) === profileId);
  const publicationIds = new Set(publications.map((entry) => entry.id));
  const assignments = workRuleGovernanceEntries("assignments")
    .filter((entry) => publicationIds.has(entry.publicationId) || workRuleProfileId(entry.profileId || entry.profileVersionId) === profileId);
  const assignmentIds = new Set(assignments.flatMap((entry) => [
    entry.id,
    entry.governedRevisionId,
    entry.logicalAssignmentId,
  ]).filter(Boolean));
  const versionIds = new Set((draft?.versions || []).map((entry) => entry.id));
  const requests = workRuleGovernanceEntries("requests").filter((entry) => (
    workRuleProfileId(entry.profileId || entry.subjectId) === profileId
    || versionIds.has(entry.subjectId)
    || publicationIds.has(entry.subjectId)
    || assignmentIds.has(entry.subjectId)
  ));
  const requestIds = new Set(requests.map((entry) => entry.id));
  const relatedIds = new Set([profileId, ...versionIds, ...publicationIds, ...assignmentIds, ...requestIds]);
  const events = workRuleGovernanceEntries("events").filter((entry) => (
    relatedIds.has(entry.aggregateId)
    || relatedIds.has(entry.subjectId)
    || relatedIds.has(entry.requestId)
    || workRuleProfileId(entry.profileId || entry.aggregateId) === profileId
  ));
  return { draft, publications, assignments, requests, events };
}

function customWorkRuleStatus(context) {
  const blocked = context.requests.some((request) => (
    ["in_review", "approved"].includes(workRuleRequestState(request))
    && workRuleConflict(request).outcome === "blocked"
  ));
  if (blocked) return { key: "conflict", label: "Konflikt – Bearbeitung erforderlich", tone: "danger" };
  const pending = context.requests
    .filter((request) => ["in_review", "approved"].includes(workRuleRequestState(request)))
    .sort((left, right) => String(right.submittedAt || "").localeCompare(String(left.submittedAt || "")))[0];
  if (pending) {
    const approvals = workRuleRequestApprovalCount(pending);
    const required = Number(pending.requiredApprovals || 2);
    if (workRuleRequestState(pending) === "approved" || approvals >= required) {
      return { key: "approval", label: "Freigegeben – Abschluss offen", tone: "success" };
    }
    if (approvals > 0) return { key: "approval", label: "Zweitfreigabe offen", tone: "warning" };
    return { key: "review", label: "Fachprüfung offen", tone: "warning" };
  }
  const activeAssignment = context.assignments.find((entry) => workRuleAssignmentState(entry) === "active");
  if (activeAssignment) {
    return {
      key: "effective",
      label: activeAssignment.enforcementMode === "enforced"
        ? "Wirksam · verbindliche Prüfung"
        : "Wirksam · Monitorbetrieb",
      tone: "success",
    };
  }
  const plannedAssignment = context.assignments.find((entry) => workRuleAssignmentState(entry) === "planned");
  if (plannedAssignment) {
    return { key: "published", label: `Geplant ab ${formatDate(plannedAssignment.validFrom)}`, tone: "info" };
  }
  const publication = context.publications.find((entry) => workRulePublicationState(entry) === "published");
  if (publication) return { key: "published", label: "Veröffentlicht – noch nicht zugeordnet", tone: "info" };
  const ended = context.assignments.some((entry) => ["ended", "superseded"].includes(workRuleAssignmentState(entry)))
    || context.publications.some((entry) => ["withdrawn", "superseded"].includes(workRulePublicationState(entry)));
  if (ended && !context.draft?.hasUnreleasedDraft) return { key: "ended", label: "Beendet / zurückgezogen", tone: "inactive" };
  return { key: "draft", label: "Entwurf – keine Wirkung", tone: "warning" };
}

function customWorkRuleItems() {
  const profiles = new Map((state.customWorkRuleRegistry?.drafts || []).map((draft) => [draft.id, draft]));
  for (const publication of workRuleGovernanceEntries("publications")) {
    const profileId = workRuleProfileId(publication.profileId || publication.releasedProfileVersionId || publication.sourceProfileVersionId);
    if (profileId && !profiles.has(profileId)) {
      profiles.set(profileId, {
        id: profileId,
        code: profileId.slice("custom:".length),
        title: publication.title || publication.profileTitle || profileId,
        currentVersion: publication.definition ? { id: publication.releasedProfileVersionId, definition: publication.definition } : null,
        versions: [],
      });
    }
  }
  const statusOrder = ["conflict", "review", "approval", "draft", "published", "effective", "ended"];
  return [...profiles.values()].map((draft) => {
    const context = customWorkRuleContext(draft.id);
    return { draft, context, status: customWorkRuleStatus(context) };
  }).sort((left, right) => (
    statusOrder.indexOf(left.status.key) - statusOrder.indexOf(right.status.key)
    || String(left.draft.title || "").localeCompare(String(right.draft.title || ""), "de-AT")
  ));
}

function renderCustomWorkRuleSummary(items) {
  if (!elements.customWorkRuleSummary) return;
  const cards = [
    ["actionable", "Zu bearbeiten", items.filter((item) => ["conflict", "review", "approval"].includes(item.status.key)).length, "Prüfung oder Abschluss offen"],
    ["draft", "Entwürfe", items.filter((item) => item.status.key === "draft").length, "noch ohne Freigabe"],
    ["published", "Veröffentlicht", items.filter((item) => item.status.key === "published").length, "Zuordnung getrennt prüfen"],
    ["effective", "Wirksam", items.filter((item) => item.status.key === "effective").length, "datierte Zuordnungen"],
  ];
  elements.customWorkRuleSummary.innerHTML = cards.map(([filter, label, value, note]) => `
    <button type="button" class="personnel-administration-stat custom-work-rule-summary-card ${state.customWorkRuleStatusFilter === filter ? "selected" : ""}" data-custom-work-rule-filter="${escapeHtmlAttribute(filter)}" aria-pressed="${state.customWorkRuleStatusFilter === filter}">
      <span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong><small>${escapeHtml(note)}</small>
    </button>
  `).join("");
}

function customWorkRuleFilterMatch(item, filter) {
  if (filter === "all") return true;
  if (filter === "actionable") return ["conflict", "review", "approval"].includes(item.status.key);
  return item.status.key === filter;
}

function renderCustomWorkRuleTaskFilter(items) {
  if (!elements.customWorkRuleTaskFilter) return;
  const filters = [
    ["all", "Alle"],
    ["actionable", "Zu bearbeiten"],
    ["draft", "Entwürfe"],
    ["review", "Fachprüfung"],
    ["approval", "Zweitfreigabe"],
    ["published", "Veröffentlicht"],
    ["effective", "Wirksam"],
    ["conflict", "Konflikte"],
    ["ended", "Historisch"],
  ];
  elements.customWorkRuleTaskFilter.innerHTML = filters.map(([key, label]) => {
    const count = items.filter((item) => customWorkRuleFilterMatch(item, key)).length;
    return `<button type="button" class="${state.customWorkRuleStatusFilter === key ? "active" : ""}" data-custom-work-rule-filter="${escapeHtmlAttribute(key)}" aria-pressed="${state.customWorkRuleStatusFilter === key}">${escapeHtml(label)} <span>${count}</span></button>`;
  }).join("");
}

function renderCustomWorkRuleList(items) {
  if (!elements.customWorkRuleList) return;
  const filtered = items.filter((item) => customWorkRuleFilterMatch(item, state.customWorkRuleStatusFilter));
  if (elements.customWorkRuleListHint) {
    elements.customWorkRuleListHint.textContent = state.customWorkRuleStatusFilter === "all"
      ? `${items.length} eigene Regeln in allen Bearbeitungsständen`
      : `${filtered.length} von ${items.length} Regeln im gewählten Bearbeitungsstand`;
  }
  if (!filtered.length) {
    elements.customWorkRuleList.innerHTML = `
      <div class="custom-work-rule-empty compact">
        <strong>Keine eigene Regel in diesem Bearbeitungsstand</strong>
        <p>Wähle einen anderen Filter oder lege – mit passendem Recht – einen neuen Entwurf an.</p>
      </div>`;
    return;
  }
  elements.customWorkRuleList.innerHTML = filtered.map(({ draft, status }) => {
    const current = draft.currentVersion?.definition || {};
    const active = draft.id === state.selectedCustomWorkRuleId;
    return `<button class="custom-work-rule-list-item ${active ? "active" : ""}" type="button" data-custom-work-rule-id="${escapeHtmlAttribute(draft.id)}">
      <span class="custom-work-rule-code">${escapeHtml(draft.code)}</span>
      <strong>${escapeHtml(draft.title)}</strong>
      <small>${escapeHtml(customWorkRuleCatalogLabel("ruleTypes", current.ruleType, "Eigene Regel"))} · ${escapeHtml(draft.currentVersion?.versionLabel || "Entwurf")}</small>
      <span class="status-badge ${escapeHtmlAttribute(status.tone)}">${escapeHtml(status.label)}</span>
    </button>`;
  }).join("");
}

function renderCustomWorkRuleTestCases(testCases = []) {
  const labels = { pass: "Eingehalten", fail: "Verletzt", unknown: "Manuell prüfen" };
  return `<div class="custom-work-rule-tests">${testCases.map((testCase) => `
    <article class="${escapeHtmlAttribute(testCase.actual || "unknown")}">
      <span>${escapeHtml(testCase.label || testCase.id)}</span>
      <strong>${testCase.input === null ? "Kein Prüfwert" : escapeHtml(String(testCase.input))}</strong>
      <small>${escapeHtml(labels[testCase.actual] || testCase.actual || "Unbekannt")}</small>
    </article>
  `).join("")}</div>`;
}

function workRuleOperationLabel(operation) {
  return ({
    publish_rule: "Regelfassung veröffentlichen",
    activate_assignment: "Zuordnung aktivieren",
    deactivate_assignment: "Zuordnung beenden",
    withdraw_publication: "Veröffentlichung zurückziehen",
    approve_kv_assignment: "KV-Zuordnung freigeben",
    deactivate_kv_assignment: "KV-Zuordnung beenden",
  })[operation] || operation || "Governance-Vorgang";
}

function workRuleDecisionActor(decision = {}) {
  return [
    decision.actorEmployeeNumber || decision.employeeNumber || "Zugang",
    decision.actorName || decision.fullName || "",
    decision.qualification === "fachlich" ? "fachlich" : decision.qualification || "",
  ].filter(Boolean).join(" · ");
}

function renderCustomWorkRuleReviewWorkflow(context) {
  const publishRequest = context.requests
    .filter((entry) => entry.operation === "publish_rule")
    .sort((left, right) => String(right.submittedAt || "").localeCompare(String(left.submittedAt || "")))[0];
  const approvals = workRuleRequestApprovalCount(publishRequest);
  const requiredApprovals = Number(publishRequest?.requiredApprovals || 1);
  const rejected = workRuleRequestState(publishRequest) === "rejected";
  const published = context.publications.some((entry) => workRulePublicationState(entry) !== "withdrawn");
  const steps = [
    ["Entwurf", true],
    ["Fachprüfung", published || approvals >= 1, Boolean(publishRequest) && approvals === 0 && !rejected],
    ...(requiredApprovals > 1
      ? [["Zweitfreigabe", published || approvals >= requiredApprovals,
        Boolean(publishRequest) && approvals > 0 && approvals < requiredApprovals && !rejected]]
      : []),
    ["Veröffentlicht", published, workRuleRequestState(publishRequest) === "approved" && !published],
  ];
  return `<section class="custom-work-rule-workflow review">
    <div class="custom-work-rule-section-heading"><div><span class="eyebrow">Freigabeweg</span><h4>Fassung und Veröffentlichung</h4></div><small>Vier-Augen-Prinzip · unveränderliche Prüfbasis</small></div>
    <ol>${steps.map(([label, completed, current]) => `<li class="${rejected && current ? "failed" : completed ? "completed" : current ? "current" : "pending"}"><span>${completed ? "✓" : current ? "●" : ""}</span><strong>${escapeHtml(label)}</strong></li>`).join("")}</ol>
  </section>`;
}

function renderCustomWorkRuleAssignmentWorkflow(context) {
  const hasPublication = context.publications.some((entry) => workRulePublicationState(entry) === "published");
  const planned = context.assignments.some((entry) => workRuleAssignmentState(entry) === "planned");
  const effective = context.assignments.some((entry) => workRuleAssignmentState(entry) === "active");
  const ended = context.assignments.some((entry) => ["ended", "superseded"].includes(workRuleAssignmentState(entry)));
  const hasAssignmentRequest = context.requests.some((entry) => entry.operation === "activate_assignment");
  const steps = [
    ["Zuordnung", hasPublication && (hasAssignmentRequest || context.assignments.length), hasPublication && !hasAssignmentRequest && !context.assignments.length],
    ["Geplant", planned || effective || ended, hasAssignmentRequest && !context.assignments.length],
    ["Wirksam", effective || ended, planned],
    ["Beendet", ended, false],
  ];
  return `<section class="custom-work-rule-workflow effect">
    <div class="custom-work-rule-section-heading"><div><span class="eyebrow">Wirksamkeitsweg</span><h4>Zuordnung und Betriebsart</h4></div><small>Veröffentlichung allein hat keine Dienstplanwirkung</small></div>
    <ol>${steps.map(([label, completed, current]) => `<li class="${completed ? "completed" : current ? "current" : "pending"}"><span>${completed ? "✓" : current ? "●" : ""}</span><strong>${escapeHtml(label)}</strong></li>`).join("")}</ol>
  </section>`;
}

function renderCustomWorkRuleRequestCard(request, capabilities) {
  const stateLabel = ({
    in_review: "Prüfung offen",
    approved: "Freigegeben · Abschluss offen",
    rejected: "Abgelehnt",
    applied: "Abgeschlossen",
    finalized: "Abgeschlossen",
    superseded: "Abgelöst",
  })[workRuleRequestState(request)] || workRuleRequestState(request);
  const decisions = workRuleRequestDecisions(request);
  const required = Number(request.requiredApprovals || 2);
  const approvals = workRuleRequestApprovalCount(request);
  const canFinalize = workRuleRequestState(request) === "approved" && (
    (request.operation === "publish_rule" && capabilities.canPublish)
    || (request.operation === "activate_assignment" && capabilities.canAssign)
    || (request.operation === "deactivate_assignment" && capabilities.canDeactivateAssignment)
    || (request.operation === "withdraw_publication" && capabilities.canWithdrawPublication)
    || (["approve_kv_assignment", "deactivate_kv_assignment"].includes(request.operation)
      && capabilities.canApproveCollectiveAgreement)
  );
  const currentActorNumber = state.workRuleGovernance?.currentActor?.employeeNumber
    || state.portalSession?.user?.employeeNumber
    || "";
  const alreadyDecided = decisions.some((entry) => (
    (entry.actorEmployeeNumber || entry.employeeNumber) === currentActorNumber
  )) || request.currentActorDecisionRecorded === true;
  const canDecide = capabilities.canReview
    && workRuleRequestState(request) === "in_review"
    && request.submittedBy !== currentActorNumber
    && request.submittedByCurrentActor !== true
    && !alreadyDecided;
  return `<article class="custom-work-rule-request-card ${escapeHtmlAttribute(workRuleRequestState(request))}">
    <div class="custom-work-rule-record-heading">
      <div><span class="eyebrow">${escapeHtml(workRuleOperationLabel(request.operation))}</span><strong>${escapeHtml(stateLabel)}</strong><small>${approvals} von ${required} Freigaben · eingereicht ${escapeHtml(request.submittedAt ? new Date(request.submittedAt).toLocaleString("de-AT") : "–")}</small></div>
      <span class="status-badge ${workRuleRequestState(request) === "rejected" ? "danger" : workRuleRequestState(request) === "approved" ? "success" : "warning"}">${escapeHtml(stateLabel)}</span>
    </div>
    ${workRuleConflictMarkup(request, { compact: true })}
    <div class="custom-work-rule-decisions">${decisions.length ? decisions.map((decision) => `
      <div class="${escapeHtmlAttribute(decision.decision)}"><span>${decision.decision === "approve" ? "✓" : "!"}</span><div><strong>${decision.decision === "approve" ? "Freigegeben" : "Abgelehnt"} · ${escapeHtml(workRuleDecisionActor(decision))}</strong><small>${escapeHtml(decision.reason || "Keine Begründung übermittelt")} · ${escapeHtml(decision.decidedAt ? new Date(decision.decidedAt).toLocaleString("de-AT") : "")}</small></div></div>
    `).join("") : approvals || workRuleRequestState(request) === "rejected"
      ? '<p>Entscheidungen sind dokumentiert; personenbezogene Entscheidungsdetails sind nur mit Auditrecht sichtbar.</p>'
      : '<p>Noch keine Entscheidung dokumentiert.</p>'}</div>
    ${(canDecide || canFinalize) ? `<div class="custom-work-rule-record-actions">
      ${canDecide ? `<button class="secondary-button" type="button" data-work-rule-action="approve-request" data-request-id="${escapeHtmlAttribute(request.id)}">${approvals ? "Zweitfreigabe erteilen" : "Fachlich freigeben"}</button>
        <button class="danger-button" type="button" data-work-rule-action="reject-request" data-request-id="${escapeHtmlAttribute(request.id)}">Ablehnen</button>` : ""}
      ${canFinalize ? `<button class="primary-button" type="button" data-work-rule-action="finalize-request" data-request-id="${escapeHtmlAttribute(request.id)}">${request.operation === "publish_rule" ? "Veröffentlichen" : "Freigegebenen Vorgang abschließen"}</button>` : ""}
    </div>` : ""}
  </article>`;
}

function renderCustomWorkRuleAssignmentCard(assignment, capabilities) {
  const assignmentState = workRuleAssignmentState(assignment);
  const stateLabel = ({
    planned: `Geplant ab ${formatDate(assignment.validFrom)}`,
    active: assignment.enforcementMode === "enforced" ? "Wirksam · verbindliche Prüfung" : "Wirksam · Monitorbetrieb",
    ended: "Beendet",
    superseded: "Abgelöst",
  })[assignmentState] || assignmentState;
  const tone = assignmentState === "active" ? "success" : assignmentState === "planned" ? "info" : "inactive";
  return `<article class="custom-work-rule-assignment-card ${escapeHtmlAttribute(assignmentState)}">
    <div class="custom-work-rule-record-heading">
      <div><span class="eyebrow">${escapeHtml(assignment.scopeLabel || assignment.scopeType || "Geltungsbereich")}</span><strong>${escapeHtml(stateLabel)}</strong><small>${escapeHtml(formatDate(assignment.validFrom))}${assignment.validTo ? ` bis ${escapeHtml(formatDate(assignment.validTo))}` : " · ohne Enddatum"} · ${assignment.applicabilityConfirmed ? "Anwendbarkeit bestätigt" : "Anwendbarkeit nicht bestätigt"}</small></div>
      <span class="status-badge ${tone}">${escapeHtml(stateLabel)}</span>
    </div>
    ${capabilities.canDeactivateAssignment && ["active", "planned"].includes(assignmentState) ? `<div class="custom-work-rule-record-actions"><button class="danger-button" type="button" data-work-rule-action="deactivate-assignment" data-assignment-id="${escapeHtmlAttribute(assignment.governedRevisionId || assignment.id)}">Zuordnung kontrolliert beenden</button></div>` : ""}
  </article>`;
}

function workRuleAuditEventLabel(event = {}) {
  return ({
    request_submitted: "Prüfung eingereicht",
    decision_recorded: "Entscheidung dokumentiert",
    published: "Fassung veröffentlicht",
    withdrawn: "Veröffentlichung zurückgezogen",
    activated: "Zuordnung aktiviert",
    deactivated: "Zuordnung beendet",
    superseded: "Fassung abgelöst",
  })[event.eventType] || event.label || event.eventType || "Governance-Ereignis";
}

function renderCustomWorkRuleAudit(context, capabilities) {
  if (!capabilities.canAudit) return "";
  const events = [...context.events].sort((left, right) => String(right.occurredAt || "").localeCompare(String(left.occurredAt || "")));
  return `<details class="custom-work-rule-audit">
    <summary>Audit-Historie (${events.length})</summary>
    <div>${events.length ? events.map((event) => `<article><span></span><div><strong>${escapeHtml(workRuleAuditEventLabel(event))}</strong><small>${escapeHtml([event.actorEmployeeNumber, event.actorRole, event.occurredAt ? new Date(event.occurredAt).toLocaleString("de-AT") : ""].filter(Boolean).join(" · "))}</small>${event.receiptSha256 ? `<code>${escapeHtml(String(event.receiptSha256).slice(0, 16))}…</code>` : ""}</div></article>`).join("") : '<p>Noch keine Audit-Ereignisse für diese Regel.</p>'}</div>
  </details>`;
}

function renderCustomWorkRuleDetail(items) {
  if (!elements.customWorkRuleDetail) return;
  const item = items.find((entry) => entry.draft.id === state.selectedCustomWorkRuleId);
  const draft = item?.draft;
  if (!draft?.currentVersion) {
    elements.customWorkRuleDetail.innerHTML = `
      <div class="custom-work-rule-empty">
        <strong>Noch keine Regel ausgewählt</strong>
        <p>Wähle links eine Regel, um Freigabeweg, Konflikte, Zuordnungen und Historie zu lesen.</p>
      </div>`;
    return;
  }
  const context = item.context;
  const capabilities = workRuleGovernanceCapabilities();
  const version = draft.currentVersion;
  const definition = version.definition || {};
  const sourceUrl = safeWorkRuleSourceUrl(definition.sourceUrl);
  const openPublishRequest = context.requests.find((entry) => (
    entry.operation === "publish_rule"
    && entry.subjectId === version.id
    && ["in_review", "approved"].includes(workRuleRequestState(entry))
  ));
  const activePublication = context.publications.find((entry) => workRulePublicationState(entry) === "published");
  const history = (draft.versions || []).map((entry) => `
    <article class="${entry.id === draft.currentVersionId ? "current" : ""}">
      <div><strong>${escapeHtml(entry.versionLabel)}</strong><small>${entry.versionKind === "release" ? "Veröffentlichte, unveränderliche Fassung" : (entry.releasedAsVersionId ? `Veröffentlicht als ${escapeHtml(entry.releasedAsVersionId)}` : "Unveränderliche Arbeitsfassung")} · ${escapeHtml(formatDate(entry.validFrom))}${entry.validTo ? ` bis ${escapeHtml(formatDate(entry.validTo))}` : " · ohne Enddatum"}</small></div>
      <div><span>${escapeHtml(String(entry.contentSha256 || "").slice(0, 12))}…</span>${capabilities.canRevise && entry.versionKind === "release" ? `<button class="secondary-button" type="button" data-work-rule-action="restore-version" data-profile-id="${escapeHtmlAttribute(draft.id)}" data-version-id="${escapeHtmlAttribute(entry.id)}">Als neue Fassung wieder öffnen</button>` : ""}</div>
    </article>
  `).join("");
  const effectCopy = item.status.key === "effective"
    ? "Nur die unten dokumentierte, datierte Zuordnung wirkt im Dienstplan. Die veröffentlichte Fassung selbst bleibt unverändert."
    : "Diese Fassung hat ohne freigegebene, datierte Zuordnung keine Dienstplanwirkung.";
  elements.customWorkRuleDetail.innerHTML = `
    <div class="custom-work-rule-detail-heading">
      <div><span class="eyebrow">${escapeHtml(draft.code)} · ${escapeHtml(version.versionLabel)}</span><h3>${escapeHtml(definition.title || draft.title)}</h3><p>${escapeHtml(definition.description || "")}</p></div>
      <div class="custom-work-rule-detail-actions">
        <span class="status-badge ${escapeHtmlAttribute(item.status.tone)}">${escapeHtml(item.status.label)}</span>
        ${capabilities.canRevise ? `<button class="secondary-button" type="button" data-revise-custom-work-rule="${escapeHtmlAttribute(draft.id)}">Neue Entwurfsfassung</button>` : ""}
      </div>
    </div>
    ${renderCustomWorkRuleReviewWorkflow(context)}
    ${renderCustomWorkRuleAssignmentWorkflow(context)}
    <div class="custom-work-rule-effect-note"><strong>${item.status.key === "effective" ? "Kontrolliert wirksam" : "Noch keine Dienstplanwirkung"}</strong><span>${escapeHtml(effectCopy)}</span></div>
    <div class="custom-work-rule-primary-actions">
      ${capabilities.canSubmitForReview && draft.hasUnreleasedDraft !== false && !openPublishRequest ? `<button class="primary-button" type="button" data-work-rule-action="submit-review" data-profile-id="${escapeHtmlAttribute(draft.id)}" data-version-id="${escapeHtmlAttribute(version.id)}">Fassung zur Prüfung einreichen</button>` : ""}
      ${capabilities.canAssign && activePublication ? `<button class="primary-button" type="button" data-work-rule-action="assign-publication" data-publication-id="${escapeHtmlAttribute(activePublication.id)}">Datierte Zuordnung vorbereiten</button>` : ""}
      ${capabilities.canWithdrawPublication && activePublication ? `<button class="secondary-button" type="button" data-work-rule-action="withdraw-publication" data-publication-id="${escapeHtmlAttribute(activePublication.id)}">Veröffentlichung zurückziehen</button>` : ""}
    </div>
    <dl class="custom-work-rule-facts">
      <div><dt>Regelart</dt><dd>${escapeHtml(customWorkRuleCatalogLabel("ruleTypes", definition.ruleType))}</dd></div>
      <div><dt>Thema</dt><dd>${escapeHtml(customWorkRuleCatalogLabel("topics", definition.topic))}</dd></div>
      <div><dt>Geltungsbereich</dt><dd>${escapeHtml(definition.scopeLabel || customWorkRuleCatalogLabel("scopes", definition.scopeType))}</dd></div>
      <div><dt>Gültigkeit</dt><dd>${escapeHtml(formatDate(definition.validFrom))}${definition.validTo ? ` bis ${escapeHtml(formatDate(definition.validTo))}` : " · ohne Enddatum"}</dd></div>
      <div class="wide"><dt>Bedingung</dt><dd>${escapeHtml(customWorkRuleConditionLabel(definition))}</dd></div>
      <div><dt>Schweregrad</dt><dd>${escapeHtml(customWorkRuleCatalogLabel("severities", definition.severity))}</dd></div>
      <div><dt>Verantwortlich</dt><dd>${escapeHtml(definition.responsibleUnit || "–")}</dd></div>
      <div class="wide"><dt>Hinweistext</dt><dd>${escapeHtml(definition.message || "–")}</dd></div>
    </dl>
    <section class="custom-work-rule-source">
      <div><span>Quelle</span><strong>${escapeHtml(definition.sourceTitle || "–")}</strong><small>${escapeHtml(definition.sourceReference || "–")}</small></div>
      ${sourceUrl ? `<a href="${escapeHtmlAttribute(sourceUrl)}" target="_blank" rel="noopener noreferrer">Fundstelle öffnen</a>` : ""}
      ${definition.sourceNote ? `<p>${escapeHtml(definition.sourceNote)}</p>` : ""}
    </section>
    <section class="custom-work-rule-test-section">
      <div><span class="eyebrow">Deterministische Vorschau</span><h4>Pflicht-Testfälle</h4></div>
      ${renderCustomWorkRuleTestCases(definition.testCases)}
    </section>
    <section class="custom-work-rule-version-history">
      <h4>Unveränderliche Fassungen</h4>
      ${history}
    </section>
    ${context.requests.length ? `<section class="custom-work-rule-records"><div class="custom-work-rule-section-heading"><div><span class="eyebrow">Vier-Augen-Prinzip</span><h4>Prüf- und Freigabevorgänge</h4></div></div>${context.requests.map((request) => renderCustomWorkRuleRequestCard(request, capabilities)).join("")}</section>` : ""}
    ${context.assignments.length ? `<section class="custom-work-rule-records"><div class="custom-work-rule-section-heading"><div><span class="eyebrow">Datierte Wirkung</span><h4>Zuordnungen</h4></div></div>${context.assignments.map((assignment) => renderCustomWorkRuleAssignmentCard(assignment, capabilities)).join("")}</section>` : ""}
    ${renderCustomWorkRuleAudit(context, capabilities)}`;
}

function renderCustomWorkRuleRegistry() {
  const registry = state.customWorkRuleRegistry;
  if (!registry || !canAccessCustomWorkRuleGovernance()) return;
  const items = customWorkRuleItems();
  if (!items.some((item) => item.draft.id === state.selectedCustomWorkRuleId)) {
    state.selectedCustomWorkRuleId = items[0]?.draft.id || "";
  }
  if (elements.customWorkRuleNotice) {
    elements.customWorkRuleNotice.innerHTML = `<strong>Veröffentlichung und Wirksamkeit bleiben getrennt</strong><p>${escapeHtml(registry.notice || "Jede Entscheidung bezieht sich auf eine unveränderliche Fassung; Dienstplanwirkung entsteht ausschließlich durch eine freigegebene, datierte Zuordnung.")}</p>`;
  }
  renderCustomWorkRuleSummary(items);
  renderCustomWorkRuleTaskFilter(items);
  renderCustomWorkRuleList(items);
  renderCustomWorkRuleDetail(items);
  const generatedAt = state.workRuleGovernance?.generatedAt || registry.generatedAt;
  if (elements.customWorkRuleUpdated) {
    elements.customWorkRuleUpdated.textContent = generatedAt
      ? `Stand ${new Date(generatedAt).toLocaleString("de-AT")}`
      : "Aktueller Serverstand";
  }
  elements.addCustomWorkRuleButton?.classList.toggle("hidden", !workRuleGovernanceCapabilities().canDraft);
}

function customWorkRuleOptions(entries = [], selected = "") {
  return entries.map((entry) => `
    <option value="${escapeHtmlAttribute(entry.id)}" ${entry.id === selected ? "selected" : ""}>${escapeHtml(entry.label)}</option>
  `).join("");
}

function populateCustomWorkRuleCatalogs(definition = {}) {
  const catalogs = state.customWorkRuleRegistry?.catalogs || {};
  elements.customWorkRuleType.innerHTML = customWorkRuleOptions(catalogs.ruleTypes, definition.ruleType);
  elements.customWorkRuleTopic.innerHTML = customWorkRuleOptions(catalogs.topics, definition.topic);
  elements.customWorkRuleScopeType.innerHTML = customWorkRuleOptions(catalogs.scopes, definition.scopeType);
  elements.customWorkRuleMetric.innerHTML = customWorkRuleOptions(catalogs.metrics, definition.metric);
  elements.customWorkRuleSeverity.innerHTML = customWorkRuleOptions(catalogs.severities, definition.severity);
  elements.customWorkRuleReaction.innerHTML = customWorkRuleOptions(catalogs.reactions, definition.reaction);
}

function updateCustomWorkRuleScopeFields(selectedKey = "") {
  const ruleType = elements.customWorkRuleType.value;
  const allowedForLocationRule = ["location", "department"];
  [...elements.customWorkRuleScopeType.options].forEach((option) => {
    option.disabled = ruleType === "location_rule" && !allowedForLocationRule.includes(option.value);
  });
  if (ruleType === "location_rule" && !allowedForLocationRule.includes(elements.customWorkRuleScopeType.value)) {
    elements.customWorkRuleScopeType.value = "location";
  }
  const scopeType = elements.customWorkRuleScopeType.value;
  const usesSelect = ["business_unit", "location", "department"].includes(scopeType);
  const usesGroup = scopeType === "employee_group";
  elements.customWorkRuleScopeSelectField.classList.toggle("hidden", !usesSelect);
  elements.customWorkRuleScopeGroupField.classList.toggle("hidden", !usesGroup);
  elements.customWorkRuleScopeSelect.disabled = !usesSelect;
  elements.customWorkRuleScopeGroup.disabled = !usesGroup;
  elements.customWorkRuleScopeSelect.required = usesSelect;
  elements.customWorkRuleScopeGroup.required = usesGroup;
  if (!usesSelect) return;
  const organizationalScopes = state.customWorkRuleRegistry?.organizationalScopes || {};
  let options = [];
  if (scopeType === "business_unit") {
    elements.customWorkRuleScopeSelectLabel.textContent = "Betriebsteil";
    options = (organizationalScopes.businessUnits || []).map((unit) => ({
      id: String(unit.id),
      label: `${unit.code} · ${unit.name}`,
    }));
  } else if (scopeType === "location") {
    elements.customWorkRuleScopeSelectLabel.textContent = "Filiale";
    options = (organizationalScopes.locations || []).map((location) => ({
      id: String(location.id),
      label: `${location.id} · ${location.name}`,
    }));
  } else {
    elements.customWorkRuleScopeSelectLabel.textContent = "Abteilung";
    options = (organizationalScopes.locations || []).flatMap((location) => (
      (location.departments || []).map((department) => ({
        id: String(department.id),
        label: `${location.id} · ${location.name} · ${department.name}`,
      }))
    ));
  }
  elements.customWorkRuleScopeSelect.innerHTML = options.length
    ? options.map((option) => `<option value="${escapeHtmlAttribute(option.id)}">${escapeHtml(option.label)}</option>`).join("")
    : '<option value="">Noch keine passende Organisationseinheit</option>';
  const candidate = selectedKey || elements.customWorkRuleScopeSelect.value;
  elements.customWorkRuleScopeSelect.value = options.some((option) => option.id === String(candidate))
    ? String(candidate) : (options[0]?.id || "");
}

function customWorkRuleExampleDefaults(metric) {
  const thresholds = {
    maximum_planned_daily_minutes: 600,
    maximum_planned_weekly_minutes: 2400,
    minimum_planned_rest_minutes: 660,
    maximum_consecutive_workdays: 6,
    maximum_saturdays_per_month: 2,
    earliest_shift_start_time: "06:00",
    latest_shift_end_time: "20:00",
    minimum_vacation_request_lead_days: 14,
    minimum_time_off_request_lead_days: 7,
    maximum_vacation_days_per_request: 20,
  };
  const threshold = thresholds[metric.id] ?? (metric.min || 1);
  if (metric.valueType === "time") {
    const minutes = (value) => {
      const [hours, minute] = value.split(":").map(Number);
      return hours * 60 + minute;
    };
    const time = (value) => `${String(Math.floor(value / 60)).padStart(2, "0")}:${String(value % 60).padStart(2, "0")}`;
    const base = minutes(threshold);
    return {
      threshold,
      positive: time(metric.operator === "lte" ? Math.max(0, base - 60) : Math.min(1439, base + 60)),
      negative: time(metric.operator === "lte" ? Math.min(1439, base + 60) : Math.max(0, base - 60)),
    };
  }
  return {
    threshold,
    positive: metric.operator === "lte" ? Math.max(metric.min, threshold - 1) : Math.min(metric.max, threshold + 1),
    negative: metric.operator === "lte" ? Math.min(metric.max, threshold + 1) : Math.max(metric.min, threshold - 1),
  };
}

function updateCustomWorkRuleMetricFields({ resetValues = false } = {}) {
  const metric = customWorkRuleCatalogEntry("metrics", elements.customWorkRuleMetric.value);
  if (!metric) return;
  elements.customWorkRuleOperator.value = metric.operatorLabel || metric.operator;
  elements.customWorkRuleMetricHelp.textContent = metric.help || "";
  for (const element of [
    elements.customWorkRuleThreshold,
    elements.customWorkRulePositiveTest,
    elements.customWorkRuleNegativeTest,
  ]) {
    element.type = metric.valueType === "time" ? "time" : "number";
    if (metric.valueType === "time") {
      element.removeAttribute("min");
      element.removeAttribute("max");
      element.removeAttribute("step");
    } else {
      element.min = String(metric.min);
      element.max = String(metric.max);
      element.step = String(metric.step || 1);
    }
  }
  elements.customWorkRuleThresholdUnit.textContent = metric.unitLabel || "";
  elements.customWorkRulePositiveUnit.textContent = metric.unitLabel || "";
  elements.customWorkRuleNegativeUnit.textContent = metric.unitLabel || "";
  if (resetValues) {
    const defaults = customWorkRuleExampleDefaults(metric);
    elements.customWorkRuleThreshold.value = String(defaults.threshold);
    elements.customWorkRulePositiveTest.value = String(defaults.positive);
    elements.customWorkRuleNegativeTest.value = String(defaults.negative);
  }
  resetCustomWorkRuleSimulation();
}

function resetCustomWorkRuleSimulation() {
  state.customWorkRuleSimulationValid = false;
  if (elements.customWorkRuleTestResult) {
    elements.customWorkRuleTestResult.className = "custom-work-rule-test-result";
    elements.customWorkRuleTestResult.textContent = "Nach Änderungen erneut prüfen.";
  }
}

function customWorkRulePayload() {
  const scopeType = elements.customWorkRuleScopeType.value;
  const scopeKey = scopeType === "employee_group"
    ? elements.customWorkRuleScopeGroup.value.trim()
    : (scopeType === "installation" ? "" : elements.customWorkRuleScopeSelect.value);
  return {
    code: elements.customWorkRuleCode.value.trim(),
    title: elements.customWorkRuleTitle.value.trim(),
    description: elements.customWorkRuleDescription.value.trim(),
    ruleType: elements.customWorkRuleType.value,
    topic: elements.customWorkRuleTopic.value,
    scopeType,
    scopeKey,
    validFrom: elements.customWorkRuleValidFrom.value,
    validTo: elements.customWorkRuleValidTo.value || null,
    metric: elements.customWorkRuleMetric.value,
    threshold: elements.customWorkRuleThreshold.value,
    severity: elements.customWorkRuleSeverity.value,
    reaction: elements.customWorkRuleReaction.value,
    message: elements.customWorkRuleMessage.value.trim(),
    responsibleUnit: elements.customWorkRuleResponsibleUnit.value.trim(),
    sourceTitle: elements.customWorkRuleSourceTitle.value.trim(),
    sourceReference: elements.customWorkRuleSourceReference.value.trim(),
    sourceUrl: elements.customWorkRuleSourceUrl.value.trim(),
    sourceNote: elements.customWorkRuleSourceNote.value.trim(),
    testCases: {
      positiveValue: elements.customWorkRulePositiveTest.value,
      negativeValue: elements.customWorkRuleNegativeTest.value,
    },
    status: "draft",
    enforcementMode: "monitor",
  };
}

function openCustomWorkRuleModal(draft = null) {
  if (!canDraftCustomWorkRules() || !elements.customWorkRuleModal) return;
  elements.customWorkRuleForm.reset();
  const definition = draft?.currentVersion?.definition || {};
  populateCustomWorkRuleCatalogs(definition);
  elements.customWorkRuleId.value = draft?.id || "";
  elements.customWorkRuleCode.value = draft?.code || "";
  elements.customWorkRuleCode.disabled = Boolean(draft);
  document.querySelectorAll(".custom-work-rule-new-only").forEach((field) => field.classList.toggle("hidden", Boolean(draft)));
  elements.customWorkRuleTitle.value = definition.title || draft?.title || "";
  elements.customWorkRuleDescription.value = definition.description || draft?.description || "";
  elements.customWorkRuleValidFrom.value = definition.validFrom || toIsoDate(new Date());
  elements.customWorkRuleValidTo.value = definition.validTo || "";
  elements.customWorkRuleMessage.value = definition.message || "";
  elements.customWorkRuleResponsibleUnit.value = definition.responsibleUnit || "Personalleitung";
  elements.customWorkRuleSourceTitle.value = definition.sourceTitle || "";
  elements.customWorkRuleSourceReference.value = definition.sourceReference || "";
  elements.customWorkRuleSourceUrl.value = definition.sourceUrl || "";
  elements.customWorkRuleSourceNote.value = definition.sourceNote || "";
  elements.customWorkRuleScopeGroup.value = definition.scopeType === "employee_group" ? (definition.scopeKey || "") : "";
  updateCustomWorkRuleScopeFields(definition.scopeKey || "");
  updateCustomWorkRuleMetricFields({ resetValues: !draft });
  if (draft) {
    elements.customWorkRuleThreshold.value = String(definition.threshold ?? "");
    elements.customWorkRulePositiveTest.value = String(definition.positiveTestValue ?? "");
    elements.customWorkRuleNegativeTest.value = String(definition.negativeTestValue ?? "");
  }
  elements.customWorkRuleModalTitle.textContent = draft ? "Neue Entwurfsfassung" : "Regelentwurf anlegen";
  elements.customWorkRuleSubmitButton.textContent = draft ? "Neue Fassung speichern" : "Entwurf speichern";
  resetCustomWorkRuleSimulation();
  elements.customWorkRuleModal.showModal();
}

async function simulateCustomWorkRuleDraft() {
  if (!elements.customWorkRuleForm.reportValidity()) return false;
  elements.simulateCustomWorkRuleButton.disabled = true;
  elements.customWorkRuleTestResult.className = "custom-work-rule-test-result";
  elements.customWorkRuleTestResult.textContent = "Testfälle werden serverseitig geprüft.";
  try {
    const result = await api("/api/work-rules/drafts/simulate", {
      method: "POST",
      body: JSON.stringify(customWorkRulePayload()),
    });
    const simulation = result.simulation || {};
    state.customWorkRuleSimulationValid = simulation.valid === true;
    elements.customWorkRuleTestResult.className = `custom-work-rule-test-result ${state.customWorkRuleSimulationValid ? "valid" : "invalid"}`;
    elements.customWorkRuleTestResult.innerHTML = state.customWorkRuleSimulationValid
      ? `<strong>Alle drei Testfälle passen.</strong><span>eingehalten · verletzt · fehlender Prüfwert</span>`
      : "<strong>Die Testfälle passen noch nicht.</strong>";
    return state.customWorkRuleSimulationValid;
  } catch (error) {
    state.customWorkRuleSimulationValid = false;
    elements.customWorkRuleTestResult.className = "custom-work-rule-test-result invalid";
    elements.customWorkRuleTestResult.textContent = error.message;
    showToast(error.message, true);
    return false;
  } finally {
    elements.simulateCustomWorkRuleButton.disabled = false;
  }
}

async function saveCustomWorkRule(event) {
  event.preventDefault();
  if (!canDraftCustomWorkRules()) return;
  if (!state.customWorkRuleSimulationValid && !(await simulateCustomWorkRuleDraft())) return;
  const draftId = elements.customWorkRuleId.value;
  elements.customWorkRuleSubmitButton.disabled = true;
  try {
    const result = await api(draftId
      ? `/api/work-rules/drafts/${encodeURIComponent(draftId)}/revisions`
      : "/api/work-rules/drafts", {
      method: "POST",
      body: JSON.stringify(customWorkRulePayload()),
    });
    elements.customWorkRuleModal.close();
    state.selectedCustomWorkRuleId = result.draft?.id || draftId;
    await loadCustomWorkRuleRegistry({ force: true });
    showToast(draftId
      ? "Die neue unveränderliche Entwurfsfassung wurde gespeichert."
      : "Der Regelentwurf wurde ohne Dienstplanwirkung gespeichert.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.customWorkRuleSubmitButton.disabled = false;
  }
}

function workRuleGovernanceSummaryMarkup({ title, versionLabel, scopeLabel, basisSha256 } = {}) {
  return `<div>
    <span class="eyebrow">${escapeHtml(versionLabel || "Unveränderliche Prüfbasis")}</span>
    <strong>${escapeHtml(title || "Eigene Personalregel")}</strong>
    ${scopeLabel ? `<small>${escapeHtml(scopeLabel)}</small>` : ""}
  </div>${basisSha256 ? `<code title="${escapeHtmlAttribute(basisSha256)}">${escapeHtml(String(basisSha256).slice(0, 16))}…</code>` : ""}`;
}

function workRuleClientRequestId(operation) {
  const suffix = globalThis.crypto?.randomUUID
    ? globalThis.crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  return `gp-${operation}-${suffix}`;
}

function findWorkRuleRequest(id) {
  return workRuleGovernanceEntries("requests").find((entry) => entry.id === id) || null;
}

function findWorkRulePublication(id) {
  return workRuleGovernanceEntries("publications").find((entry) => entry.id === id) || null;
}

function findWorkRuleAssignment(id) {
  return workRuleGovernanceEntries("assignments").find((entry) => (
    entry.id === id
    || entry.governedRevisionId === id
    || entry.logicalAssignmentId === id
  )) || null;
}

function customWorkRuleForGovernanceSubject(subject = {}) {
  let profileId = workRuleProfileId(
    subject.profileId
    || subject.subjectId
    || subject.releasedProfileVersionId
    || subject.sourceProfileVersionId
    || subject.profileVersionId,
  );
  if (!profileId && subject.subjectId) {
    const publication = findWorkRulePublication(subject.subjectId);
    const assignment = findWorkRuleAssignment(subject.subjectId);
    profileId = workRuleProfileId(
      publication?.profileId
      || publication?.releasedProfileVersionId
      || assignment?.profileId
      || assignment?.profileVersionId,
    );
  }
  return (state.customWorkRuleRegistry?.drafts || []).find((entry) => entry.id === profileId) || null;
}

function workRuleGovernanceSubjectType(operation) {
  return ({
    publish_rule: "work_rule_profile_version",
    activate_assignment: "work_rule_publication",
    deactivate_assignment: "work_rule_assignment_revision",
    withdraw_publication: "work_rule_publication",
    approve_kv_assignment: "collective_agreement_assignment",
    deactivate_kv_assignment: "collective_agreement_assignment",
  })[operation] || "";
}

async function previewWorkRuleGovernance(operation, subjectId, payload = {}) {
  const result = await api("/api/work-rules/governance/preview", {
    method: "POST",
    body: JSON.stringify({
      operation,
      subjectType: workRuleGovernanceSubjectType(operation),
      subjectId,
      payload,
    }),
  });
  return result.preview || result;
}

async function createWorkRuleGovernanceRequest({
  operation,
  subjectId,
  payload = {},
  reason,
  sourceReference,
  basisSha256,
  conflictRunId,
}) {
  return api("/api/work-rules/governance/requests", {
    method: "POST",
    body: JSON.stringify({
      operation,
      subjectType: workRuleGovernanceSubjectType(operation),
      subjectId,
      payload,
      reason,
      sourceReference,
      clientRequestId: workRuleClientRequestId(operation),
      basisSha256,
      conflictRunId,
    }),
  });
}

async function openWorkRuleReviewModal(action, { profileId = "", versionId = "", requestId = "" } = {}) {
  if (!elements.workRuleReviewModal) return;
  const request = requestId ? findWorkRuleRequest(requestId) : null;
  const draft = (state.customWorkRuleRegistry?.drafts || []).find((entry) => entry.id === profileId)
    || customWorkRuleForGovernanceSubject(request || {});
  const collectiveAssignment = request
    ? (state.collectiveAgreementRegistry?.assignments || []).find((entry) => entry.id === request.subjectId)
    : null;
  const version = (draft?.versions || []).find((entry) => entry.id === versionId)
    || draft?.currentVersion;
  if (action === "submit" && (!draft || !version)) {
    showToast("Die unveränderliche Regelfassung wurde nicht gefunden.", true);
    return;
  }
  if (action !== "submit" && !request) {
    showToast("Der Prüfauftrag wurde nicht gefunden.", true);
    return;
  }
  elements.workRuleReviewForm.reset();
  state.workRuleGovernancePreview = null;
  elements.workRuleReviewAction.value = action;
  elements.workRuleReviewProfileId.value = draft?.id || "";
  elements.workRuleReviewVersionId.value = version?.id || request?.subjectId || "";
  elements.workRuleReviewRequestId.value = request?.id || "";
  elements.workRuleReviewBasisSha256.value = request?.basisSha256 || version?.contentSha256 || "";
  elements.workRuleReviewActor.textContent = workRuleActorLabel();
  elements.workRuleReviewSummary.innerHTML = workRuleGovernanceSummaryMarkup({
    title: version?.definition?.title || draft?.title
      || (collectiveAssignment
        ? `${collectiveAssignment.agreementCode} · ${collectiveAssignment.businessUnitName}`
        : request?.subjectLabel),
    versionLabel: version?.versionLabel || collectiveAssignment?.versionLabel || request?.subjectVersionLabel,
    scopeLabel: version?.definition?.scopeLabel || collectiveAssignment?.businessUnitName || request?.scopeLabel,
    basisSha256: request?.basisSha256 || version?.contentSha256,
  });
  const labels = {
    submit: ["Regelfassung zur Prüfung einreichen", "Die Einreichung startet das Vier-Augen-Verfahren und aktiviert die Fassung nicht.", "Zur Prüfung einreichen"],
    approve: ["Regelfassung fachlich freigeben", "Die Entscheidung wird dir persönlich zugerechnet. Eine Selbst- oder Stellvertretungsfreigabe verhindert der Server.", workRuleRequestApprovalCount(request) ? "Zweitfreigabe erteilen" : "Fachlich freigeben"],
    reject: ["Regelfassung ablehnen", "Die Ablehnung beendet diesen Prüfauftrag; die unveränderliche Fassung bleibt in der Historie.", "Begründet ablehnen"],
  };
  const collectiveLabels = {
    approve: ["KV-Zuordnung fachlich freigeben", "Die Entscheidung wird dir persönlich zugerechnet. Selbst- und Stellvertretungsfreigaben verhindert der Server.", workRuleRequestApprovalCount(request) ? "Zweitfreigabe erteilen" : "Fachlich freigeben"],
    reject: ["KV-Zuordnung ablehnen", "Die Ablehnung beendet diesen Prüfauftrag; Fassung, Zuordnungsvorschlag und Nachweise bleiben erhalten.", "Begründet ablehnen"],
  };
  const [title, copy, submitLabel] = request?.subjectType === "collective_agreement_assignment"
    ? (collectiveLabels[action] || labels[action])
    : (labels[action] || labels.submit);
  elements.workRuleReviewModalTitle.textContent = title;
  elements.workRuleReviewModalCopy.textContent = copy;
  elements.workRuleReviewSubmitButton.textContent = submitLabel;
  elements.workRuleReviewSubmitButton.classList.toggle("danger-button", action === "reject");
  elements.workRuleReviewSubmitButton.classList.toggle("primary-button", action !== "reject");
  const reviewSourceField = elements.workRuleReviewSourceReference.closest(".field");
  reviewSourceField?.classList.toggle("hidden", action !== "submit");
  elements.workRuleReviewSourceReference.required = action === "submit";
  elements.workRuleReviewSourceReference.disabled = action !== "submit";
  elements.workRuleReviewConflict.innerHTML = request
    ? workRuleConflictMarkup(request)
    : '<p>Die serverseitige Konfliktprüfung wird geladen.</p>';
  elements.workRuleReviewSubmitButton.disabled = action === "submit";
  elements.workRuleReviewModal.showModal();
  if (action !== "submit") return;
  try {
    const preview = await previewWorkRuleGovernance("publish_rule", version.id, {});
    state.workRuleGovernancePreview = preview;
    elements.workRuleReviewBasisSha256.value = preview.basisSha256 || "";
    elements.workRuleReviewConflict.innerHTML = workRuleConflictMarkup(preview);
    elements.workRuleReviewSubmitButton.disabled = workRuleConflict(preview).outcome === "blocked";
  } catch (error) {
    elements.workRuleReviewConflict.innerHTML = workRuleConflictMarkup({
      outcome: "blocked",
      title: "Konfliktprüfung fehlgeschlagen",
      note: error.message,
    });
    showToast(error.message, true);
  }
}

async function saveWorkRuleReview(event) {
  event.preventDefault();
  const action = elements.workRuleReviewAction.value;
  const reason = elements.workRuleReviewReason.value.trim();
  const sourceReference = elements.workRuleReviewSourceReference.value.trim();
  const reviewRequest = findWorkRuleRequest(elements.workRuleReviewRequestId.value);
  const collectiveOperation = ["approve_kv_assignment", "deactivate_kv_assignment"]
    .includes(reviewRequest?.operation);
  elements.workRuleReviewSubmitButton.disabled = true;
  try {
    if (action === "submit") {
      await createWorkRuleGovernanceRequest({
        operation: "publish_rule",
        subjectId: elements.workRuleReviewVersionId.value,
        reason,
        sourceReference,
        basisSha256: elements.workRuleReviewBasisSha256.value,
        conflictRunId: state.workRuleGovernancePreview?.conflictRunId,
      });
      showToast("Die unveränderliche Fassung wurde zur fachlichen Prüfung eingereicht.");
    } else {
      const requestId = elements.workRuleReviewRequestId.value;
      await api(`/api/work-rules/governance/requests/${encodeURIComponent(requestId)}/decisions`, {
        method: "POST",
        body: JSON.stringify({
          decision: action === "reject" ? "reject" : "approve",
          reason,
        }),
      });
      showToast(action === "reject"
        ? "Die Ablehnung wurde nachvollziehbar dokumentiert."
        : "Die persönliche Freigabe wurde dokumentiert.");
    }
    elements.workRuleReviewModal.close();
    if (collectiveOperation) await loadCollectiveAgreementRegistry({ force: true });
    else await loadCustomWorkRuleRegistry({ force: true });
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.workRuleReviewSubmitButton.disabled = false;
  }
}

function openWorkRuleFinalizeModal(requestId) {
  const request = findWorkRuleRequest(requestId);
  if (!request || !elements.workRuleFinalizeModal) {
    showToast("Der freigegebene Vorgang wurde nicht gefunden.", true);
    return;
  }
  const draft = customWorkRuleForGovernanceSubject(request);
  const collectiveAssignment = (state.collectiveAgreementRegistry?.assignments || [])
    .find((entry) => entry.id === request.subjectId);
  const version = (draft?.versions || []).find((entry) => entry.id === request.subjectId) || draft?.currentVersion;
  elements.workRuleFinalizeForm.reset();
  elements.workRuleFinalizeRequestId.value = request.id;
  elements.workRuleFinalizeBasisSha256.value = request.basisSha256 || "";
  elements.workRuleFinalizeActor.textContent = workRuleActorLabel();
  elements.workRuleFinalizeSummary.innerHTML = workRuleGovernanceSummaryMarkup({
    title: version?.definition?.title || draft?.title
      || (collectiveAssignment ? `${collectiveAssignment.agreementCode} · ${collectiveAssignment.businessUnitName}` : request.subjectLabel),
    versionLabel: collectiveAssignment?.versionLabel || workRuleOperationLabel(request.operation),
    scopeLabel: version?.definition?.scopeLabel || collectiveAssignment?.businessUnitName || request.scopeLabel,
    basisSha256: request.basisSha256,
  });
  elements.workRuleFinalizeConflict.innerHTML = workRuleConflictMarkup(request);
  elements.workRuleFinalizeModalTitle.textContent = request.operation === "publish_rule"
    ? "Freigegebene Fassung veröffentlichen"
    : "Freigegebenen Vorgang abschließen";
  elements.workRuleFinalizeModalCopy.textContent = "Fassung, Freigaben und Konfliktbasis werden unmittelbar vor dem Abschluss serverseitig erneut geprüft.";
  elements.workRuleFinalizeSubmitButton.textContent = request.operation === "publish_rule"
    ? "Veröffentlichen"
    : "Vorgang abschließen";
  elements.workRuleFinalizeModal.showModal();
}

async function saveWorkRuleFinalize(event) {
  event.preventDefault();
  elements.workRuleFinalizeSubmitButton.disabled = true;
  try {
    const requestId = elements.workRuleFinalizeRequestId.value;
    const collectiveOperation = ["approve_kv_assignment", "deactivate_kv_assignment"]
      .includes(findWorkRuleRequest(requestId)?.operation);
    await api(`/api/work-rules/governance/requests/${encodeURIComponent(requestId)}/finalize`, {
      method: "POST",
      body: JSON.stringify({
        reason: elements.workRuleFinalizeReason.value.trim(),
        sourceReference: elements.workRuleFinalizeSourceReference.value.trim(),
      }),
    });
    elements.workRuleFinalizeModal.close();
    if (collectiveOperation) await loadCollectiveAgreementRegistry({ force: true });
    else await loadCustomWorkRuleRegistry({ force: true });
    showToast("Der freigegebene Vorgang wurde auf unveränderter Prüfbasis abgeschlossen.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.workRuleFinalizeSubmitButton.disabled = false;
  }
}

function setWorkRuleAssignmentScope(definition = {}) {
  const scopeType = definition.scopeType || "installation";
  const scopeLabel = definition.scopeLabel || customWorkRuleCatalogLabel("scopes", scopeType);
  elements.workRuleAssignmentScopeType.innerHTML = `<option value="${escapeHtmlAttribute(scopeType)}">${escapeHtml(scopeLabel)}</option>`;
  elements.workRuleAssignmentScopeType.value = scopeType;
  elements.workRuleAssignmentScopeType.disabled = true;
  elements.workRuleAssignmentScopeSelectField.classList.add("hidden");
  elements.workRuleAssignmentScopeGroupField.classList.add("hidden");
  if (["business_unit", "location", "department"].includes(scopeType)) {
    elements.workRuleAssignmentScopeSelectField.classList.remove("hidden");
    elements.workRuleAssignmentScopeSelectLabel.textContent = "Aus veröffentlichter Fassung";
    elements.workRuleAssignmentScopeSelect.innerHTML = `<option value="${escapeHtmlAttribute(definition.scopeKey || "")}">${escapeHtml(scopeLabel)}</option>`;
    elements.workRuleAssignmentScopeSelect.disabled = true;
  } else if (scopeType === "employee_group") {
    elements.workRuleAssignmentScopeGroupField.classList.remove("hidden");
    elements.workRuleAssignmentScopeGroup.value = definition.scopeKey || scopeLabel;
    elements.workRuleAssignmentScopeGroup.readOnly = true;
    elements.workRuleAssignmentScopeGroup.disabled = false;
  }
}

function workRuleAssignmentPayload() {
  return {
    validFrom: elements.workRuleAssignmentValidFrom.value,
    validTo: elements.workRuleAssignmentValidTo.value || null,
    enforcementMode: elements.workRuleAssignmentEnforcementMode.value,
    applicabilityConfirmed: elements.workRuleAssignmentApplicabilityConfirmed.checked,
  };
}

function resetWorkRuleAssignmentPreview() {
  state.workRuleAssignmentPreviewValid = false;
  state.workRuleGovernancePreview = null;
  if (elements.workRuleAssignmentPreviewState) elements.workRuleAssignmentPreviewState.textContent = "Nach Änderungen erneut prüfen";
  if (elements.workRuleAssignmentSubmitButton) elements.workRuleAssignmentSubmitButton.disabled = true;
}

function openWorkRuleAssignmentModal(publicationId) {
  const publication = findWorkRulePublication(publicationId);
  if (!publication || !elements.workRuleAssignmentModal) {
    showToast("Die veröffentlichte Regelfassung wurde nicht gefunden.", true);
    return;
  }
  const draft = customWorkRuleForGovernanceSubject(publication);
  const version = (draft?.versions || []).find((entry) => (
    [publication.sourceProfileVersionId, publication.releasedProfileVersionId].includes(entry.id)
  )) || draft?.publishedVersion || draft?.currentVersion;
  const definition = version?.definition || publication.definition || {};
  elements.workRuleAssignmentForm.reset();
  elements.workRuleAssignmentPublicationId.value = publication.id;
  elements.workRuleAssignmentProfileId.value = draft?.id || publication.profileId || "";
  elements.workRuleAssignmentBasisSha256.value = publication.semanticSha256 || publication.receiptSha256 || "";
  elements.workRuleAssignmentSummary.innerHTML = workRuleGovernanceSummaryMarkup({
    title: definition.title || draft?.title || publication.title,
    versionLabel: version?.versionLabel || publication.versionLabel || "Veröffentlichte Fassung",
    scopeLabel: definition.scopeLabel || publication.scopeLabel,
    basisSha256: publication.semanticSha256 || publication.receiptSha256,
  });
  setWorkRuleAssignmentScope(definition);
  elements.workRuleAssignmentValidFrom.value = definition.validFrom || toIsoDate(new Date());
  elements.workRuleAssignmentValidTo.value = definition.validTo || "";
  elements.workRuleAssignmentEnforcementMode.value = "monitor";
  elements.workRuleAssignmentApplicabilityConfirmed.checked = false;
  elements.workRuleAssignmentApplicabilityConfirmed.required = true;
  elements.workRuleAssignmentConflict.innerHTML = "<p>Vor der Einreichung müssen Zeitraum und Überschneidungen serverseitig geprüft werden.</p>";
  resetWorkRuleAssignmentPreview();
  elements.workRuleAssignmentPreviewState.textContent = "Noch nicht geprüft";
  elements.workRuleAssignmentModal.showModal();
}

async function previewWorkRuleAssignment() {
  if (!elements.workRuleAssignmentForm.reportValidity()) return;
  if (!elements.workRuleAssignmentApplicabilityConfirmed.checked) {
    showToast("Vor jeder Zuordnung muss die fachliche Anwendbarkeit bestätigt sein.", true);
    return;
  }
  elements.previewWorkRuleAssignmentButton.disabled = true;
  try {
    const preview = await previewWorkRuleGovernance(
      "activate_assignment",
      elements.workRuleAssignmentPublicationId.value,
      workRuleAssignmentPayload(),
    );
    state.workRuleGovernancePreview = preview;
    state.workRuleAssignmentPreviewValid = workRuleConflict(preview).outcome !== "blocked";
    elements.workRuleAssignmentBasisSha256.value = preview.basisSha256 || "";
    elements.workRuleAssignmentConflict.innerHTML = workRuleConflictMarkup(preview);
    elements.workRuleAssignmentPreviewState.textContent = state.workRuleAssignmentPreviewValid
      ? "Prüfung aktuell · Einreichung möglich"
      : "Blockierender Konflikt";
    elements.workRuleAssignmentSubmitButton.disabled = !state.workRuleAssignmentPreviewValid;
  } catch (error) {
    elements.workRuleAssignmentConflict.innerHTML = workRuleConflictMarkup({
      outcome: "blocked",
      title: "Konfliktprüfung fehlgeschlagen",
      note: error.message,
    });
    showToast(error.message, true);
  } finally {
    elements.previewWorkRuleAssignmentButton.disabled = false;
  }
}

async function saveWorkRuleAssignment(event) {
  event.preventDefault();
  if (!state.workRuleAssignmentPreviewValid) {
    showToast("Bitte die Zuordnung nach der letzten Änderung erneut prüfen.", true);
    return;
  }
  elements.workRuleAssignmentSubmitButton.disabled = true;
  try {
    await createWorkRuleGovernanceRequest({
      operation: "activate_assignment",
      subjectId: elements.workRuleAssignmentPublicationId.value,
      payload: workRuleAssignmentPayload(),
      reason: elements.workRuleAssignmentReason.value.trim(),
      sourceReference: elements.workRuleAssignmentSourceReference.value.trim(),
      basisSha256: elements.workRuleAssignmentBasisSha256.value,
      conflictRunId: state.workRuleGovernancePreview?.conflictRunId,
    });
    elements.workRuleAssignmentModal.close();
    await loadCustomWorkRuleRegistry({ force: true });
    showToast("Der datierte Zuordnungsantrag wurde zur unabhängigen Freigabe eingereicht.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.workRuleAssignmentSubmitButton.disabled = false;
  }
}

async function openWorkRuleLifecycleModal(action, subjectId, { profileId = "", versionId = "" } = {}) {
  if (!elements.workRuleLifecycleModal) return;
  const assignment = action === "deactivate_assignment" ? findWorkRuleAssignment(subjectId) : null;
  const publication = action === "withdraw_publication" ? findWorkRulePublication(subjectId) : null;
  const collectiveAssignment = ["approve_kv_assignment", "deactivate_kv_assignment"].includes(action)
    ? (state.collectiveAgreementRegistry?.assignments || []).find((entry) => entry.id === subjectId)
    : null;
  const draft = action === "restore_version"
    ? (state.customWorkRuleRegistry?.drafts || []).find((entry) => entry.id === profileId)
    : customWorkRuleForGovernanceSubject(assignment || publication || {});
  const version = (draft?.versions || []).find((entry) => entry.id === versionId) || draft?.currentVersion;
  if (!draft && !assignment && !publication && !collectiveAssignment) {
    showToast("Der ausgewählte Regelvorgang wurde nicht gefunden.", true);
    return;
  }
  elements.workRuleLifecycleForm.reset();
  state.workRuleGovernancePreview = null;
  elements.workRuleLifecycleAction.value = action;
  elements.workRuleLifecycleSubjectId.value = subjectId;
  elements.workRuleLifecycleProfileId.value = draft?.id || profileId;
  elements.workRuleLifecycleVersionId.value = versionId;
  elements.workRuleLifecycleBasisSha256.value = assignment?.receiptSha256 || publication?.receiptSha256 || version?.contentSha256 || "";
  const today = toIsoDate(new Date());
  const earliestEffectiveOn = action === "approve_kv_assignment"
    ? collectiveAssignment.validFrom
    : (action === "deactivate_kv_assignment"
      ? (collectiveAssignment.governanceCurrentEffectiveOn
        || collectiveAssignment.governanceEffectiveOn
        || collectiveAssignment.validFrom)
      : (action === "deactivate_assignment" ? assignment?.validFrom : ""));
  elements.workRuleLifecycleEffectiveOn.value = earliestEffectiveOn && earliestEffectiveOn > today
    ? earliestEffectiveOn
    : (action === "approve_kv_assignment" ? earliestEffectiveOn : today);
  elements.workRuleLifecycleEffectiveOn.min = earliestEffectiveOn || "";
  elements.workRuleLifecycleEffectiveOn.max = collectiveAssignment?.validTo || assignment?.validTo || "";
  elements.workRuleLifecycleEffectiveOn.closest(".field")?.classList.toggle("hidden", action === "restore_version");
  elements.workRuleLifecycleEffectiveOn.required = action !== "restore_version";
  const copy = {
    deactivate_assignment: ["Zuordnung beenden", "Die Beendigung wird datiert beantragt und benötigt eine unabhängige Freigabe.", "Beendigung zur Freigabe einreichen"],
    withdraw_publication: ["Veröffentlichung zurückziehen", "Bestehende Fassungen, Prüfungen und frühere Wirkzeiträume bleiben vollständig erhalten.", "Rücknahme zur Freigabe einreichen"],
    restore_version: ["Historische Fassung wieder öffnen", "Die historische Fassung bleibt unverändert; aus ihr wird ausschließlich eine neue Entwurfsfassung erzeugt.", "Als neue Entwurfsfassung öffnen"],
    approve_kv_assignment: ["KV-Zuordnung zur Freigabe einreichen", "Die fachliche Anwendbarkeit wird auf der unveränderlichen Fassung und dem dokumentierten Betriebsteil im Vier-Augen-Prinzip geprüft.", "KV-Zuordnung zur Freigabe einreichen"],
    deactivate_kv_assignment: ["KV-Zuordnung kontrolliert beenden", "Die Beendigung wird datiert und im Vier-Augen-Prinzip freigegeben; frühere Nachweise bleiben erhalten.", "Beendigung zur Freigabe einreichen"],
  }[action];
  elements.workRuleLifecycleModalTitle.textContent = copy[0];
  elements.workRuleLifecycleModalCopy.textContent = copy[1];
  elements.workRuleLifecycleSubmitButton.textContent = copy[2];
  const constructiveAction = ["restore_version", "approve_kv_assignment"].includes(action);
  elements.workRuleLifecycleSubmitButton.classList.toggle("danger-button", !constructiveAction);
  elements.workRuleLifecycleSubmitButton.classList.toggle("primary-button", constructiveAction);
  elements.workRuleLifecycleSummary.innerHTML = workRuleGovernanceSummaryMarkup({
    title: version?.definition?.title || draft?.title || publication?.title || assignment?.scopeLabel
      || (collectiveAssignment ? `${collectiveAssignment.agreementCode} · ${collectiveAssignment.agreementTitle}` : ""),
    versionLabel: version?.versionLabel || collectiveAssignment?.versionLabel || workRuleOperationLabel(action),
    scopeLabel: assignment?.scopeLabel || version?.definition?.scopeLabel || publication?.scopeLabel
      || collectiveAssignment?.businessUnitName,
    basisSha256: elements.workRuleLifecycleBasisSha256.value,
  });
  elements.workRuleLifecycleBoundary.textContent = action === "restore_version"
    ? "Die Wiederöffnung überschreibt keine Fassung und erzeugt keine Dienstplanwirkung."
    : "Die Änderung überschreibt keine frühere Fassung und beendet keine historischen Nachweise.";
  elements.workRuleLifecycleConflict.innerHTML = action === "restore_version"
    ? workRuleConflictMarkup({ outcome: "pass", title: "Neue Entwurfsfassung ohne Wirkung", note: "Die bestehende Historie bleibt unverändert." })
    : "<p>Die serverseitige Konfliktprüfung wird geladen.</p>";
  elements.workRuleLifecycleSubmitButton.disabled = action !== "restore_version";
  elements.workRuleLifecycleModal.showModal();
  if (action === "restore_version") return;
  await refreshWorkRuleLifecyclePreview();
}

async function refreshWorkRuleLifecyclePreview() {
  const action = elements.workRuleLifecycleAction.value;
  if (![
    "deactivate_assignment",
    "withdraw_publication",
    "approve_kv_assignment",
    "deactivate_kv_assignment",
  ].includes(action)) return;
  elements.workRuleLifecycleSubmitButton.disabled = true;
  elements.workRuleLifecycleConflict.innerHTML = "<p>Die geänderte Wirksamkeit wird serverseitig erneut geprüft.</p>";
  try {
    const preview = await previewWorkRuleGovernance(action, elements.workRuleLifecycleSubjectId.value, {
      effectiveOn: elements.workRuleLifecycleEffectiveOn.value,
    });
    state.workRuleGovernancePreview = preview;
    elements.workRuleLifecycleBasisSha256.value = preview.basisSha256 || "";
    elements.workRuleLifecycleConflict.innerHTML = workRuleConflictMarkup(preview);
    elements.workRuleLifecycleSubmitButton.disabled = workRuleConflict(preview).outcome === "blocked";
  } catch (error) {
    elements.workRuleLifecycleConflict.innerHTML = workRuleConflictMarkup({
      outcome: "blocked",
      title: "Konfliktprüfung fehlgeschlagen",
      note: error.message,
    });
    showToast(error.message, true);
  }
}

async function saveWorkRuleLifecycle(event) {
  event.preventDefault();
  const action = elements.workRuleLifecycleAction.value;
  elements.workRuleLifecycleSubmitButton.disabled = true;
  try {
    if (action === "restore_version") {
      await api(`/api/work-rules/drafts/${encodeURIComponent(elements.workRuleLifecycleProfileId.value)}/versions/${encodeURIComponent(elements.workRuleLifecycleVersionId.value)}/restore`, {
        method: "POST",
        body: JSON.stringify({
          reason: elements.workRuleLifecycleReason.value.trim(),
          sourceReference: elements.workRuleLifecycleSourceReference.value.trim(),
        }),
      });
      showToast("Die historische Fassung wurde als neue, noch nicht wirksame Entwurfsfassung geöffnet.");
    } else {
      await createWorkRuleGovernanceRequest({
        operation: action,
        subjectId: elements.workRuleLifecycleSubjectId.value,
        payload: { effectiveOn: elements.workRuleLifecycleEffectiveOn.value },
        reason: elements.workRuleLifecycleReason.value.trim(),
        sourceReference: elements.workRuleLifecycleSourceReference.value.trim(),
        basisSha256: elements.workRuleLifecycleBasisSha256.value,
        conflictRunId: state.workRuleGovernancePreview?.conflictRunId,
      });
      showToast("Die kontrollierte Änderung wurde zur unabhängigen Freigabe eingereicht.");
    }
    elements.workRuleLifecycleModal.close();
    if (["approve_kv_assignment", "deactivate_kv_assignment"].includes(action)) {
      await loadCollectiveAgreementRegistry({ force: true });
    } else {
      await loadCustomWorkRuleRegistry({ force: true });
    }
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.workRuleLifecycleSubmitButton.disabled = false;
  }
}

function collectiveAgreementReviewLabel(value) {
  return ({
    review_pending: "Prüfung offen",
    approved: "Freigegeben",
    retired: "Historisch",
  })[value] || "Prüfung offen";
}

function collectiveAgreementApprenticeLabel(value) {
  return ({ yes: "Lehrlingsrelevant", no: "Nicht lehrlingsrelevant", unknown: "Lehrlingsrelevanz offen" })[value]
    || "Lehrlingsrelevanz offen";
}

function collectiveAgreementValidity(from, to) {
  return `${formatDate(from)}${to ? ` – ${formatDate(to)}` : " – offen"}`;
}

async function loadCollectiveAgreementRegistry({ force = false } = {}) {
  if (!canReadCollectiveAgreements() || state.collectiveAgreementsLoading) return;
  if (state.collectiveAgreementRegistry && state.workRuleGovernance && !force) {
    renderCollectiveAgreementRegistry();
    return;
  }
  state.collectiveAgreementsLoading = true;
  if (elements.collectiveAgreementList) {
    elements.collectiveAgreementList.innerHTML = '<p class="settings-note">KV-Fassungen werden geladen.</p>';
  }
  try {
    const [registryResult, governanceResult] = await Promise.allSettled([
      api("/api/collective-agreements/registry"),
      api("/api/work-rules/governance"),
    ]);
    if (registryResult.status === "rejected") throw registryResult.reason;
    state.collectiveAgreementRegistry = registryResult.value;
    if (governanceResult.status === "fulfilled") state.workRuleGovernance = governanceResult.value;
    const agreementIds = new Set((state.collectiveAgreementRegistry.agreements || []).map((agreement) => agreement.id));
    if (!agreementIds.has(state.selectedCollectiveAgreementId)) {
      state.selectedCollectiveAgreementId = state.collectiveAgreementRegistry.agreements?.[0]?.id || "";
    }
    renderCollectiveAgreementRegistry();
  } catch (error) {
    state.collectiveAgreementRegistry = null;
    if (elements.collectiveAgreementList) {
      elements.collectiveAgreementList.innerHTML = `<p class="settings-note">${escapeHtml(error.message)}</p>`;
    }
    throw error;
  } finally {
    state.collectiveAgreementsLoading = false;
  }
}

function renderCollectiveAgreementSummary(registry) {
  if (!elements.collectiveAgreementSummary) return;
  const summary = registry.summary || {};
  elements.collectiveAgreementSummary.innerHTML = [
    ["Registereinträge", summary.agreements || 0, "externe Verträge"],
    ["Fassungen", summary.versions || 0, "unveränderliche Quellenstände"],
    ["Betriebsteile", summary.businessUnits || 0, registry.scopeLabel || "sichtbarer Bereich"],
    ["Prüfung offen", summary.pendingAssignments || 0, "noch ohne Wirksamkeit"],
  ].map(([label, value, note], index) => `
    <article class="personnel-administration-stat ${index === 3 && Number(value) ? "warning" : ""}">
      <span>${escapeHtml(label)}</span><strong>${Number(value)}</strong><small>${escapeHtml(note)}</small>
    </article>
  `).join("");
}

function renderCollectiveAgreementList(registry) {
  if (!elements.collectiveAgreementList) return;
  const agreements = registry.agreements || [];
  if (!agreements.length) {
    elements.collectiveAgreementList.innerHTML = `
      <div class="collective-agreement-empty">
        <strong>Noch kein externer Kollektivvertrag registriert</strong>
        <p>Foto/Multimedia, Printcenter und IT werden bewusst nicht vorab rechtlich zugeordnet. Zuerst müssen Quelle, Rechtsträger und Geltungsbereich bestätigt werden.</p>
      </div>`;
    return;
  }
  elements.collectiveAgreementList.innerHTML = agreements.map((agreement) => {
    const current = agreement.versions.find((version) => version.id === agreement.currentVersionId) || null;
    const displayedVersion = current || agreement.versions[0] || null;
    const active = agreement.id === state.selectedCollectiveAgreementId;
    return `
      <button type="button" class="collective-agreement-list-item ${active ? "active" : ""}" data-collective-agreement-id="${escapeHtmlAttribute(agreement.id)}" ${active ? 'aria-current="true"' : ""}>
        <span class="collective-agreement-code">${escapeHtml(agreement.code)}</span>
        <strong>${escapeHtml(agreement.shortTitle || agreement.title)}</strong>
        <small>${current
          ? `${escapeHtml(current.versionLabel)} · ${escapeHtml(collectiveAgreementValidity(current.validFrom, current.validTo))}`
          : displayedVersion
            ? `${escapeHtml(displayedVersion.versionLabel)} · zugeordnete historische Fassung`
            : "Noch keine Fassung"}</small>
        <span class="status-badge warning">${escapeHtml(collectiveAgreementReviewLabel(agreement.reviewState))}</span>
      </button>`;
  }).join("");
}

function collectiveAgreementDefinitionList(version) {
  const entries = [
    ["Räumlich", version.territorialScope],
    ["Fachlich", version.functionalScope],
    ["Persönlich", version.personalScope],
    ["Beschäftigtengruppen", (version.employeeGroups || []).join(", ")],
    ["Arbeitszeitparameter", version.workTimeParametersNote],
    ["Einstufung", version.classificationNote],
    ["Lehrlinge", `${collectiveAgreementApprenticeLabel(version.apprenticeRelevance)}${version.apprenticeNote ? ` · ${version.apprenticeNote}` : ""}`],
    ["Nachfolge / Ersetzung", version.successorNote],
  ].filter(([, value]) => String(value || "").trim());
  return entries.length ? entries.map(([label, value]) => `
    <div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>
  `).join("") : '<p class="settings-note">Der Geltungsbereich ist noch nicht vollständig dokumentiert.</p>';
}

function renderCollectiveAgreementDetail(registry) {
  if (!elements.collectiveAgreementDetail) return;
  const agreement = (registry.agreements || []).find((entry) => entry.id === state.selectedCollectiveAgreementId);
  if (!agreement) {
    elements.collectiveAgreementDetail.innerHTML = `
      <div class="collective-agreement-empty"><strong>Noch keine Fassung ausgewählt</strong><p>Wähle links einen Registereintrag.</p></div>`;
    return;
  }
  const current = agreement.versions.find((version) => version.id === agreement.currentVersionId) || null;
  const displayedVersion = current || agreement.versions[0] || null;
  if (!displayedVersion) return;
  const parties = displayedVersion.contractingParties?.length
    ? displayedVersion.contractingParties.join(" · ")
    : "Noch nicht dokumentiert";
  const sourceHash = displayedVersion.source.sha256 || displayedVersion.contentSha256;
  const versionHistory = agreement.versions.map((version) => `
    <article class="${version.id === agreement.currentVersionId ? "current" : ""}">
      <div><strong>${escapeHtml(version.versionLabel)}</strong><small>${escapeHtml(collectiveAgreementValidity(version.validFrom, version.validTo))}</small></div>
      <span>${version.id === agreement.currentVersionId ? "Aktueller Registerstand" : current ? "Historische Fassung" : "Zugeordnete historische Fassung"}</span>
    </article>`).join("");
  elements.collectiveAgreementDetail.innerHTML = `
    <div class="collective-agreement-detail-heading">
      <div>
        <span class="eyebrow">${escapeHtml(agreement.code)} · ${escapeHtml(agreement.jurisdiction)}</span>
        <h3>${escapeHtml(agreement.title)}</h3>
        <p>${escapeHtml(agreement.note || "Externer Registereintrag ohne bestätigte betriebliche Anwendbarkeit.")}</p>
      </div>
      <div class="collective-agreement-detail-actions">
        <span class="status-badge warning">${escapeHtml(collectiveAgreementReviewLabel(agreement.reviewState))}</span>
        ${registry.capabilities?.canManage ? `<button type="button" class="secondary-button" data-add-collective-agreement-version="${escapeHtmlAttribute(agreement.id)}">+ Neue Fassung</button>` : ""}
      </div>
    </div>
    ${current ? "" : '<p class="settings-note collective-agreement-current-visibility">Der aktuelle Registerstand ist in dieser bereichsbezogenen Lesesicht nicht sichtbar. Angezeigt wird ausschließlich eine dem eigenen Bereich zugeordnete historische Fassung.</p>'}
    <div class="collective-agreement-source-card">
      <div><span>${current ? "Fassung" : "Sichtbare Fassung"}</span><strong>${escapeHtml(displayedVersion.versionLabel)}</strong><small>${escapeHtml(collectiveAgreementValidity(displayedVersion.validFrom, displayedVersion.validTo))}</small></div>
      <div><span>Vertragsparteien</span><strong>${escapeHtml(parties)}</strong><small>${displayedVersion.externalPublishedOn ? `extern veröffentlicht ${escapeHtml(formatDate(displayedVersion.externalPublishedOn))}` : "Veröffentlichungsdatum offen"}</small></div>
      <div class="source-wide"><span>Dokumentierte Quelle</span><strong><a href="${escapeHtmlAttribute(displayedVersion.source.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(displayedVersion.source.title)}</a></strong><small>abgerufen ${escapeHtml(formatDate(displayedVersion.source.retrievedOn))} · Integritätswert ${escapeHtml(sourceHash.slice(0, 16))}…</small></div>
    </div>
    <dl class="collective-agreement-applicability">${collectiveAgreementDefinitionList(displayedVersion)}</dl>
    ${displayedVersion.linkedProfileVersionId ? `<p class="collective-agreement-profile-link">Vorbereitete Regelprofil-Verknüpfung: <strong>${escapeHtml(displayedVersion.linkedProfileVersionId)}</strong>. Noch nicht aktiviert.</p>` : ""}
    <section class="collective-agreement-version-history">
      <div><span class="eyebrow">Nicht überschreibbar</span><h4>Versionshistorie</h4></div>
      ${versionHistory}
    </section>`;
}

function renderCollectiveAgreementBusinessUnits(registry) {
  if (!elements.collectiveAgreementBusinessUnits) return;
  const units = registry.businessUnits || [];
  elements.collectiveAgreementBusinessUnits.innerHTML = units.length ? units.map((unit) => `
    <article class="collective-agreement-business-unit" data-collective-agreement-business-unit="${escapeHtmlAttribute(unit.id)}">
      <div><span>${escapeHtml(unit.code)}</span><strong>${escapeHtml(unit.name)}</strong><small>${escapeHtml(unit.legalEntityName)}</small></div>
      <p>${escapeHtml(unit.description || "Keine zusätzliche Beschreibung.")}</p>
      <div class="collective-agreement-scope-tags">${unit.scopes.length
        ? unit.scopes.map((scope) => `<span>${escapeHtml(scope.label)}</span>`).join("")
        : '<span class="warning">Noch ohne organisatorischen Bereich</span>'}</div>
      ${registry.capabilities?.canManage ? '<button class="text-action" type="button" data-add-business-unit-scopes>Bereiche ergänzen</button>' : ""}
    </article>`).join("") : `
      <div class="collective-agreement-empty compact"><strong>Noch keine Betriebsteile</strong><p>Lege Rechtsträger und ihre tatsächlichen organisatorischen Bereiche zuerst neutral an.</p></div>`;
}

function collectiveAgreementGovernanceStateLabel(stateValue, effectiveOn) {
  return ({
    review_pending: "Freigabe noch nicht eingereicht",
    approval_planned: `Freigegeben · wirksam ab ${formatDate(effectiveOn)}`,
    approved: "Wirksam zugeordnet",
    deactivation_planned: `Beendigung geplant ab ${formatDate(effectiveOn)}`,
    deactivated: "Beendet",
  })[stateValue] || collectiveAgreementReviewLabel(stateValue);
}

function renderCollectiveAgreementAssignments(registry) {
  if (!elements.collectiveAgreementAssignments) return;
  const assignments = registry.assignments || [];
  const canApprove = Boolean(registry.capabilities?.canApprove
    && state.workRuleGovernance?.capabilities?.canApproveCollectiveAgreement);
  elements.collectiveAgreementAssignments.innerHTML = assignments.length ? assignments.map((assignment) => {
    const requests = workRuleGovernanceEntries("requests").filter((entry) => (
      entry.subjectId === assignment.id
      && ["approve_kv_assignment", "deactivate_kv_assignment"].includes(entry.operation)
    ));
    const openApproval = requests.some((entry) => (
      entry.operation === "approve_kv_assignment"
      && ["in_review", "approved"].includes(workRuleRequestState(entry))
    ));
    const openDeactivation = requests.some((entry) => (
      entry.operation === "deactivate_kv_assignment"
      && ["in_review", "approved"].includes(workRuleRequestState(entry))
    ));
    const label = collectiveAgreementGovernanceStateLabel(
      assignment.governanceState,
      assignment.governanceEffectiveOn,
    );
    const tone = ["approved", "approval_planned"].includes(assignment.governanceState)
      ? "success"
      : assignment.governanceState === "deactivated" ? "inactive" : "warning";
    const requestCapabilities = {
      canReview: canApprove,
      canApproveCollectiveAgreement: canApprove,
    };
    return `
    <article class="collective-agreement-assignment governed" data-collective-agreement-assignment="${escapeHtmlAttribute(assignment.id)}">
      <div>
        <span class="status-badge ${tone}">${escapeHtml(label)}</span>
        <strong>${escapeHtml(assignment.businessUnitCode)} · ${escapeHtml(assignment.businessUnitName)}</strong>
        <small>${escapeHtml(assignment.agreementCode)} · Fassung ${escapeHtml(assignment.versionLabel)} · ${escapeHtml(collectiveAgreementValidity(assignment.validFrom, assignment.validTo))}</small>
      </div>
      <p>${escapeHtml(assignment.rationale)}</p>
      ${assignment.referenceNote ? `<small>${escapeHtml(assignment.referenceNote)}</small>` : ""}
      ${canApprove && assignment.governanceState === "review_pending" && !openApproval ? `<div class="collective-agreement-governance-actions"><button class="primary-button" type="button" data-kv-governance-action="approve_kv_assignment">Zur Freigabe einreichen</button></div>` : ""}
      ${canApprove && ["approved", "approval_planned"].includes(assignment.governanceState) && !openDeactivation ? `<div class="collective-agreement-governance-actions"><button class="danger-button" type="button" data-kv-governance-action="deactivate_kv_assignment">Zuordnung kontrolliert beenden</button></div>` : ""}
      ${requests.length ? `<div class="collective-agreement-governance-requests">${requests.map((request) => renderCustomWorkRuleRequestCard(request, requestCapabilities)).join("")}</div>` : ""}
    </article>`;
  }).join("") : `
      <div class="collective-agreement-empty compact"><strong>Keine Zuordnung vorbereitet</strong><p>Ohne bestätigte Quelle und Betriebsteil soll kein Kollektivvertrag vorweggenommen werden.</p></div>`;
}

function renderCollectiveAgreementRegistry() {
  const registry = state.collectiveAgreementRegistry;
  if (!registry || !canReadCollectiveAgreements()) return;
  if (elements.collectiveAgreementLegalNotice) {
    elements.collectiveAgreementLegalNotice.innerHTML = `<strong>Register und Freigabeweg, keine pauschale Rechtsbestätigung</strong><p>Externe Quellenstände und interne Zuordnungsvorschläge bleiben getrennt. Eine KV-Zuordnung wird erst nach Konfliktprüfung, zwei unabhängigen Entscheidungen und datiertem Abschluss wirksam; die rechtliche Einzelfallprüfung bleibt erforderlich.</p>`;
  }
  renderCollectiveAgreementSummary(registry);
  renderCollectiveAgreementList(registry);
  renderCollectiveAgreementDetail(registry);
  renderCollectiveAgreementBusinessUnits(registry);
  renderCollectiveAgreementAssignments(registry);
  elements.addCollectiveAgreementButton?.classList.toggle("hidden", !registry.capabilities?.canManage);
  elements.addCollectiveAgreementBusinessUnitButton?.classList.toggle("hidden", !registry.capabilities?.canManage);
  elements.addCollectiveAgreementAssignmentButton?.classList.toggle("hidden", !registry.capabilities?.canPrepareAssignments);
}

function collectiveAgreementVersionOptions(registry) {
  return (registry.agreements || []).flatMap((agreement) => (agreement.versions || []).map((version) => ({
    ...version,
    agreement,
  })));
}

function populateCollectiveAgreementProfileOptions(selected = "") {
  if (!elements.collectiveAgreementLinkedProfileVersion) return;
  const options = state.collectiveAgreementRegistry?.ruleProfileVersions || [];
  elements.collectiveAgreementLinkedProfileVersion.innerHTML = `<option value="">Noch keines</option>${options.map((profile) => `
    <option value="${escapeHtmlAttribute(profile.id)}">${escapeHtml(`${profile.profileName} · ${profile.version} · ${profile.status === "published" ? "veröffentlicht" : "Entwurf"}`)}</option>
  `).join("")}`;
  elements.collectiveAgreementLinkedProfileVersion.value = options.some((profile) => profile.id === selected) ? selected : "";
}

function openCollectiveAgreementModal(agreement = null) {
  if (!canManageCollectiveAgreements() || !elements.collectiveAgreementModal) return;
  elements.collectiveAgreementForm.reset();
  const today = toIsoDate(new Date());
  const newVersion = Boolean(agreement);
  elements.collectiveAgreementId.value = agreement?.id || "";
  elements.collectiveAgreementCode.value = agreement?.code || "";
  elements.collectiveAgreementShortTitle.value = agreement?.shortTitle || "";
  elements.collectiveAgreementTitle.value = agreement?.title || "";
  elements.collectiveAgreementJurisdiction.value = agreement?.jurisdiction || "AT";
  elements.collectiveAgreementSourceRetrievedOn.value = today;
  elements.collectiveAgreementModalTitle.textContent = newVersion ? "Neue KV-Fassung ergänzen" : "Kollektivvertrag erfassen";
  elements.collectiveAgreementSubmitButton.textContent = newVersion ? "Neue Fassung speichern" : "Registereintrag speichern";
  [elements.collectiveAgreementCode, elements.collectiveAgreementShortTitle,
    elements.collectiveAgreementTitle, elements.collectiveAgreementJurisdiction]
    .forEach((input) => { input.disabled = newVersion; });
  document.querySelectorAll(".new-collective-agreement-only").forEach((field) => field.classList.toggle("hidden", newVersion));
  populateCollectiveAgreementProfileOptions();
  elements.collectiveAgreementModal.showModal();
}

function collectiveAgreementVersionPayload() {
  return {
    versionLabel: elements.collectiveAgreementVersionLabel.value.trim(),
    validFrom: elements.collectiveAgreementValidFrom.value,
    validTo: elements.collectiveAgreementValidTo.value || null,
    externalPublishedOn: elements.collectiveAgreementPublishedOn.value || null,
    sourceTitle: elements.collectiveAgreementSourceTitle.value.trim(),
    sourceUrl: elements.collectiveAgreementSourceUrl.value.trim(),
    sourceRetrievedOn: elements.collectiveAgreementSourceRetrievedOn.value,
    sourceSha256: elements.collectiveAgreementSourceSha256.value.trim(),
    sourceNote: elements.collectiveAgreementSourceNote.value.trim(),
    contractingParties: elements.collectiveAgreementContractingParties.value,
    territorialScope: elements.collectiveAgreementTerritorialScope.value.trim(),
    functionalScope: elements.collectiveAgreementFunctionalScope.value.trim(),
    personalScope: elements.collectiveAgreementPersonalScope.value.trim(),
    employeeGroups: elements.collectiveAgreementEmployeeGroups.value,
    workTimeParametersNote: elements.collectiveAgreementWorkTimeNote.value.trim(),
    classificationNote: elements.collectiveAgreementClassificationNote.value.trim(),
    apprenticeRelevance: elements.collectiveAgreementApprenticeRelevance.value,
    apprenticeNote: elements.collectiveAgreementApprenticeNote.value.trim(),
    successorNote: elements.collectiveAgreementSuccessorNote.value.trim(),
    linkedProfileVersionId: elements.collectiveAgreementLinkedProfileVersion.value,
  };
}

async function saveCollectiveAgreement(event) {
  event.preventDefault();
  if (!canManageCollectiveAgreements()) return;
  const agreementId = elements.collectiveAgreementId.value;
  const version = collectiveAgreementVersionPayload();
  const body = agreementId ? version : {
    code: elements.collectiveAgreementCode.value.trim(),
    shortTitle: elements.collectiveAgreementShortTitle.value.trim(),
    title: elements.collectiveAgreementTitle.value.trim(),
    jurisdiction: elements.collectiveAgreementJurisdiction.value.trim(),
    note: elements.collectiveAgreementNote.value.trim(),
    version,
  };
  elements.collectiveAgreementSubmitButton.disabled = true;
  try {
    const result = await api(
      agreementId
        ? `/api/collective-agreements/${encodeURIComponent(agreementId)}/versions`
        : "/api/collective-agreements",
      { method: "POST", body: JSON.stringify(body) },
    );
    elements.collectiveAgreementModal.close();
    state.selectedCollectiveAgreementId = result.agreement?.id || agreementId;
    await loadCollectiveAgreementRegistry({ force: true });
    showToast(agreementId ? "Die neue KV-Fassung wurde unveränderlich ergänzt." : "Der KV-Registereintrag wurde angelegt.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.collectiveAgreementSubmitButton.disabled = false;
  }
}

function renderCollectiveAgreementScopeOptions(editingUnit = null) {
  if (!elements.collectiveAgreementBusinessUnitScopeOptions) return;
  const registry = state.collectiveAgreementRegistry || {};
  const owners = new Map((registry.businessUnits || []).flatMap((unit) => (
    unit.scopes.map((scope) => [`${scope.scopeType}:${scope.scopeKey}`, unit])
  )));
  const group = (title, options) => options.length ? `
    <section><strong>${escapeHtml(title)}</strong>${options.map((option) => {
      const key = `${option.scopeType}:${option.scopeKey}`;
      const owner = owners.get(key);
      const belongsToEditingUnit = owner?.id === editingUnit?.id;
      return `<label class="${owner ? "occupied" : ""}"><input type="checkbox" data-business-unit-scope-type="${escapeHtmlAttribute(option.scopeType)}" data-business-unit-scope-key="${escapeHtmlAttribute(String(option.scopeKey))}" ${belongsToEditingUnit ? "checked " : ""}${owner ? "disabled" : ""} /><span>${escapeHtml(option.label)}</span>${owner ? `<small>${belongsToEditingUnit ? "bereits in diesem Betriebsteil" : `bereits bei ${escapeHtml(owner.code)}`}</small>` : ""}</label>`;
    }).join("")}</section>` : "";
  const costCenters = (registry.costCenters || []).map((center) => ({
    scopeType: "cost_center",
    scopeKey: center.id,
    label: `${center.code} · ${center.name}${center.active ? "" : " · inaktiv"}`,
  }));
  const locations = (registry.locations || []).map((location) => ({
    scopeType: "location",
    scopeKey: location.id,
    label: `${location.id} · ${location.name}`,
  }));
  const departments = (registry.locations || []).flatMap((location) => (location.departments || []).map((department) => ({
    scopeType: "department",
    scopeKey: department.id,
    label: `${location.id} · ${location.name} · ${department.name}`,
  })));
  elements.collectiveAgreementBusinessUnitScopeOptions.innerHTML = [
    group("Kostenstellen", costCenters),
    group("Filialen", locations),
    group("Abteilungen", departments),
  ].join("") || '<p class="settings-note">Keine organisatorischen Bereiche verfügbar.</p>';
}

function openCollectiveAgreementBusinessUnitModal(unit = null) {
  if (!canManageCollectiveAgreements() || !elements.collectiveAgreementBusinessUnitModal) return;
  elements.collectiveAgreementBusinessUnitForm.reset();
  state.editingCollectiveAgreementBusinessUnitId = unit?.id || "";
  elements.collectiveAgreementBusinessUnitId.value = unit?.id || "";
  elements.collectiveAgreementBusinessUnitCode.value = unit?.code || "";
  elements.collectiveAgreementBusinessUnitName.value = unit?.name || "";
  elements.collectiveAgreementBusinessUnitLegalEntity.value = unit?.legalEntityName || "";
  elements.collectiveAgreementBusinessUnitDescription.value = unit?.description || "";
  [elements.collectiveAgreementBusinessUnitCode, elements.collectiveAgreementBusinessUnitName,
    elements.collectiveAgreementBusinessUnitLegalEntity, elements.collectiveAgreementBusinessUnitDescription]
    .forEach((input) => { input.disabled = Boolean(unit); });
  elements.collectiveAgreementBusinessUnitModalTitle.textContent = unit ? "Betriebsteil um Bereiche ergänzen" : "Betriebsteil anlegen";
  elements.collectiveAgreementBusinessUnitSubmitButton.textContent = unit ? "Bereiche ergänzen" : "Betriebsteil speichern";
  renderCollectiveAgreementScopeOptions(unit);
  elements.collectiveAgreementBusinessUnitModal.showModal();
}

async function saveCollectiveAgreementBusinessUnit(event) {
  event.preventDefault();
  if (!canManageCollectiveAgreements()) return;
  const businessUnitId = elements.collectiveAgreementBusinessUnitId.value;
  const scopes = [...elements.collectiveAgreementBusinessUnitScopeOptions.querySelectorAll("input:checked:not(:disabled)")]
    .map((input) => ({
      scopeType: input.dataset.businessUnitScopeType,
      scopeKey: input.dataset.businessUnitScopeKey,
    }));
  if (businessUnitId && !scopes.length) {
    showToast("Bitte mindestens einen neuen organisatorischen Bereich auswählen.", true);
    return;
  }
  const body = businessUnitId ? { scopes } : {
    code: elements.collectiveAgreementBusinessUnitCode.value.trim(),
    name: elements.collectiveAgreementBusinessUnitName.value.trim(),
    legalEntityName: elements.collectiveAgreementBusinessUnitLegalEntity.value.trim(),
    description: elements.collectiveAgreementBusinessUnitDescription.value.trim(),
    scopes,
  };
  elements.collectiveAgreementBusinessUnitSubmitButton.disabled = true;
  try {
    await api(
      businessUnitId
        ? `/api/collective-agreements/business-units/${encodeURIComponent(businessUnitId)}/scopes`
        : "/api/collective-agreements/business-units",
      {
      method: "POST",
      body: JSON.stringify(body),
      },
    );
    elements.collectiveAgreementBusinessUnitModal.close();
    await loadCollectiveAgreementRegistry({ force: true });
    showToast(businessUnitId ? "Die Bereiche wurden unveränderlich ergänzt." : "Der Betriebsteil wurde angelegt.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.collectiveAgreementBusinessUnitSubmitButton.disabled = false;
  }
}

function selectedCollectiveAgreementAssignmentVersion() {
  const id = elements.collectiveAgreementAssignmentVersion?.value || "";
  return collectiveAgreementVersionOptions(state.collectiveAgreementRegistry || {})
    .find((version) => version.id === id) || null;
}

function updateCollectiveAgreementAssignmentDates() {
  const version = selectedCollectiveAgreementAssignmentVersion();
  if (!version) return;
  elements.collectiveAgreementAssignmentValidFrom.value = version.validFrom;
  elements.collectiveAgreementAssignmentValidFrom.min = version.validFrom;
  elements.collectiveAgreementAssignmentValidTo.min = version.validFrom;
  elements.collectiveAgreementAssignmentValidFrom.max = version.validTo || "";
  elements.collectiveAgreementAssignmentValidTo.max = version.validTo || "";
  elements.collectiveAgreementAssignmentValidTo.value = version.validTo || "";
}

function openCollectiveAgreementAssignmentModal() {
  if (!canPrepareCollectiveAgreementAssignments() || !elements.collectiveAgreementAssignmentModal) return;
  const registry = state.collectiveAgreementRegistry || {};
  const versions = collectiveAgreementVersionOptions(registry);
  const units = (registry.businessUnits || []).filter((unit) => unit.active);
  if (!versions.length || !units.length) {
    showToast("Für einen Zuordnungsvorschlag werden mindestens eine KV-Fassung und ein Betriebsteil benötigt.", true);
    return;
  }
  elements.collectiveAgreementAssignmentForm.reset();
  elements.collectiveAgreementAssignmentVersion.innerHTML = versions.map((version) => `
    <option value="${escapeHtmlAttribute(version.id)}">${escapeHtml(`${version.agreement.code} · ${version.versionLabel} · ${collectiveAgreementValidity(version.validFrom, version.validTo)}`)}</option>
  `).join("");
  const selectedAgreement = (registry.agreements || []).find((agreement) => agreement.id === state.selectedCollectiveAgreementId);
  if (selectedAgreement?.currentVersionId) elements.collectiveAgreementAssignmentVersion.value = selectedAgreement.currentVersionId;
  elements.collectiveAgreementAssignmentBusinessUnit.innerHTML = units.map((unit) => `
    <option value="${escapeHtmlAttribute(unit.id)}">${escapeHtml(`${unit.code} · ${unit.name}`)}</option>
  `).join("");
  updateCollectiveAgreementAssignmentDates();
  elements.collectiveAgreementAssignmentModal.showModal();
}

async function saveCollectiveAgreementAssignment(event) {
  event.preventDefault();
  if (!canPrepareCollectiveAgreementAssignments()) return;
  const body = {
    agreementVersionId: elements.collectiveAgreementAssignmentVersion.value,
    businessUnitId: elements.collectiveAgreementAssignmentBusinessUnit.value,
    validFrom: elements.collectiveAgreementAssignmentValidFrom.value,
    validTo: elements.collectiveAgreementAssignmentValidTo.value || null,
    rationale: elements.collectiveAgreementAssignmentRationale.value.trim(),
    referenceNote: elements.collectiveAgreementAssignmentReference.value.trim(),
    reviewState: "review_pending",
  };
  elements.collectiveAgreementAssignmentSubmitButton.disabled = true;
  try {
    await api("/api/collective-agreements/assignments", {
      method: "POST",
      body: JSON.stringify(body),
    });
    elements.collectiveAgreementAssignmentModal.close();
    await loadCollectiveAgreementRegistry({ force: true });
    showToast("Der Zuordnungsvorschlag wurde mit Status „Prüfung offen“ gespeichert.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.collectiveAgreementAssignmentSubmitButton.disabled = false;
  }
}

const PERSONNEL_CANDIDATE_STATUS_LABELS = Object.freeze({
  new: "Neu",
  screening: "Vorauswahl",
  first_interview: "Erstgespräch",
  further_interview: "Weiteres Gespräch",
  offer: "Angebot",
  accepted: "Angenommen",
  preboarding: "Preboarding",
  converted: "Eingestellt",
  rejected: "Abgelehnt",
  withdrawn: "Zurückgezogen",
  talent_pool: "Talentpool",
  archived: "Archiviert",
});

const PERSONNEL_CANDIDATE_STATUS_TRANSITIONS = Object.freeze({
  new: Object.freeze(["screening", "rejected", "withdrawn", "talent_pool", "archived"]),
  screening: Object.freeze(["first_interview", "rejected", "withdrawn", "talent_pool", "archived"]),
  first_interview: Object.freeze(["further_interview", "offer", "rejected", "withdrawn", "talent_pool", "archived"]),
  further_interview: Object.freeze(["offer", "rejected", "withdrawn", "talent_pool", "archived"]),
  offer: Object.freeze(["accepted", "rejected", "withdrawn", "archived"]),
  accepted: Object.freeze(["preboarding", "withdrawn", "archived"]),
  preboarding: Object.freeze(["withdrawn", "archived"]),
  converted: Object.freeze([]),
  rejected: Object.freeze(["talent_pool", "archived"]),
  withdrawn: Object.freeze(["talent_pool", "archived"]),
  talent_pool: Object.freeze(["archived"]),
  archived: Object.freeze([]),
});

const PERSONNEL_CANDIDATE_REASON_STATUSES = Object.freeze(new Set([
  "rejected",
  "withdrawn",
  "talent_pool",
  "archived",
]));

function defaultPersonnelCandidateCapabilities() {
  return {
    scope: null,
    canReadCandidates: false,
    canWriteCandidates: false,
    canWriteApplications: false,
    canReadConfidential: false,
    canWriteConfidential: false,
    canConvert: false,
  };
}

function normalizePersonnelCandidateCapabilities(value) {
  const submitted = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    scope: submitted.scope && typeof submitted.scope === "object" ? submitted.scope : null,
    canReadCandidates: submitted.canReadCandidates === true,
    canWriteCandidates: submitted.canWriteCandidates === true,
    canWriteApplications: submitted.canWriteApplications === true,
    canReadConfidential: submitted.canReadConfidential === true,
    canWriteConfidential: submitted.canWriteConfidential === true,
    canConvert: submitted.canConvert === true,
  };
}

function applyPersonnelCandidateCapabilities(payload) {
  if (!payload || typeof payload.capabilities !== "object" || Array.isArray(payload.capabilities)) {
    return state.personnelCandidateCapabilities;
  }
  state.personnelCandidateCapabilities = normalizePersonnelCandidateCapabilities(payload.capabilities);
  return state.personnelCandidateCapabilities;
}

function personnelCandidateScopeLabel(scope) {
  if (!scope || typeof scope !== "object") return "Freigegebener Bereich";
  const suppliedLabel = String(scope.label || scope.name || "").trim();
  if (suppliedLabel) return suppliedLabel;
  const kind = String(scope.type || scope.kind || scope.scopeType || "").toLowerCase();
  if (["all", "global", "company", "company_wide"].includes(kind)) return "Unternehmensweit freigegeben";
  const locationCount = Array.isArray(scope.locationIds)
    ? scope.locationIds.length
    : (scope.locationId ? 1 : 0);
  const departmentCount = Array.isArray(scope.departmentIds)
    ? scope.departmentIds.length
    : (scope.departmentId ? 1 : 0);
  if (locationCount && departmentCount) return `${locationCount} Standort(e) · ${departmentCount} Abteilung(en)`;
  if (departmentCount) return `${departmentCount} Abteilung(en) freigegeben`;
  if (locationCount) return `${locationCount} Standort(e) freigegeben`;
  return "Freigegebener Bereich";
}

function personnelCandidateProfile(candidate) {
  return candidate?.profile && typeof candidate.profile === "object" && !Array.isArray(candidate.profile)
    ? candidate.profile
    : {};
}

function personnelCandidateName(candidate) {
  const profile = personnelCandidateProfile(candidate);
  const firstName = String(profile.firstName || candidate?.firstName || "").trim();
  const lastName = String(profile.lastName || candidate?.lastName || "").trim();
  return [firstName, lastName].filter(Boolean).join(" ") || "Bewerbung ohne Namensangabe";
}

function personnelCandidateApplications(candidate) {
  return Array.isArray(candidate?.applications) ? candidate.applications.filter((entry) => (
    entry && typeof entry === "object" && typeof entry.id === "string"
  )) : [];
}

function personnelCandidatePrimaryApplication(candidate, preferredStatus = "") {
  const applications = personnelCandidateApplications(candidate);
  if (preferredStatus) {
    const matching = applications.find((entry) => entry.status === preferredStatus);
    if (matching) return matching;
  }
  return [...applications].sort((left, right) => (
    String(right.updatedAt || right.statusChangedAt || right.createdAt || "")
      .localeCompare(String(left.updatedAt || left.statusChangedAt || left.createdAt || ""))
  ))[0] || null;
}

function personnelCandidateOrganization(application) {
  if (!application) return "Noch keine Stelle zugeordnet";
  const role = String(application.desiredRoleTitle || application.positionName || "").trim();
  const location = String(application.desiredLocationName || application.locationName || application.desiredLocationId || "").trim();
  const department = String(application.desiredDepartmentName || application.departmentName || application.desiredDepartmentId || "").trim();
  return [role, location, department].filter(Boolean).join(" · ") || "Noch keine Stelle zugeordnet";
}

function formatPersonnelCandidateTimestamp(value, fallback = "Nicht angegeben") {
  const parsed = new Date(String(value || ""));
  if (!Number.isFinite(parsed.getTime())) return fallback;
  try {
    return new Intl.DateTimeFormat("de-AT", { dateStyle: "short", timeStyle: "short" }).format(parsed);
  } catch {
    return fallback;
  }
}

function personnelCandidateStatusLabel(status) {
  return PERSONNEL_CANDIDATE_STATUS_LABELS[status] || "Status nicht angegeben";
}

function personnelCandidateStatusClass(status) {
  return Object.hasOwn(PERSONNEL_CANDIDATE_STATUS_LABELS, status)
    ? ` status-${status.replaceAll("_", "-")}`
    : "";
}

function filteredPersonnelCandidates() {
  const query = state.personnelCandidateSearch.trim().toLocaleLowerCase("de-AT");
  const status = state.personnelCandidateStatusFilter;
  return state.personnelCandidates.filter((candidate) => {
    const applications = personnelCandidateApplications(candidate);
    if (status && !applications.some((entry) => entry.status === status)) return false;
    if (!query) return true;
    const profile = personnelCandidateProfile(candidate);
    const searchable = [
      personnelCandidateName(candidate),
      ...applications.flatMap((entry) => [
        entry.status,
        personnelCandidateStatusLabel(entry.status),
        entry.desiredRoleTitle,
        entry.positionName,
        entry.desiredLocationName,
        entry.locationName,
        entry.desiredLocationId,
        entry.desiredDepartmentName,
        entry.departmentName,
        entry.desiredDepartmentId,
      ]),
      profile.email,
    ].filter(Boolean).join(" ").toLocaleLowerCase("de-AT");
    return searchable.includes(query);
  });
}

function clearPersonnelLifecycleCandidateState(message = "") {
  state.personnelCandidates = [];
  state.personnelCandidateCapabilities = defaultPersonnelCandidateCapabilities();
  state.personnelCandidatePagination = { limit: 50, offset: 0, count: 0, total: null };
  state.personnelCandidatesLoaded = false;
  state.personnelCandidatesLoading = false;
  state.selectedPersonnelCandidateId = "";
  state.selectedPersonnelCandidate = null;
  state.personnelCandidateDetailLoading = false;
  state.personnelCandidateMutationPending = "";
  state.personnelCandidateLoadError = message;
  state.personnelCandidateDetailError = "";
  renderPersonnelCandidateOverview();
}

function renderPersonnelCandidateList() {
  if (!elements.personnelCandidateList || !elements.personnelCandidateCount) return;
  if (state.personnelCandidatesLoading) {
    elements.personnelCandidateCount.textContent = "Bewerbungen werden geladen";
    elements.personnelCandidateList.innerHTML = '<p class="personnel-candidate-empty">Die freigegebene Liste wird geladen …</p>';
    return;
  }
  if (state.personnelCandidateLoadError) {
    elements.personnelCandidateCount.textContent = "Liste nicht verfügbar";
    elements.personnelCandidateList.innerHTML = `<div class="personnel-candidate-empty error"><strong>Liste konnte nicht geladen werden</strong><p>${escapeHtml(state.personnelCandidateLoadError)}</p></div>`;
    return;
  }
  if (!state.personnelCandidatesLoaded) {
    elements.personnelCandidateCount.textContent = "0 Bewerbungen";
    elements.personnelCandidateList.innerHTML = '<p class="personnel-candidate-empty">Noch keine Liste geladen.</p>';
    return;
  }
  const candidates = filteredPersonnelCandidates();
  elements.personnelCandidateCount.textContent = `${candidates.length} ${candidates.length === 1 ? "Bewerbung" : "Bewerbungen"}`;
  if (!candidates.length) {
    const filtered = Boolean(state.personnelCandidateSearch.trim() || state.personnelCandidateStatusFilter);
    elements.personnelCandidateList.innerHTML = `<div class="personnel-candidate-empty"><strong>${filtered ? "Keine passenden Bewerbungen" : "Keine Bewerbungen vorhanden"}</strong><p>${filtered ? "Bitte Suche oder Statusfilter anpassen." : "Im freigegebenen Bereich sind derzeit keine Bewerbungen sichtbar."}</p></div>`;
    return;
  }
  elements.personnelCandidateList.innerHTML = candidates.map((candidate) => {
    const application = personnelCandidatePrimaryApplication(candidate, state.personnelCandidateStatusFilter);
    const status = application?.status || "";
    const selected = candidate.id === state.selectedPersonnelCandidateId;
    return `<button class="personnel-candidate-list-item${selected ? " active" : ""}" type="button" data-personnel-candidate-id="${escapeHtmlAttribute(candidate.id)}" aria-pressed="${String(selected)}">
      <span class="personnel-candidate-list-title"><strong>${escapeHtml(personnelCandidateName(candidate))}</strong><span class="personnel-candidate-status-badge${personnelCandidateStatusClass(status)}">${escapeHtml(personnelCandidateStatusLabel(status))}</span></span>
      <span>${escapeHtml(personnelCandidateOrganization(application))}</span>
      <small>Aktualisiert: ${escapeHtml(formatPersonnelCandidateTimestamp(application?.updatedAt || candidate.updatedAt))}</small>
    </button>`;
  }).join("");
}

function personnelCandidateFact(label, value) {
  return `<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value || "Nicht angegeben"))}</strong></div>`;
}

function renderPersonnelCandidateStatusForm(candidateId, application) {
  const transitions = PERSONNEL_CANDIDATE_STATUS_TRANSITIONS[application.status] || [];
  if (!state.personnelCandidateCapabilities.canWriteApplications || !transitions.length) return "";
  const pending = state.personnelCandidateMutationPending === application.id;
  return `<form class="personnel-candidate-status-form" data-personnel-candidate-status-form data-candidate-id="${escapeHtmlAttribute(candidateId)}" data-application-id="${escapeHtmlAttribute(application.id)}">
    <label class="field"><span>Nächster Status</span><select name="status" required ${pending ? "disabled" : ""}>
      <option value="">Bitte auswählen</option>
      ${transitions.map((status) => `<option value="${escapeHtmlAttribute(status)}">${escapeHtml(personnelCandidateStatusLabel(status))}</option>`).join("")}
    </select></label>
    <label class="field personnel-candidate-reason hidden"><span>Begründung</span><input name="reason" type="text" maxlength="500" autocomplete="off" placeholder="Kurze nachvollziehbare Begründung" ${pending ? "disabled" : ""} /></label>
    <button class="primary-button" type="submit" ${pending ? "disabled" : ""}>${pending ? "Wird gespeichert …" : "Status übernehmen"}</button>
  </form>`;
}

function renderPersonnelCandidateApplication(candidateId, application) {
  const weeklyMinutes = Number(application.desiredWeeklyMinutes);
  const weeklyHours = Number.isFinite(weeklyMinutes) && weeklyMinutes > 0
    ? `${(weeklyMinutes / 60).toLocaleString("de-AT", { maximumFractionDigits: 2 })} Std.`
    : "Nicht angegeben";
  return `<article class="personnel-candidate-application">
    <header><div><span class="eyebrow">Bewerbung</span><h4>${escapeHtml(application.desiredRoleTitle || application.positionName || "Stelle nicht angegeben")}</h4></div><span class="personnel-candidate-status-badge${personnelCandidateStatusClass(application.status)}">${escapeHtml(personnelCandidateStatusLabel(application.status))}</span></header>
    <div class="personnel-candidate-facts">
      ${personnelCandidateFact("Standort", application.desiredLocationName || application.locationName || application.desiredLocationId)}
      ${personnelCandidateFact("Abteilung", application.desiredDepartmentName || application.departmentName || application.desiredDepartmentId)}
      ${personnelCandidateFact("Verfügbar ab", application.availableFrom ? formatDate(String(application.availableFrom).slice(0, 10)) : "Nicht angegeben")}
      ${personnelCandidateFact("Wochenumfang", weeklyHours)}
      ${personnelCandidateFact("Beschäftigungsart", application.employmentType)}
      ${personnelCandidateFact("Stand", formatPersonnelCandidateTimestamp(application.updatedAt || application.statusChangedAt))}
    </div>
    ${renderPersonnelCandidateStatusForm(candidateId, application)}
  </article>`;
}

function renderPersonnelCandidateDetail() {
  if (!elements.personnelCandidateDetail) return;
  if (state.personnelCandidateDetailLoading) {
    elements.personnelCandidateDetail.innerHTML = '<div class="personnel-candidate-empty"><strong>Details werden geladen</strong><p>Die freigegebenen Bewerbungsdaten werden abgerufen.</p></div>';
    return;
  }
  if (state.personnelCandidateDetailError && !state.selectedPersonnelCandidate) {
    elements.personnelCandidateDetail.innerHTML = `<div class="personnel-candidate-empty error"><strong>Details konnten nicht geladen werden</strong><p>${escapeHtml(state.personnelCandidateDetailError)}</p></div>`;
    return;
  }
  const candidate = state.selectedPersonnelCandidate;
  if (!candidate) {
    elements.personnelCandidateDetail.innerHTML = '<div class="personnel-candidate-empty"><strong>Details auswählen</strong><p>Wähle links eine Bewerbung. Vertrauliche Felder werden in dieser kompakten Ansicht nicht dargestellt.</p></div>';
    return;
  }
  const profile = personnelCandidateProfile(candidate);
  const applications = personnelCandidateApplications(candidate);
  elements.personnelCandidateDetail.innerHTML = `<div class="personnel-candidate-detail-heading">
      <div><span class="eyebrow">Bewerberprofil</span><h3>${escapeHtml(personnelCandidateName(candidate))}</h3><p>Getrennte Bewerberentität ohne Personalnummer.</p></div>
      <span class="personnel-candidate-status-badge${candidate.state === "archived" ? " status-archived" : ""}">${candidate.state === "archived" ? "Archiviert" : "Aktiv"}</span>
    </div>
    ${state.personnelCandidateDetailError ? `<p class="personnel-candidate-inline-error">${escapeHtml(state.personnelCandidateDetailError)}</p>` : ""}
    <div class="personnel-candidate-facts personnel-candidate-contact-facts">
      ${personnelCandidateFact("E-Mail", profile.email)}
      ${personnelCandidateFact("Telefon", profile.phone)}
      ${personnelCandidateFact("Bewerbungen", String(applications.length))}
      ${personnelCandidateFact("Zuletzt aktualisiert", formatPersonnelCandidateTimestamp(candidate.updatedAt))}
    </div>
    <div class="personnel-candidate-privacy-note"><strong>Datensparsame Ansicht</strong><p>Es werden ausschließlich Kontaktdaten und freigegebene Bewerbungsangaben dargestellt. Vertrauliche Bewertungs- und Verlaufsdaten bleiben ausgeblendet.</p></div>
    <div class="personnel-candidate-applications">
      ${applications.length
        ? applications.map((application) => renderPersonnelCandidateApplication(candidate.id, application)).join("")
        : '<div class="personnel-candidate-empty"><strong>Keine Bewerbung zugeordnet</strong><p>Für dieses Bewerberprofil ist keine Bewerbung sichtbar.</p></div>'}
    </div>`;
}

function renderPersonnelCandidateOverview() {
  const capabilities = state.personnelCandidateCapabilities;
  if (elements.personnelCandidateScopeBadge) {
    const capabilityKnown = state.personnelCandidatesLoaded || state.personnelCandidatesLoading || Boolean(state.personnelCandidateLoadError);
    elements.personnelCandidateScopeBadge.textContent = capabilityKnown && capabilities.canReadCandidates
      ? personnelCandidateScopeLabel(capabilities.scope)
      : (state.personnelCandidatesLoading ? "Bereich wird geladen" : "Zugriff wird geprüft");
    elements.personnelCandidateScopeBadge.classList.toggle("inactive", !capabilities.canReadCandidates);
  }
  if (elements.refreshPersonnelCandidatesButton) {
    elements.refreshPersonnelCandidatesButton.disabled = state.personnelCandidatesLoading || !canReadCandidatePreboarding();
  }
  if (elements.personnelCandidateSearch) elements.personnelCandidateSearch.value = state.personnelCandidateSearch;
  if (elements.personnelCandidateStatusFilter) elements.personnelCandidateStatusFilter.value = state.personnelCandidateStatusFilter;
  if (elements.personnelCandidateStatus) {
    const visibleCount = filteredPersonnelCandidates().length;
    elements.personnelCandidateStatus.textContent = state.personnelCandidatesLoading
      ? "Bewerbungen werden geladen."
      : state.personnelCandidateLoadError
        ? state.personnelCandidateLoadError
        : state.personnelCandidatesLoaded
          ? `${visibleCount} von ${state.personnelCandidates.length} freigegebenen Bewerbungen sichtbar. Vertrauliche Felder bleiben ausgeblendet.`
          : "Bewerbungen werden beim Öffnen geladen.";
  }
  renderPersonnelCandidateList();
  renderPersonnelCandidateDetail();
}

async function loadPersonnelCandidates({ force = false } = {}) {
  if (!canReadCandidatePreboarding() || state.personnelCandidatesLoading) return;
  if (state.personnelCandidatesLoaded && !force) {
    renderPersonnelCandidateOverview();
    return;
  }
  state.personnelCandidatesLoading = true;
  state.personnelCandidateLoadError = "";
  renderPersonnelCandidateOverview();
  try {
    const result = await api("/api/portal/v1/personnel-lifecycle/candidates?limit=50&offset=0");
    if (!canReadCandidatePreboarding()) {
      clearPersonnelLifecycleCandidateState("Der Bewerberzugriff wurde während des Ladens entzogen.");
      return;
    }
    const capabilities = applyPersonnelCandidateCapabilities(result);
    if (!capabilities.canReadCandidates) {
      clearPersonnelLifecycleCandidateState("Der Server hat keinen Lesezugriff auf Bewerbungen freigegeben.");
      return;
    }
    state.personnelCandidates = Array.isArray(result?.candidates)
      ? result.candidates.filter((candidate) => candidate && typeof candidate.id === "string")
      : [];
    const pagination = result?.pagination && typeof result.pagination === "object" ? result.pagination : {};
    state.personnelCandidatePagination = {
      limit: Number.isInteger(pagination.limit) ? pagination.limit : 50,
      offset: Number.isInteger(pagination.offset) ? pagination.offset : 0,
      count: state.personnelCandidates.length,
      total: Number.isInteger(pagination.total) ? pagination.total : null,
    };
    state.personnelCandidatesLoaded = true;
    if (state.selectedPersonnelCandidateId
      && !state.personnelCandidates.some((candidate) => candidate.id === state.selectedPersonnelCandidateId)) {
      state.selectedPersonnelCandidateId = "";
      state.selectedPersonnelCandidate = null;
      state.personnelCandidateDetailError = "";
    }
  } catch (error) {
    if ([401, 403].includes(error.status)) {
      clearPersonnelLifecycleCandidateState("Der Bewerberzugriff ist nicht mehr verfügbar.");
      return;
    }
    state.personnelCandidates = [];
    state.personnelCandidatesLoaded = false;
    state.personnelCandidateLoadError = error.message || "Die Bewerbungen konnten nicht geladen werden.";
  } finally {
    state.personnelCandidatesLoading = false;
    renderPersonnelCandidateOverview();
  }
}

async function loadPersonnelCandidateDetail(candidateId) {
  const id = String(candidateId || "").trim();
  if (!id || !canReadCandidatePreboarding() || !state.personnelCandidateCapabilities.canReadCandidates) return;
  state.selectedPersonnelCandidateId = id;
  state.selectedPersonnelCandidate = null;
  state.personnelCandidateDetailError = "";
  state.personnelCandidateDetailLoading = true;
  renderPersonnelCandidateOverview();
  try {
    const result = await api(`/api/portal/v1/personnel-lifecycle/candidates/${encodeURIComponent(id)}`);
    if (state.selectedPersonnelCandidateId !== id) return;
    if (!canReadCandidatePreboarding()) {
      clearPersonnelLifecycleCandidateState("Der Bewerberzugriff wurde während des Ladens entzogen.");
      return;
    }
    const capabilities = applyPersonnelCandidateCapabilities(result);
    if (!capabilities.canReadCandidates) {
      clearPersonnelLifecycleCandidateState("Der Server hat keinen Lesezugriff auf diese Bewerbung freigegeben.");
      return;
    }
    const candidate = result?.candidate;
    if (!candidate || candidate.id !== id) throw new Error("Die Bewerbungsdetails sind unvollständig.");
    state.selectedPersonnelCandidate = candidate;
  } catch (error) {
    if ([401, 403].includes(error.status)) {
      clearPersonnelLifecycleCandidateState("Der Bewerberzugriff ist nicht mehr verfügbar.");
      return;
    }
    if (state.selectedPersonnelCandidateId === id) {
      state.personnelCandidateDetailError = error.message || "Die Bewerbungsdetails konnten nicht geladen werden.";
    }
  } finally {
    if (state.selectedPersonnelCandidateId === id) state.personnelCandidateDetailLoading = false;
    renderPersonnelCandidateOverview();
  }
}

function updatePersonnelCandidateReasonField(form) {
  const status = form?.elements?.status?.value || "";
  const reasonField = form?.querySelector(".personnel-candidate-reason");
  const reasonInput = form?.elements?.reason;
  const required = PERSONNEL_CANDIDATE_REASON_STATUSES.has(status);
  reasonField?.classList.toggle("hidden", !required);
  if (reasonInput) {
    reasonInput.required = required;
    if (!required) reasonInput.value = "";
  }
}

async function savePersonnelCandidateApplicationStatus(event) {
  event.preventDefault();
  const form = event.target.closest("[data-personnel-candidate-status-form]");
  if (!form || !state.personnelCandidateCapabilities.canWriteApplications) return;
  const candidateId = form.dataset.candidateId || "";
  const applicationId = form.dataset.applicationId || "";
  const candidate = state.selectedPersonnelCandidate;
  const application = personnelCandidateApplications(candidate).find((entry) => (
    entry.id === applicationId && candidate?.id === candidateId
  ));
  const status = form.elements.status.value;
  const allowedTransitions = PERSONNEL_CANDIDATE_STATUS_TRANSITIONS[application?.status] || [];
  if (!application || !allowedTransitions.includes(status)) {
    state.personnelCandidateDetailError = "Der gewählte Statuswechsel ist nicht mehr verfügbar. Bitte Details aktualisieren.";
    renderPersonnelCandidateDetail();
    return;
  }
  const reason = String(form.elements.reason?.value || "").trim();
  if (PERSONNEL_CANDIDATE_REASON_STATUSES.has(status) && !reason) {
    form.elements.reason?.focus();
    return;
  }
  state.personnelCandidateMutationPending = applicationId;
  state.personnelCandidateDetailError = "";
  renderPersonnelCandidateDetail();
  try {
    await api(`/api/portal/v1/personnel-lifecycle/candidates/${encodeURIComponent(candidateId)}/applications/${encodeURIComponent(applicationId)}/status`, {
      method: "POST",
      body: JSON.stringify({ status, ...(reason ? { reason } : {}), revision: application.revision }),
    });
    await loadPersonnelCandidates({ force: true });
    await loadPersonnelCandidateDetail(candidateId);
    showToast("Der Bewerbungsstatus wurde aktualisiert.");
  } catch (error) {
    if ([401, 403].includes(error.status)) {
      clearPersonnelLifecycleCandidateState("Der Bewerberzugriff ist nicht mehr verfügbar.");
      return;
    }
    state.personnelCandidateDetailError = error.message || "Der Bewerbungsstatus konnte nicht aktualisiert werden.";
    if (error.status === 409) {
      await loadPersonnelCandidates({ force: true });
      await loadPersonnelCandidateDetail(candidateId);
    }
  } finally {
    state.personnelCandidateMutationPending = "";
    renderPersonnelCandidateOverview();
  }
}

const PERSONNEL_WORKFLOW_TYPE_LABELS = Object.freeze({
  application: "Bewerbung",
  preboarding: "Preboarding",
  training: "Schulung",
  position_change: "Positionswechsel",
  department_change: "Abteilungswechsel",
  location_change: "Standortwechsel",
  return_from_absence: "Rückkehr",
  custom_personnel: "Personalprozess",
});

const PERSONNEL_WORKFLOW_STATUS_LABELS = Object.freeze({
  open: "Offen",
  resolved: "Abgeschlossen",
});

const PERSONNEL_WORKFLOW_TASK_STATUS_LABELS = Object.freeze({
  pending: "Ausstehend",
  active: "Aktiv",
  completed: "Erledigt",
  skipped: "Übersprungen",
});

function defaultPersonnelWorkflowInstanceCapabilities() {
  return { scope: null, canRead: null };
}

function normalizePersonnelWorkflowInstanceCapabilities(value) {
  const submitted = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const scope = submitted.scope && typeof submitted.scope === "object" && !Array.isArray(submitted.scope)
    ? { type: String(submitted.scope.type || "none") }
    : null;
  return {
    scope,
    canRead: submitted.canReadInstances === true,
  };
}

function applyPersonnelWorkflowInstanceCapabilities(payload) {
  state.personnelWorkflowInstanceCapabilities = normalizePersonnelWorkflowInstanceCapabilities(
    payload?.capabilities,
  );
  return state.personnelWorkflowInstanceCapabilities;
}

function personnelWorkflowObject(value) {
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function personnelWorkflowText(...values) {
  for (const value of values) {
    const normalized = String(value ?? "").trim();
    if (normalized) return normalized;
  }
  return "";
}

function normalizePersonnelWorkflowStatus(value) {
  const status = personnelWorkflowText(value).toLowerCase();
  return Object.hasOwn(PERSONNEL_WORKFLOW_STATUS_LABELS, status) ? status : "";
}

function personnelWorkflowScopeLabel(value, fallback = "Freigegebener Bereich") {
  const scope = personnelWorkflowObject(value);
  const type = personnelWorkflowText(scope.type).toLowerCase();
  if (type === "company") return "Unternehmensweit";
  if (type === "department") return "Freigegebener Abteilungsbereich";
  if (type === "location") return "Freigegebener Standortbereich";
  return fallback;
}

function normalizePersonnelWorkflowTask(value, workflowTitle = "Personalprozess") {
  const task = personnelWorkflowObject(value);
  return {
    title: personnelWorkflowText(task.title, "Aufgabenschritt"),
    workflowTitle: personnelWorkflowText(workflowTitle, "Personalprozess"),
    status: "active",
  };
}

function normalizePersonnelLifecycleOnboardingTaskCapabilities(value) {
  const capabilities = personnelWorkflowObject(value);
  return {
    canRead: capabilities.canReadOnboardingTasks === true,
    canComplete: capabilities.canCompleteOnboardingTasks === true,
  };
}

function requiredPersonnelLifecycleOnboardingTaskText(value, label, maximum = 160) {
  const normalized = String(value ?? "").trim();
  if (!normalized || normalized.length > maximum || /[\0\r\n]/.test(normalized)) {
    throw new Error(`${label} ist ungültig.`);
  }
  return normalized;
}

function normalizePersonnelLifecycleOnboardingTask(value) {
  const task = personnelWorkflowObject(value);
  const step = personnelWorkflowObject(task.step);
  const subject = personnelWorkflowObject(task.subject);
  const scope = personnelWorkflowObject(task.scope);
  const scopeType = String(scope.type || "").trim();
  const locationId = String(scope.locationId || "").trim();
  const departmentId = scope.departmentId === null ? null : Number(scope.departmentId);
  const position = Number(step.position);
  const activatedAt = requiredPersonnelLifecycleOnboardingTaskText(
    step.activatedAt,
    "Der Aktivierungszeitpunkt",
    40,
  );
  if (!["location", "department"].includes(scopeType)
    || !locationId || locationId.length > 80 || locationId.includes("\0")
    || (scopeType === "location" && departmentId !== null)
    || (scopeType === "department"
      && (!Number.isSafeInteger(departmentId) || departmentId < 1))
    || !Number.isSafeInteger(position) || position < 1
    || Number.isNaN(new Date(activatedAt).getTime())) {
    throw new Error("Eine Lifecycle-Onboarding-Aufgabe ist unvollständig.");
  }
  return {
    caseId: requiredPersonnelLifecycleOnboardingTaskText(task.caseId, "Der Fallbezug", 120),
    runId: requiredPersonnelLifecycleOnboardingTaskText(task.runId, "Der Instanzbezug", 120),
    stepId: requiredPersonnelLifecycleOnboardingTaskText(task.stepId, "Der Schrittbezug", 120),
    workflowCode: requiredPersonnelLifecycleOnboardingTaskText(task.workflowCode, "Der Workflow-Code", 120),
    workflowTitle: requiredPersonnelLifecycleOnboardingTaskText(task.workflowTitle, "Der Workflow-Titel", 200),
    title: requiredPersonnelLifecycleOnboardingTaskText(step.title, "Der Aufgabentitel", 200),
    subject: {
      displayName: requiredPersonnelLifecycleOnboardingTaskText(
        subject.displayName,
        "Der Name der zugeordneten Person",
        200,
      ),
      employeeNumber: requiredPersonnelLifecycleOnboardingTaskText(
        subject.employeeNumber,
        "Die Personalnummer der zugeordneten Person",
        120,
      ),
    },
    position,
    activatedAt,
    scope: { type: scopeType, locationId, departmentId },
  };
}

function personnelLifecycleOnboardingTaskKey(task) {
  return `${task.runId}\0${task.stepId}`;
}

const PERSONNEL_LIFECYCLE_OFFBOARDING_TASK_FIELDS = Object.freeze({
  leadership_task: Object.freeze([
    "displayName",
    "employeeNumber",
    "locationId",
    "departmentId",
    "dueAt",
  ]),
  it_security_task: Object.freeze([
    "businessIdentifier",
    "targetSystem",
    "action",
    "executeAt",
  ]),
  asset_task: Object.freeze(["assetIdentifier", "dueAt"]),
  payroll_task: Object.freeze([
    "displayName",
    "employeeNumber",
    "payrollAction",
    "effectiveDate",
    "dueAt",
  ]),
});

function normalizePersonnelLifecycleOffboardingTaskCapabilities(value) {
  const capabilities = personnelWorkflowObject(value);
  return {
    canRead: capabilities.canReadOffboardingTasks === true,
    canComplete: capabilities.canCompleteOffboardingTasks === true,
  };
}

function normalizePersonnelLifecycleOffboardingTask(value) {
  const task = personnelWorkflowObject(value);
  const projection = requiredPersonnelLifecycleOnboardingTaskText(
    task.projection,
    "Die Aufgabenprojektion",
    80,
  );
  const allowedFields = PERSONNEL_LIFECYCLE_OFFBOARDING_TASK_FIELDS[projection];
  const status = String(task.status || "").trim();
  if (!allowedFields || !["pending", "active"].includes(status)) {
    throw new Error("Eine Lifecycle-Offboarding-Aufgabe ist unvollständig.");
  }
  const normalized = {
    runId: requiredPersonnelLifecycleOnboardingTaskText(
      task.runId,
      "Der Instanzbezug",
      120,
    ),
    stepId: requiredPersonnelLifecycleOnboardingTaskText(
      task.stepId,
      "Der Schrittbezug",
      120,
    ),
    orderId: requiredPersonnelLifecycleOnboardingTaskText(
      task.orderId,
      "Der Auftragsbezug",
      120,
    ),
    projection,
    title: requiredPersonnelLifecycleOnboardingTaskText(
      task.title,
      "Der Aufgabentitel",
      200,
    ),
    status,
  };
  for (const field of allowedFields) {
    const submitted = task[field];
    if (submitted === null || submitted === undefined || submitted === "") continue;
    if (typeof submitted === "object" || /[\0\r\n]/.test(String(submitted))) {
      throw new Error("Eine Lifecycle-Offboarding-Aufgabe enthält ungültige Projektionsdaten.");
    }
    normalized[field] = String(submitted).trim().slice(0, 200);
  }
  return normalized;
}

function personnelLifecycleOffboardingTaskKey(task) {
  return `${task.runId}\0${task.stepId}`;
}

