async function submitPersonnelLifecycleOffboardingTaskCompletion(event) {
  const form = event.target.closest("[data-personnel-lifecycle-offboarding-task-complete]");
  if (!form) return false;
  event.preventDefault();
  if (state.personnelLifecycleOffboardingTaskPending
    || state.personnelLifecycleOffboardingTaskCapabilities.canComplete !== true
    || (typeof form.reportValidity === "function" && !form.reportValidity())) return true;
  const runId = String(form.dataset.runId || "").trim();
  const stepId = String(form.dataset.stepId || "").trim();
  const task = state.personnelLifecycleOffboardingTasks.find((entry) => (
    entry.runId === runId && entry.stepId === stepId && entry.status === "active"
  ));
  if (!task || form.querySelector("[data-offboarding-task-confirm]")?.checked !== true) return true;
  const key = personnelLifecycleOffboardingTaskKey(task);
  let operationId = state.personnelLifecycleOffboardingTaskOperations[key];
  if (!operationId) {
    operationId = globalThis.crypto?.randomUUID?.();
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(operationId || ""))) {
      showToast("Die sichere Vorgangs-ID konnte nicht erzeugt werden.", true);
      return true;
    }
    state.personnelLifecycleOffboardingTaskOperations[key] = operationId.toLowerCase();
  }
  state.personnelLifecycleOffboardingTaskPending = key;
  renderPersonnelWorkflowInstanceOverview();
  try {
    await api(`/api/portal/v1/personnel-lifecycle/offboarding/tasks/${encodeURIComponent(runId)}/${encodeURIComponent(stepId)}/completions`, {
      method: "POST",
      body: JSON.stringify({
        operationId: state.personnelLifecycleOffboardingTaskOperations[key],
        action: "complete",
        evidenceReference: null,
      }),
    });
    delete state.personnelLifecycleOffboardingTaskOperations[key];
    state.personnelLifecycleOffboardingTaskPending = "";
    await loadPersonnelLifecycleOffboardingTasks({ force: true });
    showToast("Der Offboarding-Auftrag wurde nachvollziehbar als erledigt bestätigt.");
  } catch (error) {
    state.personnelLifecycleOffboardingTaskPending = "";
    if ([403, 404, 409].includes(error.status)) {
      delete state.personnelLifecycleOffboardingTaskOperations[key];
      showToast(error.message, true);
      await loadPersonnelLifecycleOffboardingTasks({ force: true });
      return true;
    }
    state.personnelLifecycleOffboardingTasksError = error.message
      || "Die Erledigung konnte nicht sicher bestätigt werden.";
    renderPersonnelWorkflowInstanceOverview();
  }
  return true;
}

function renderPersonnelAdministration() {
  if (!canOpenPersonnelAdministrationView()) return;
  if (canReadCentralPersonnel()) {
    renderPersonnelAdministrationSummary();
    renderPersonnelDirectory();
  }
  if (canReadCostCenters()) {
    renderCostCenterTypes();
    renderCostCenters();
  }
  if (canReadCandidatePreboarding()) renderPersonnelCandidateOverview();
  if (canOpenWorkflowCenter() || canReadPersonnelTasks()) renderPersonnelWorkflowInstanceOverview();
  if (canAccessCustomWorkRuleGovernance() && state.customWorkRuleRegistry) renderCustomWorkRuleRegistry();
  if (canReadCollectiveAgreements() && state.collectiveAgreementRegistry) renderCollectiveAgreementRegistry();
  if (canReadCentralVacations() && state.centralVacationLoadedYear !== null) renderCentralVacations();
  if (canReadDataSubjectRequests()) renderDataSubjectRequests();
}

const PERSONNEL_DASHBOARD_ITEM_IDS = Object.freeze([
  "employees",
  "applications",
  "workflows",
  "tasks",
  "requests",
  "timeTracking",
  "costCenters",
  "ruleDrafts",
  "collectiveAgreements",
  "vacations",
  "dataRequests",
]);

function defaultPersonnelDashboardLayout() {
  return { version: 1, order: [...PERSONNEL_DASHBOARD_ITEM_IDS], hidden: [] };
}

function normalizePersonnelDashboardLayout(value) {
  const known = new Set(PERSONNEL_DASHBOARD_ITEM_IDS);
  const order = Array.isArray(value?.order)
    ? [...new Set(value.order.map(String))].filter((id) => known.has(id))
    : [];
  for (const id of PERSONNEL_DASHBOARD_ITEM_IDS) if (!order.includes(id)) order.push(id);
  const hidden = Array.isArray(value?.hidden)
    ? [...new Set(value.hidden.map(String))].filter((id) => known.has(id))
    : [];
  return { version: 1, order, hidden };
}

function filialDashboardCatalog() {
  const features = state.portalStatus?.installationFeatures || {};
  return [
    { id: "team", symbol: "◎", eyebrow: "Organisation", label: "Teams & Standorte", description: "Team, Farben, Spitznamen und operative Filialdaten verwalten.", view: "personnel", available: true },
    { id: "loans", symbol: "▣", eyebrow: "Leihe", label: "Leihverwaltung", description: "Leihvorgänge und Rücknahmen im freigegebenen Bereich bearbeiten.", view: "loans", available: canReadLoanManagement() },
    { id: "branchOrders", symbol: "▤", eyebrow: "Beschaffung", label: "Filialbestellungen", description: "Bestellgruppen, Ziele und Nachweise im erlaubten Bereich verwalten.", view: "branchOrders", available: canManageBranchOrders() },
    { id: "planning", symbol: "▦", eyebrow: "Einsatzplanung", label: "Dienstplanung", description: "Wochenpläne, Filialeinsätze und Stundenübersicht öffnen.", view: "planning", available: true },
    { id: "vacations", symbol: "☀", eyebrow: "Abwesenheit", label: "Urlaubsplanung", description: "Genehmigte Urlaube im Filialkalender anzeigen und planen.", view: "vacations", available: features.vacation !== false },
  ];
}

function renderFilialDashboard() {
  if (!elements.filialDashboardGrid) return;
  const items = filialDashboardCatalog().filter((item) => item.available);
  elements.filialDashboardGrid.innerHTML = items.map((item) => `
    <button class="personnel-dashboard-card" type="button" data-filial-dashboard-view="${escapeHtmlAttribute(item.view)}">
      <span class="personnel-dashboard-card-symbol" aria-hidden="true">${escapeHtml(item.symbol)}</span>
      <span class="personnel-dashboard-card-copy"><small>${escapeHtml(item.eyebrow)}</small><strong>${escapeHtml(item.label)}</strong><span>${escapeHtml(item.description)}</span></span>
      <span class="personnel-dashboard-card-arrow" aria-hidden="true">→</span>
    </button>`).join("");
}

