function orderedPersonnelDashboardItems(layout = state.personnelDashboardLayout) {
  const normalized = normalizePersonnelDashboardLayout(layout);
  const catalog = new Map(personnelDashboardCatalog().map((item) => [item.id, item]));
  return normalized.order.map((id) => catalog.get(id)).filter((item) => item?.available);
}

function renderPersonnelDashboard() {
  if (!elements.personnelDashboardGrid) return;
  state.personnelDashboardLayout = normalizePersonnelDashboardLayout(state.personnelDashboardLayout);
  const hidden = new Set(state.personnelDashboardLayout.hidden);
  const items = orderedPersonnelDashboardItems().filter((item) => !hidden.has(item.id));
  elements.personnelDashboardGrid.innerHTML = items.length
    ? items.map((item) => `<button class="personnel-dashboard-card" type="button" data-personnel-dashboard-item="${escapeHtmlAttribute(item.id)}">
        <span class="personnel-dashboard-card-symbol" aria-hidden="true">${escapeHtml(item.symbol)}</span>
        <span class="personnel-dashboard-card-copy"><small>${escapeHtml(item.eyebrow)}</small><strong>${escapeHtml(item.label)}</strong><span>${escapeHtml(item.description)}</span></span>
        <span class="personnel-dashboard-card-arrow" aria-hidden="true">→</span>
      </button>`).join("")
    : '<div class="personnel-dashboard-empty"><strong>Keine Kachel eingeblendet</strong><p>Öffne „Dashboard anpassen“, um mindestens einen verfügbaren Arbeitsbereich einzublenden.</p></div>';
}

function renderPersonnelDashboardCustomizer() {
  if (!elements.personnelDashboardCustomizerList) return;
  const layout = normalizePersonnelDashboardLayout(state.personnelDashboardDraftLayout || state.personnelDashboardLayout);
  state.personnelDashboardDraftLayout = layout;
  const hidden = new Set(layout.hidden);
  const items = orderedPersonnelDashboardItems(layout);
  elements.personnelDashboardCustomizerList.innerHTML = items.map((item, index) => `
    <article class="personnel-dashboard-customizer-row">
      <label><input type="checkbox" data-personnel-dashboard-visible="${escapeHtmlAttribute(item.id)}" ${hidden.has(item.id) ? "" : "checked"} /><span><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.eyebrow)}</small></span></label>
      <div>
        <button type="button" data-personnel-dashboard-move="${escapeHtmlAttribute(item.id)}" data-direction="-1" ${index === 0 ? "disabled" : ""} aria-label="${escapeHtmlAttribute(`${item.label} nach vorne verschieben`)}">↑</button>
        <button type="button" data-personnel-dashboard-move="${escapeHtmlAttribute(item.id)}" data-direction="1" ${index === items.length - 1 ? "disabled" : ""} aria-label="${escapeHtmlAttribute(`${item.label} nach hinten verschieben`)}">↓</button>
      </div>
    </article>`).join("");
  updatePersonnelDashboardCustomizerStatus(layout);
}

function updatePersonnelDashboardCustomizerStatus(layout = state.personnelDashboardDraftLayout || state.personnelDashboardLayout) {
  const normalized = normalizePersonnelDashboardLayout(layout);
  const hidden = new Set(normalized.hidden);
  const items = orderedPersonnelDashboardItems(normalized);
  if (elements.personnelDashboardCustomizerStatus) {
    elements.personnelDashboardCustomizerStatus.textContent = `${items.length} verfügbare Arbeitsbereiche · ${items.filter((item) => !hidden.has(item.id)).length} eingeblendet`;
  }
}

function openPersonnelDashboardCustomizer() {
  state.personnelDashboardDraftLayout = normalizePersonnelDashboardLayout(state.personnelDashboardLayout);
  elements.personnelDashboardCustomizer?.classList.remove("hidden");
  elements.personnelDashboardCustomizeButton?.setAttribute("aria-expanded", "true");
  renderPersonnelDashboardCustomizer();
  elements.personnelDashboardCustomizerClose?.focus();
}

function closePersonnelDashboardCustomizer({ restoreFocus = true } = {}) {
  state.personnelDashboardDraftLayout = null;
  elements.personnelDashboardCustomizer?.classList.add("hidden");
  elements.personnelDashboardCustomizeButton?.setAttribute("aria-expanded", "false");
  if (restoreFocus) elements.personnelDashboardCustomizeButton?.focus();
}

function movePersonnelDashboardDraft(itemId, direction) {
  const layout = normalizePersonnelDashboardLayout(state.personnelDashboardDraftLayout || state.personnelDashboardLayout);
  const accessibleIds = orderedPersonnelDashboardItems(layout).map((item) => item.id);
  const currentIndex = accessibleIds.indexOf(itemId);
  const targetId = accessibleIds[currentIndex + direction];
  if (currentIndex < 0 || !targetId) return;
  const left = layout.order.indexOf(itemId);
  const right = layout.order.indexOf(targetId);
  [layout.order[left], layout.order[right]] = [layout.order[right], layout.order[left]];
  state.personnelDashboardDraftLayout = layout;
  renderPersonnelDashboardCustomizer();
  elements.personnelDashboardCustomizerList?.querySelector(`[data-personnel-dashboard-move="${CSS.escape(itemId)}"][data-direction="${direction}"]`)?.focus();
}

function navigateFromPersonnelDashboard(itemId) {
  const item = personnelDashboardCatalog().find((entry) => entry.id === itemId && entry.available);
  if (!item) return;
  if (item.view === "personnelAdministration") setPersonnelAdministrationTab(item.route);
  setView(item.view);
  closeMobileNavigation({ restoreFocus: false });
}

function setPersonnelAdministrationTab(tab) {
  const normalized = canOpenPersonnelAdministrationTab(tab)
    ? tab
    : firstAccessiblePersonnelAdministrationTab();
  if (normalized !== "workflows" && (
    state.personnelLifecycleEditorCatalog
    || state.personnelLifecycleEditorCatalogLoaded
    || state.personnelLifecycleEditorLoading
    || state.personnelLifecycleEditorDraft
    || state.personnelLifecycleEditorValidation
    || state.personnelLifecycleEditorError
    || elements.personnelLifecycleEditorDialog?.open
  )) clearPersonnelLifecycleEditorState("", { closeDialog: true, restoreFocus: false });
  if (normalized !== "tasks" && (
    state.personnelLifecycleAutomationCatalog
    || state.personnelLifecycleAutomationPreview
    || state.personnelLifecycleAutomationCatalogLoaded
    || state.personnelLifecycleAutomationPreviewLoaded
    || state.personnelLifecycleAutomationLoading
    || state.personnelLifecycleAutomationError
  )) clearPersonnelLifecycleAutomationState();
  if (normalized !== "employees" && employeeProfileIsOpen()) closeEmployeeProfile({ restoreFocus: false });
  state.personnelAdministrationTab = normalized;
  document.querySelectorAll("[data-personnel-administration-tab]").forEach((button) => {
    const active = button.dataset.personnelAdministrationTab === normalized;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
    button.tabIndex = active ? 0 : -1;
  });
  document.querySelector(".personnel-administration-tabs")?.classList.toggle("hidden", normalized === "dashboard");
  elements.personnelDashboardSection?.classList.toggle("active", normalized === "dashboard");
  elements.personnelDirectorySection?.classList.toggle("active", normalized === "employees");
  elements.candidatePreboardingSection?.classList.toggle("active", normalized === "applications");
  elements.workflowCenterSection?.classList.toggle("active", normalized === "workflows");
  elements.personnelTasksSection?.classList.toggle("active", normalized === "tasks");
  elements.costCenterSection?.classList.toggle("active", normalized === "costCenters");
  elements.customWorkRulesSection?.classList.toggle("active", normalized === "ruleDrafts");
  elements.collectiveAgreementsSection?.classList.toggle("active", normalized === "collectiveAgreements");
  elements.centralVacationSection?.classList.toggle("active", normalized === "vacations");
  elements.dataSubjectRequestsSection?.classList.toggle("active", normalized === "dataRequests");
  elements.personnelDisplayColumnsButton?.classList.toggle("hidden", normalized !== "employees" || employeeProfileIsOpen());
  if (normalized === "dashboard") renderPersonnelDashboard();
  if (state.currentView === "personnelAdministration") renderContextNavigation();
  if (state.currentView === "personnelAdministration" && ["employees", "costCenters"].includes(normalized)) {
    loadPersonnelAdministration().catch((error) => showToast(error.message, true));
  }
  if (normalized === "applications") loadPersonnelCandidates();
  if ((normalized === "workflows" || normalized === "tasks")
    && canReadPersonnelWorkflowInstances()) {
    loadPersonnelWorkflowInstances().catch((error) => showToast(error.message, true));
  }
  if (normalized === "tasks" && canReadLifecycleOnboardingTasks()) {
    loadPersonnelLifecycleOnboardingTasks().catch((error) => showToast(error.message, true));
  }
  if (normalized === "tasks" && canReadLifecycleOffboardingTasks()) {
    loadPersonnelLifecycleOffboardingTasks().catch((error) => showToast(error.message, true));
  }
  if (normalized === "tasks" && canReadLifecycleInterfaces()) {
    loadPersonnelLifecycleInterfacesCatalog().catch((error) => showToast(error.message, true));
  }
  if (normalized === "tasks" && canReadLifecycleAutomationCatalog()) {
    loadPersonnelLifecycleAutomation().catch((error) => showToast(error.message, true));
  }
  if (normalized === "ruleDrafts") loadCustomWorkRuleRegistry().catch((error) => showToast(error.message, true));
  if (normalized === "collectiveAgreements") loadCollectiveAgreementRegistry().catch((error) => showToast(error.message, true));
  if (normalized === "vacations") loadCentralVacations().catch((error) => showToast(error.message, true));
  if (normalized === "dataRequests") loadDataSubjectRequests().catch((error) => showToast(error.message, true));
}

function populateCostCenterTypeSelect(selectedId = "") {
  if (!elements.costCenterType) return;
  const selected = String(selectedId || "");
  const types = state.costCenterTypes
    .filter((type) => type.active || type.id === selected)
    .sort((left, right) => Number(left.sortOrder) - Number(right.sortOrder)
      || left.name.localeCompare(right.name, "de-AT", { sensitivity: "base" }));
  elements.costCenterType.innerHTML = types.length
    ? types.map((type) => `<option value="${escapeHtmlAttribute(type.id)}">${escapeHtml(type.name)}${type.isBranch ? " · Filialtyp" : ""}${type.active ? "" : " · archiviert"}</option>`).join("")
    : '<option value="">Kein aktiver Typ verfügbar</option>';
  const fallback = types.find((type) => type.code === "other") || types[0] || null;
  elements.costCenterType.value = types.some((type) => type.id === selected) ? selected : fallback?.id || "";
  syncCostCenterTypeHint();
}

function syncCostCenterTypeHint() {
  if (!elements.costCenterTypeHint) return;
  const type = costCenterTypeByKey(elements.costCenterType?.value);
  if (!type) {
    elements.costCenterTypeHint.textContent = "Bitte zuerst einen aktiven Kostenstellentyp anlegen.";
    return;
  }
  const parts = [
    type.isBranch ? "Kann einem Standort zugeordnet werden." : "Keine Filiale; ein Standort wird dafür nicht benötigt.",
    `${type.positionIds.length} Position(en) hinterlegt.`,
  ];
  if (!type.active) parts.push("Dieser Typ ist archiviert.");
  elements.costCenterTypeHint.textContent = parts.join(" ");
}

function openCostCenterModal(costCenter = null) {
  if (!canWriteCostCenters() || !elements.costCenterModal) return;
  state.editingCostCenterId = costCenter?.id ?? null;
  elements.costCenterForm.reset();
  elements.costCenterId.value = costCenter?.id ?? "";
  elements.costCenterCode.value = costCenter?.code || "";
  elements.costCenterCode.disabled = Boolean(costCenter);
  elements.costCenterName.value = costCenter?.name || "";
  populateCostCenterTypeSelect(costCenter?.typeId || costCenter?.type || "");
  elements.costCenterDescription.value = costCenter?.description || "";
  elements.costCenterActive.checked = costCenter?.active ?? true;
  elements.costCenterModalTitle.textContent = costCenter ? "Kostenstelle bearbeiten" : "Kostenstelle anlegen";
  elements.costCenterSubmitButton.textContent = costCenter ? "Kostenstelle speichern" : "Kostenstelle anlegen";
  elements.deactivateCostCenterButton.classList.toggle("hidden", !costCenter?.active);
  elements.costCenterModal.showModal();
}

async function saveCostCenter(event) {
  event.preventDefault();
  if (!canWriteCostCenters()) return;
  const id = state.editingCostCenterId;
  const body = {
    code: elements.costCenterCode.value.trim(),
    name: elements.costCenterName.value.trim(),
    costCenterTypeId: elements.costCenterType.value,
    description: elements.costCenterDescription.value.trim(),
    active: elements.costCenterActive.checked,
  };
  elements.costCenterSubmitButton.disabled = true;
  try {
    await api(id === null ? "/api/cost-centers" : `/api/cost-centers/${encodeURIComponent(id)}`, {
      method: id === null ? "POST" : "PUT",
      body: JSON.stringify(body),
    });
    elements.costCenterModal.close();
    state.personnelAdministrationLoaded = false;
    await loadPersonnelAdministration({ force: true });
    showToast(id === null ? "Kostenstelle wurde angelegt." : "Kostenstelle wurde gespeichert.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.costCenterSubmitButton.disabled = false;
  }
}

async function deactivateCostCenter() {
  const id = state.editingCostCenterId;
  if (id === null || !canWriteCostCenters() || !confirm("Diese Kostenstelle deaktivieren? Bestehende Zuordnungen und historische Daten bleiben erhalten.")) return;
  elements.deactivateCostCenterButton.disabled = true;
  try {
    await api(`/api/cost-centers/${encodeURIComponent(id)}`, { method: "DELETE" });
    elements.costCenterModal.close();
    state.personnelAdministrationLoaded = false;
    await loadPersonnelAdministration({ force: true });
    showToast("Kostenstelle wurde deaktiviert.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.deactivateCostCenterButton.disabled = false;
  }
}

function updateCostCenterTypePositionCount() {
  if (!elements.costCenterTypePositionCount) return;
  const count = state.costCenterTypePositionSelection.size;
  elements.costCenterTypePositionCount.textContent = `${count} ausgewählt`;
  if (elements.costCenterTypePositionHint) {
    elements.costCenterTypePositionHint.textContent = count
      ? "Diese Positionen stehen für Kostenstellen dieses Typs zur Verfügung."
      : "Ohne Auswahl steht für diesen Typ später keine Position zur Verfügung.";
  }
}

function renderCostCenterTypePositionOptions() {
  if (!elements.costCenterTypePositionOptions) return;
  const search = String(elements.costCenterTypePositionSearch?.value || "").trim().toLocaleLowerCase("de-AT");
  const positions = (state.positions || [])
    .filter((position) => !search || String(position.name || "").toLocaleLowerCase("de-AT").includes(search))
    .slice()
    .sort((left, right) => Number(left.sort_order ?? left.sortOrder ?? 0) - Number(right.sort_order ?? right.sortOrder ?? 0)
      || String(left.name || "").localeCompare(String(right.name || ""), "de-AT", { sensitivity: "base" }));
  elements.costCenterTypePositionOptions.innerHTML = positions.length ? positions.map((position) => {
    const id = String(position.id || "");
    return `<label class="cost-center-type-position-option">
      <input type="checkbox" value="${escapeHtmlAttribute(id)}" ${state.costCenterTypePositionSelection.has(id) ? "checked" : ""} />
      <span>${escapeHtml(position.name || id)}</span>
    </label>`;
  }).join("") : '<p class="cost-center-type-position-empty">Keine passende Position gefunden.</p>';
  updateCostCenterTypePositionCount();
}

function openCostCenterTypeModal(type = null) {
  if (!canWriteCostCenters() || !elements.costCenterTypeModal) return;
  state.editingCostCenterTypeId = type?.id || null;
  state.costCenterTypePositionSelection = new Set((type?.positionIds || []).map(String));
  elements.costCenterTypeForm.reset();
  elements.costCenterTypeId.value = type?.id || "";
  elements.costCenterTypeCode.value = type?.code || "";
  elements.costCenterTypeCode.disabled = Boolean(type);
  elements.costCenterTypeName.value = type?.name || "";
  elements.costCenterTypeDescription.value = type?.description || "";
  elements.costCenterTypeIsBranch.checked = Boolean(type?.isBranch);
  elements.costCenterTypeActive.checked = type?.active ?? true;
  elements.costCenterTypePositionSearch.value = "";
  elements.costCenterTypeModalTitle.textContent = type ? "Kostenstellentyp bearbeiten" : "Kostenstellentyp anlegen";
  elements.costCenterTypeSubmitButton.textContent = type ? "Typ speichern" : "Typ anlegen";
  elements.deactivateCostCenterTypeButton.classList.toggle("hidden", !type?.active);
  renderCostCenterTypePositionOptions();
  elements.costCenterTypeModal.showModal();
}

async function saveCostCenterType(event) {
  event.preventDefault();
  if (!canWriteCostCenters()) return;
  const id = state.editingCostCenterTypeId;
  const body = {
    code: elements.costCenterTypeCode.value.trim().toLowerCase(),
    name: elements.costCenterTypeName.value.trim(),
    description: elements.costCenterTypeDescription.value.trim(),
    isBranch: elements.costCenterTypeIsBranch.checked,
    active: elements.costCenterTypeActive.checked,
    positionIds: [...state.costCenterTypePositionSelection],
  };
  elements.costCenterTypeSubmitButton.disabled = true;
  try {
    await api(id ? `/api/cost-center-types/${encodeURIComponent(id)}` : "/api/cost-center-types", {
      method: id ? "PUT" : "POST",
      body: JSON.stringify(body),
    });
    elements.costCenterTypeModal.close();
    state.personnelAdministrationLoaded = false;
    await loadPersonnelAdministration({ force: true });
    showToast(id ? "Kostenstellentyp wurde gespeichert." : "Kostenstellentyp wurde angelegt.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.costCenterTypeSubmitButton.disabled = false;
  }
}

async function deactivateCostCenterType() {
  const id = state.editingCostCenterTypeId;
  if (!id || !canWriteCostCenters()
    || !confirm("Diesen Kostenstellentyp archivieren? Verwendete Typen müssen zuerst von allen aktiven Kostenstellen gelöst werden.")) return;
  elements.deactivateCostCenterTypeButton.disabled = true;
  try {
    await api(`/api/cost-center-types/${encodeURIComponent(id)}`, { method: "DELETE" });
    elements.costCenterTypeModal.close();
    state.personnelAdministrationLoaded = false;
    await loadPersonnelAdministration({ force: true });
    showToast("Kostenstellentyp wurde archiviert.");
  } catch (error) {
    showToast(error.message, true);
  } finally {
    elements.deactivateCostCenterTypeButton.disabled = false;
  }
}

function renderEmployees() {
  const showInactive = state.data?.settings?.show_inactive_personnel !== "0";
  const employees = sortedEmployeesForDisplay(showInactive ? state.allEmployees : state.allEmployees.filter((employee) => employee.active));
  if (employeeProfileIsOpen() && state.employeeProfileHost === "team"
    && !employees.some((employee) => (
      String(employee.personnel_number || "") === state.employeeProfileEmployeeNumber
      && employee.personnel_profile_access?.available === true
    ))) closeEmployeeProfile({ restoreFocus: false });
  const canEditFull = !state.portalStatus?.portalEnabled || state.portalSession?.user?.permissions?.includes("employees:write");
  const canEditDisplay = canEditFull || state.portalSession?.user?.permissions?.includes("employees:display:write");
  const canEditNickname = canEditFull || state.portalSession?.user?.permissions?.includes("employees:nickname:write");
  const canReadPersonnelRecord = personnelRecordAvailableInUi();
  const recordButtonLabel = personnelRecordButtonLabel();
  const columns = normalizeEmployeeDisplayColumns(state.employeeDisplayColumns)
    .map((id) => availableEmployeeDisplayColumns().find((column) => column.id === id))
    .filter(Boolean);
  state.employeeDisplayColumns = columns.map((column) => column.id);
  if (elements.employeeTableHead) elements.employeeTableHead.innerHTML = employeeDisplayHeader(columns);
  applyEmployeeDisplayTableLayout(elements.employeeTable, columns);
  elements.employeeTableBody.innerHTML = employees.map((employee) => {
    const canOpenProfile = canOpenTeamEmployeeProfileFoundation(employee.personnel_number);
    return `<tr>
      ${columns.map((column) => `<td data-label="${escapeHtmlAttribute(column.label)}">${employeeDisplayCell(employee, column)}</td>`).join("")}
      <td><span class="table-actions">${canOpenProfile ? `<button type="button" class="edit-button" data-team-employee-profile="${escapeHtmlAttribute(employee.personnel_number)}" data-team-employee-profile-access="true">Profil</button>` : ""}${canReadPersonnelRecord ? `<button type="button" class="edit-button" data-personnel-record="${escapeHtml(employee.personnel_number)}">${recordButtonLabel}</button>` : ""}${canEditDisplay ? `<button type="button" class="edit-button" data-edit-employee="${escapeHtml(employee.personnel_number)}">${canEditFull ? "Bearbeiten" : canEditNickname ? "Darstellung ändern" : "Farbe ändern"}</button>` : ""}</span></td>
    </tr>`;
  }).join("");
}

function renderLocations() {
  if (!elements.locationList) return;
  const locations = state.locations || [];
  const permissions = state.portalSession?.user?.permissions || [];
  const localAccess = !state.portalStatus?.portalEnabled;
  const canEditLocations = localAccess || permissions.includes("locations:write")
    || permissions.includes("locations:operational:write");
  const canEditDepartments = localAccess || permissions.includes("departments:write");
  elements.departmentLocation.innerHTML = locations.map((location) =>
    `<option value="${escapeHtml(location.id)}">${escapeHtml(location.id)} · ${escapeHtml(location.name)}</option>`,
  ).join("");
  if (!elements.departmentLocation.value && state.locationId) elements.departmentLocation.value = state.locationId;
  if (!state.editingLocationId) setLocationDayFields(currentLocation()?.day_settings || locations[0]?.day_settings || {});
  elements.locationList.innerHTML = locations.length ? locations.map((location) => {
    const departments = location.departments || [];
    const openingSummary = planningDayKeys.filter((day) => location.day_settings?.[day]?.open !== false).map((day) => `${preferredDayLabels[day]?.slice(0, 2) || (day === "saturday" ? "Sa" : day.slice(0, 2))} ${location.day_settings?.[day]?.start || "–"}–${location.day_settings?.[day]?.end || "–"}`).join(" · ");
    return `<article class="location-card">
      <div class="location-card-head">
        <div><strong>${escapeHtml(location.id)} · ${escapeHtml(location.name)}</strong><small>${location.active ? "Aktiv" : "Inaktiv"} · ${departments.length} Abteilung(en) · Mindestbesetzung Filiale: ${Number(location.min_staff || 0)} · Zeiterfassung ${location.time_tracking_enabled ? "aktiv" : "aus"}</small><small>Kostenstelle: ${escapeHtml([location.cost_center_code ?? location.costCenterCode, location.cost_center_name ?? location.costCenterName].filter(Boolean).join(" · ") || "noch nicht zugeordnet")} · ${escapeHtml(openingSummary)}</small></div>
        ${canEditLocations ? `<button type="button" class="edit-button" data-edit-location="${escapeHtml(location.id)}">Filiale bearbeiten</button>` : ""}
      </div>
      <div class="department-list">${
        departments.length ? departments.map((department) => `
          <div class="department-item">
            <span>${escapeHtml(department.name)}${department.active ? "" : " · inaktiv"} · Mindestbesetzung: ${Number(department.min_staff || 0)}</span>
            ${canEditDepartments ? `<button type="button" class="edit-button" data-edit-department="${department.id}">Bearbeiten</button>` : ""}
          </div>
        `).join("") : '<div class="empty-options">Keine Abteilungen angelegt.</div>'
      }</div>
    </article>`;
  }).join("") : '<div class="empty-options">Noch keine Filiale angelegt.</div>';
}

function renderPositions() {
  if (!elements.positionList) return;
  const positions = state.positions || [];
  const canEdit = !state.portalStatus?.portalEnabled || state.portalSession?.user?.permissions?.includes("positions:write");
  elements.positionList.innerHTML = positions.length ? positions.map((position) => `
    <div class="position-item">
      <div><strong>${escapeHtml(position.name)}</strong><small>${position.builtin ? "Standardposition · fix" : "Eigene Position"}</small></div>
      <div class="position-actions">${
        position.builtin
          ? '<span class="status-badge">Fix</span>'
          : canEdit
            ? `<button type="button" class="edit-button" data-edit-position="${escapeHtml(position.id)}">Bearbeiten</button><button type="button" class="delete-option" data-delete-position="${escapeHtml(position.id)}">Löschen</button>`
            : ""
      }</div>
    </div>
  `).join("") : '<div class="empty-options">Keine Positionen angelegt.</div>';
}

function renderSettings() {
  const settings = state.data.settings;
  const vacationSettings = state.vacationData?.settings || settings;
  const branding = applyShellBranding(hasManagementBrandingAccess() ? {} : settings);
  elements.brandingCompanyName.value = branding.companyName;
  elements.brandingAdminEmail.value = branding.adminEmail;
  elements.brandingLogoUrl.value = branding.logoUrl;
  elements.brandingIconUrl.value = branding.iconUrl;
  elements.brandingLogoAlt.value = branding.logoAlt;
  state.brandingFormDirty = false;
  renderBrandingKits();
  document.querySelector("#pdfTitleSetting").value = settings.pdf_title;
  document.querySelector("#pdfFilenamePrefix").value = settings.pdf_filename_prefix || settings.pdf_title || "Dienstplan";
  document.querySelector("#pdfFilenameIncludeKw").checked = settings.pdf_filename_include_kw !== "0";
  document.querySelector("#pdfFilenameIncludeTimestamp").checked = settings.pdf_filename_include_timestamp === "1";
  document.querySelector("#vacationPdfTitleSetting").value = vacationSettings.vacation_pdf_title || "Urlaubsplanung";
  document.querySelector("#vacationPdfFilenamePrefix").value = vacationSettings.vacation_pdf_filename_prefix || vacationSettings.vacation_pdf_title || "Urlaubsplanung";
  document.querySelector("#vacationPdfFilenameIncludePeriod").checked = vacationSettings.vacation_pdf_filename_include_period !== "0";
  document.querySelector("#vacationPdfFilenameIncludeTimestamp").checked = vacationSettings.vacation_pdf_filename_include_timestamp === "1";
  document.querySelector("#vacationPdfShowBalance").checked = vacationSettings.vacation_pdf_show_balance !== "0";
  document.querySelector("#vacationPdfBalanceShowEntitlement").checked = vacationSettings.vacation_pdf_balance_show_entitlement !== "0";
  document.querySelector("#vacationPdfBalanceShowPlanned").checked = vacationSettings.vacation_pdf_balance_show_planned !== "0";
  document.querySelector("#vacationPdfBalanceShowConsumed").checked = vacationSettings.vacation_pdf_balance_show_consumed === "1";
  document.querySelector("#vacationPdfCalendarStyle").value = vacationSettings.vacation_pdf_calendar_style || "bars";
  document.querySelector("#toastDuration").value = settings.toast_duration || "medium";
  document.querySelector("#showInactivePersonnel").checked = settings.show_inactive_personnel !== "0";
  document.querySelector("#showSaturdayServiceStats").checked = settings.show_saturday_service_stats !== "0";
  document.querySelector("#externalBackupEnabled").checked = settings.external_backup_enabled !== "0";
  document.querySelector("#backupDirectory").value = settings.backup_directory || "";
  document.querySelector("#backupIntervalHours").value = settings.backup_interval_hours || "2";
  const allowPastWeekEditing = document.querySelector("#allowPastWeekEditing");
  allowPastWeekEditing.checked = state.portalStatus?.portalEnabled === true
    ? state.allowPastWeekEditing
    : settings.allow_past_week_editing === "1";
  allowPastWeekEditing.disabled = state.portalStatus?.portalEnabled === true
    && (!state.portalSession?.user?.permissions?.includes("schedule:write")
      || !state.portalSession?.user?.permissions?.includes("settings:write"));
  elements.currentWeekAutoLock.checked = settings.current_week_auto_lock !== "0";
  elements.currentWeekLockMode.value = settings.current_week_lock_mode || "closing";
  elements.currentWeekLockDay.value = settings.current_week_lock_day || "saturday";
  elements.currentWeekLockTime.value = settings.current_week_lock_time || "17:00";
  updateWeekLockSettings();
  if (elements.vacationHrApprovalRequired) {
    elements.vacationHrApprovalRequired.checked = Boolean(state.workflowSettings?.vacationHrApprovalRequired ?? state.portalStatus?.workflow?.vacationHrApprovalRequired);
    elements.workflowSettingsHint.textContent = "Die Einstellung kann von Personalleitung oder höher geändert werden.";
  }
  document.querySelector("#breakRuleEnabled").checked = settings.break_rule_enabled === "1";
  document.querySelector("#breakAfterHours").value = Number(settings.break_after_minutes) / 60;
  document.querySelector("#breakDuration").value = settings.break_duration_minutes;
  document.querySelector("#saturdayBonusEnabled").checked = settings.saturday_bonus_enabled === "1";
  document.querySelector("#saturdayBonusFrom").value = settings.saturday_bonus_from;
  document.querySelector("#saturdayBonusFactor").value = settings.saturday_bonus_factor;
  document.querySelector("#showSunday").checked = settings.show_sunday === "1";
  elements.rememberLastScheduleOverallPlan.checked = settings.remember_last_schedule_overall_plan !== "0";
  elements.rememberLastVacationOverallPlan.checked = settings.remember_last_vacation_overall_plan !== "0";
  applyAppFontScalePercent(state.appFontScalePercent);
  localStorage.setItem(rememberContextCacheKey("planning"), elements.rememberLastScheduleOverallPlan.checked ? "1" : "0");
  localStorage.setItem(rememberContextCacheKey("vacations"), elements.rememberLastVacationOverallPlan.checked ? "1" : "0");
  renderPortalAccessState();
  updatePdfPreview();
}

function updateWeekLockSettings() {
  const active = elements.currentWeekAutoLock.checked;
  const manual = elements.currentWeekLockMode.value === "manual";
  elements.currentWeekLockSettings.classList.toggle("disabled-setting", !active);
  elements.currentWeekLockMode.disabled = !active;
  elements.manualWeekLockFields.classList.toggle("hidden", !active || !manual);
  elements.currentWeekLockTime.min = elements.currentWeekLockDay.value === "friday" ? "18:00" : "00:00";
  const settings = state.data?.settings || {};
  const openDays = planningDayKeys.filter((day) => settings[`${day}_open`] !== "0");
  const lastDay = openDays.at(-1) || "friday";
  const label = fixedDayLabels[lastDay] || lastDay;
  const time = settings[`${lastDay}_end_time`] || "18:00";
  elements.currentWeekLockHint.textContent = manual ? "Manuell möglich von Freitag 18:00 Uhr bis Sonntag 23:00 Uhr." : `Automatisch nach der letzten Schließzeit: ${label}, ${time} Uhr.`;
}

function renderPortalAccessState() {
  const status = state.portalStatus || {};
  if (elements.adminAccessModeLabel) elements.adminAccessModeLabel.textContent = "Geschützter Zugang";
  elements.employeePortalLink?.classList.toggle("hidden", status.portalEnabled !== true);
  elements.portalLogoutButton?.classList.toggle("hidden", status.portalEnabled !== true);
}

function portalRoleAssignableInUi(actorRole, roleId) {
  if (roleId === "developer") return false;
  if (!actorRole || actorRole === "developer") return true;
  if (actorRole === "admin") return roleId !== "it_admin";
  if (actorRole === "it_admin") return ["employee", "location_planner", "manager", "department_manager"].includes(roleId);
  if (actorRole === "hr") return ["employee", "location_planner", "manager", "department_manager"].includes(roleId);
  return actorRole === "manager" && roleId === "department_manager";
}

function portalUserManageableInUi(actorRole, user) {
  if (user.roleLocked || user.role === "developer") return false;
  if (!actorRole || actorRole === "developer") return true;
  if (actorRole === "admin") return user.role !== "it_admin";
  if (actorRole === "it_admin") return ["employee", "location_planner", "manager", "department_manager"].includes(user.role);
  if (actorRole === "hr") return ["employee", "location_planner", "manager", "department_manager"].includes(user.role);
  return actorRole === "manager" && user.role === "department_manager";
}

function permissionEligibleForRole(permission, role) {
  if (!permission || !role) return false;
  return !Array.isArray(permission.eligibleRoles) || permission.eligibleRoles.includes(role);
}

function lifecycleRightsDependency(permissionId, requiredPermissionId, label) {
  return Object.freeze({
    permissionId,
    requiredPermissionId,
    removedMessage: `${label} wurde ebenfalls entzogen, weil das erforderliche Leserecht fehlt.`,
    unavailableMessage: `${label} kann ohne verwaltbares Leserecht nicht vergeben werden.`,
    addedMessage: "Das erforderliche Lifecycle-Leserecht wurde automatisch ergänzt.",
  });
}

